import React, { useState, useMemo } from 'react';
import { DocumentMetadata, ProcessAnalysis, DocumentType } from './types';
import { analyzeProcessText } from './services/geminiService';
import { DocumentCard } from './components/DocumentCard';
import { DocumentDetail } from './components/DocumentDetail';
import { 
  Search, 
  Filter, 
  Upload, 
  Loader2, 
  Gavel, 
  FileText, 
  Menu,
  ChevronDown,
  LayoutGrid,
  AlertCircle
} from 'lucide-react';

const App: React.FC = () => {
  const [inputText, setInputText] = useState('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<ProcessAnalysis | null>(null);
  const [selectedDoc, setSelectedDoc] = useState<DocumentMetadata | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [activeFilter, setActiveFilter] = useState<string>('all');
  const [error, setError] = useState<string | null>(null);

  const handleAnalyze = async () => {
    if (!inputText.trim()) return;
    setIsAnalyzing(true);
    setError(null);
    try {
      const result = await analyzeProcessText(inputText);
      setAnalysis(result);
    } catch (err: any) {
      setError('Erro ao processar o texto. Verifique se o formato está correto.');
      console.error(err);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const filteredDocs = useMemo(() => {
    if (!analysis) return [];
    return analysis.documentos.filter(doc => {
      const matchesSearch = 
        doc.titulo_resumido.toLowerCase().includes(searchQuery.toLowerCase()) ||
        doc.texto_integral.toLowerCase().includes(searchQuery.toLowerCase()) ||
        doc.parte_apresentante.toLowerCase().includes(searchQuery.toLowerCase()) ||
        doc.ref_incidente.includes(searchQuery);

      const matchesFilter = activeFilter === 'all' || doc.tipo_documento_principal === activeFilter;

      return matchesSearch && matchesFilter;
    });
  }, [analysis, searchQuery, activeFilter]);

  const docTypes = useMemo(() => {
    if (!analysis) return [];
    return Array.from(new Set(analysis.documentos.map(d => d.tipo_documento_principal)));
  }, [analysis]);

  const incidentSiblings = useMemo(() => {
    if (!selectedDoc || !analysis) return [];
    return analysis.documentos.filter(d => d.ref_incidente === selectedDoc.ref_incidente);
  }, [selectedDoc, analysis]);

  if (!analysis && !isAnalyzing) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6">
        <div className="w-full max-w-3xl space-y-8 animate-in slide-in-from-bottom-4 duration-500">
          <div className="text-center">
            <div className="inline-flex items-center justify-center p-3 bg-blue-600 rounded-2xl shadow-lg mb-4">
              <Gavel className="w-10 h-10 text-white" />
            </div>
            <h1 className="text-4xl font-extrabold text-slate-900 tracking-tight">Citius Analytics Pro</h1>
            <p className="mt-3 text-lg text-slate-600 max-w-lg mx-auto leading-relaxed">
              Cole o texto integral da exportação do processo para segmentar e analisar automaticamente todas as peças processuais.
            </p>
          </div>

          <div className="bg-white p-8 rounded-2xl shadow-xl border border-slate-200">
            <textarea
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              placeholder="Cole aqui o texto do PDF do Citius (Capa + Índice + Documentos)..."
              className="w-full h-80 p-4 border rounded-xl focus:ring-4 focus:ring-blue-100 focus:border-blue-500 outline-none transition-all resize-none font-mono text-sm bg-slate-50 border-slate-200"
            />

            {error && (
              <div className="mt-4 flex items-center p-3 bg-red-50 border border-red-100 text-red-700 rounded-lg text-sm">
                <AlertCircle className="w-4 h-4 mr-2" />
                {error}
              </div>
            )}

            <button
              onClick={handleAnalyze}
              disabled={!inputText.trim()}
              className="w-full mt-6 py-4 px-6 bg-blue-600 text-white font-bold rounded-xl hover:bg-blue-700 active:scale-[0.98] transition-all flex items-center justify-center space-x-2 disabled:opacity-50 disabled:cursor-not-allowed shadow-lg shadow-blue-200"
            >
              <Upload className="w-5 h-5" />
              <span>Iniciar Análise Inteligente</span>
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 text-center">
            <div className="p-4 rounded-xl bg-white/50 border border-slate-200">
              <div className="text-blue-600 font-bold mb-1">Segmentação</div>
              <div className="text-xs text-slate-500">Divisão automática baseada no índice do tribunal</div>
            </div>
            <div className="p-4 rounded-xl bg-white/50 border border-slate-200">
              <div className="text-blue-600 font-bold mb-1">Metadados</div>
              <div className="text-xs text-slate-500">Extração de partes, mandatários e referências</div>
            </div>
            <div className="p-4 rounded-xl bg-white/50 border border-slate-200">
              <div className="text-blue-600 font-bold mb-1">Sumários</div>
              <div className="text-xs text-slate-500">Resumo jurídico conciso de cada documento</div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (isAnalyzing) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 space-y-8">
        <div className="relative">
          <div className="w-24 h-24 border-8 border-blue-100 border-t-blue-600 rounded-full animate-spin"></div>
          <Gavel className="absolute inset-0 m-auto w-8 h-8 text-blue-600" />
        </div>
        <div className="text-center space-y-3">
          <h2 className="text-2xl font-bold text-slate-900">Analisando Processo</h2>
          <p className="text-slate-500 flex items-center justify-center">
            <Loader2 className="w-4 h-4 animate-spin mr-2" />
            Lendo índice e peças judiciais...
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      {/* Navbar */}
      <header className="sticky top-0 z-30 bg-white border-b shadow-sm px-6 py-3 flex items-center justify-between">
        <div className="flex items-center space-x-3">
          <div className="p-1.5 bg-blue-600 rounded-lg">
            <Gavel className="w-5 h-5 text-white" />
          </div>
          <div>
            <h1 className="text-sm font-black text-slate-900 uppercase tracking-tight">Citius Analytics Pro</h1>
            <p className="text-[10px] text-slate-500 font-bold leading-none">{analysis?.numero_processo}</p>
          </div>
        </div>

        <div className="flex-1 max-w-xl mx-8 relative hidden md:block">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          <input
            type="text"
            placeholder="Pesquisar nos documentos, partes ou texto..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-2 bg-gray-100 border-transparent focus:bg-white focus:border-blue-500 rounded-lg text-sm transition-all"
          />
        </div>

        <div className="flex items-center space-x-2">
          <button 
            onClick={() => { setAnalysis(null); setInputText(''); }}
            className="px-4 py-2 text-xs font-bold text-gray-600 hover:bg-gray-100 rounded-lg transition-colors border"
          >
            Novo Processo
          </button>
        </div>
      </header>

      {/* Main Layout */}
      <div className="flex-1 flex overflow-hidden">
        {/* Sidebar Filters */}
        <aside className="w-64 bg-white border-r hidden lg:flex flex-col p-6 space-y-6 overflow-y-auto">
          <div>
            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center">
              <Filter className="w-3 h-3 mr-2" /> Filtros
            </h3>
            <div className="space-y-1">
              <button
                onClick={() => setActiveFilter('all')}
                className={`w-full text-left px-3 py-2 rounded-lg text-sm font-medium transition-colors ${
                  activeFilter === 'all' ? 'bg-blue-50 text-blue-700' : 'text-gray-600 hover:bg-gray-50'
                }`}
              >
                Todos os Documentos
              </button>
              {docTypes.map(type => (
                <button
                  key={type}
                  onClick={() => setActiveFilter(type)}
                  className={`w-full text-left px-3 py-2 rounded-lg text-sm font-medium transition-colors ${
                    activeFilter === type ? 'bg-blue-50 text-blue-700' : 'text-gray-600 hover:bg-gray-50'
                  }`}
                >
                  {type}
                </button>
              ))}
            </div>
          </div>

          <div className="pt-6 border-t">
            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center">
              <LayoutGrid className="w-3 h-3 mr-2" /> Tribunais
            </h3>
            <div className="p-3 bg-gray-50 rounded-lg border text-xs">
              <div className="font-bold text-gray-900 mb-1">{analysis?.tribunal}</div>
              <div className="text-gray-500">{analysis?.juizo}</div>
            </div>
          </div>
        </aside>

        {/* Content Area */}
        <main className="flex-1 overflow-y-auto p-8 bg-gray-50/50">
          <div className="max-w-7xl mx-auto">
            <div className="flex items-center justify-between mb-8">
              <div>
                <h2 className="text-2xl font-bold text-slate-900">Peças Processuais</h2>
                <p className="text-slate-500 text-sm">Listagem segmentada por incidentes e submissões.</p>
              </div>
              <div className="flex items-center space-x-3">
                <span className="text-xs font-medium text-slate-500 bg-white border px-3 py-1.5 rounded-full shadow-sm">
                  {filteredDocs.length} documentos encontrados
                </span>
              </div>
            </div>

            {filteredDocs.length > 0 ? (
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                {filteredDocs.map(doc => (
                  <DocumentCard 
                    key={doc.id_documento} 
                    doc={doc} 
                    onClick={setSelectedDoc} 
                  />
                ))}
              </div>
            ) : (
              <div className="flex flex-col items-center justify-center py-20 bg-white rounded-2xl border border-dashed border-gray-300">
                <FileText className="w-12 h-12 text-gray-300 mb-4" />
                <h3 className="text-lg font-semibold text-gray-600">Nenhum documento corresponde aos filtros</h3>
                <p className="text-gray-400 text-sm">Tente ajustar a pesquisa ou os filtros laterais.</p>
              </div>
            )}
          </div>
        </main>
      </div>

      {/* Document Detail View */}
      {selectedDoc && (
        <DocumentDetail 
          doc={selectedDoc} 
          onClose={() => setSelectedDoc(null)} 
          siblings={incidentSiblings}
          onSelectSibling={setSelectedDoc}
        />
      )}
    </div>
  );
};

