import * as pdfjsLib from 'pdfjs-dist';

// Configuração do worker necessária para o pdf.js via ESM
pdfjsLib.GlobalWorkerOptions.workerSrc = `https://esm.sh/pdfjs-dist@${pdfjsLib.version}/build/pdf.worker.min.mjs`;

export const extractTextFromPdf = async (file: File): Promise<string> => {
  const arrayBuffer = await file.arrayBuffer();
  const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
  let fullText = "";

  for (let i = 1; i <= pdf.numPages; i++) {
    const page = await pdf.getPage(i);
    const textContent = await page.getTextContent();
    const pageText = textContent.items
      .map((item: any) => item.str)
      .join(" ");

    // Adicionamos um marcador de página para ajudar a IA na segmentação
    fullText += `\n--- PÁGINA ${i} ---\n${pageText}\n`;
  }

  return fullText;
};

import React, { useState, useMemo, useRef } from 'react';
import { DocumentMetadata, ProcessAnalysis, DocumentType } from './types';
import { analyzeProcessText } from './services/geminiService';
import { extractTextFromPdf } from './services/pdfService';
import { DocumentCard } from './components/DocumentCard';
import { DocumentDetail } from './components/DocumentDetail';
import { 
  Search, 
  Filter, 
  Upload, 
  Loader2, 
  Gavel, 
  FileText, 
  Menu,
  ChevronDown,
  LayoutGrid,
  AlertCircle,
  FileUp,
  X
} from 'lucide-react';

const App: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStep, setProcessingStep] = useState<'extracting' | 'analyzing' | null>(null);
  const [analysis, setAnalysis] = useState<ProcessAnalysis | null>(null);
  const [selectedDoc, setSelectedDoc] = useState<DocumentMetadata | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [activeFilter, setActiveFilter] = useState<string>('all');
  const [error, setError] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile && selectedFile.type === 'application/pdf') {
      setFile(selectedFile);
      setError(null);
    } else if (selectedFile) {
      setError('Por favor, selecione apenas ficheiros PDF.');
    }
  };

  const handleAnalyze = async () => {
    if (!file) return;

    setIsProcessing(true);
    setError(null);

    try {
      setProcessingStep('extracting');
      const extractedText = await extractTextFromPdf(file);

      setProcessingStep('analyzing');
      const result = await analyzeProcessText(extractedText);
      setAnalysis(result);
    } catch (err: any) {
      console.error(err);
      setError('Erro ao processar o ficheiro. Certifique-se que o PDF não está protegido por palavra-passe.');
    } finally {
      setIsProcessing(false);
      setProcessingStep(null);
    }
  };

  const filteredDocs = useMemo(() => {
    if (!analysis) return [];
    return analysis.documentos.filter(doc => {
      const matchesSearch = 
        doc.titulo_resumido.toLowerCase().includes(searchQuery.toLowerCase()) ||
        doc.texto_integral.toLowerCase().includes(searchQuery.toLowerCase()) ||
        doc.parte_apresentante.toLowerCase().includes(searchQuery.toLowerCase()) ||
        doc.ref_incidente.includes(searchQuery);

      const matchesFilter = activeFilter === 'all' || doc.tipo_documento_principal === activeFilter;

      return matchesSearch && matchesFilter;
    });
  }, [analysis, searchQuery, activeFilter]);

  const docTypes = useMemo(() => {
    if (!analysis) return [];
    return Array.from(new Set(analysis.documentos.map(d => d.tipo_documento_principal)));
  }, [analysis]);

  const incidentSiblings = useMemo(() => {
    if (!selectedDoc || !analysis) return [];
    return analysis.documentos.filter(d => d.ref_incidente === selectedDoc.ref_incidente);
  }, [selectedDoc, analysis]);

  if (!analysis && !isProcessing) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6">
        <div className="w-full max-w-2xl space-y-8 animate-in slide-in-from-bottom-4 duration-500">
          <div className="text-center">
            <div className="inline-flex items-center justify-center p-3 bg-blue-600 rounded-2xl shadow-lg mb-4">
              <Gavel className="w-10 h-10 text-white" />
            </div>
            <h1 className="text-4xl font-extrabold text-slate-900 tracking-tight">Citius Analytics Pro</h1>
            <p className="mt-3 text-lg text-slate-600 max-w-lg mx-auto leading-relaxed">
              Carregue o PDF de exportação do Citius para análise inteligente imediata.
            </p>
          </div>

          <div className="bg-white p-8 rounded-2xl shadow-xl border border-slate-200">
            <div 
              onClick={() => fileInputRef.current?.click()}
              onDragOver={(e) => { e.preventDefault(); e.stopPropagation(); }}
              onDrop={(e) => {
                e.preventDefault();
                e.stopPropagation();
                const droppedFile = e.dataTransfer.files[0];
                if (droppedFile?.type === 'application/pdf') {
                  setFile(droppedFile);
                  setError(null);
                }
              }}
              className={`border-2 border-dashed rounded-xl p-12 flex flex-col items-center justify-center transition-all cursor-pointer ${
                file ? 'border-blue-400 bg-blue-50' : 'border-slate-300 hover:border-blue-400 hover:bg-slate-50'
              }`}
            >
              <input 
                type="file" 
                ref={fileInputRef} 
                className="hidden" 
                accept=".pdf" 
                onChange={handleFileChange} 
              />

              {file ? (
                <div className="text-center">
                  <div className="bg-blue-600 p-3 rounded-full inline-flex mb-4">
                    <FileText className="w-8 h-8 text-white" />
                  </div>
                  <h3 className="font-bold text-slate-900">{file.name}</h3>
                  <p className="text-xs text-slate-500">{(file.size / 1024 / 1024).toFixed(2)} MB</p>
                  <button 
                    onClick={(e) => { e.stopPropagation(); setFile(null); }}
                    className="mt-4 text-xs font-bold text-red-500 flex items-center justify-center mx-auto hover:text-red-700"
                  >
                    <X className="w-3 h-3 mr-1" /> Remover ficheiro
                  </button>
                </div>
              ) : (
                <div className="text-center">
                  <FileUp className="w-12 h-12 text-slate-300 mb-4 mx-auto" />
                  <p className="text-slate-600 font-medium">Arraste o PDF aqui ou clique para procurar</p>
                  <p className="text-xs text-slate-400 mt-2">Apenas exportações do Citius / Tribunais</p>
                </div>
              )}
            </div>

            {error && (
              <div className="mt-4 flex items-center p-3 bg-red-50 border border-red-100 text-red-700 rounded-lg text-sm">
                <AlertCircle className="w-4 h-4 mr-2" />
                {error}
              </div>
            )}

            <button
              onClick={handleAnalyze}
              disabled={!file}
              className="w-full mt-6 py-4 px-6 bg-blue-600 text-white font-bold rounded-xl hover:bg-blue-700 active:scale-[0.98] transition-all flex items-center justify-center space-x-2 disabled:opacity-50 disabled:cursor-not-allowed shadow-lg shadow-blue-200"
            >
              <Upload className="w-5 h-5" />
              <span>Analisar Processo</span>
            </button>
          </div>

          <div className="flex justify-center space-x-8 text-xs text-slate-400 font-medium uppercase tracking-widest">
            <span>Privacidade Local</span>
            <span className="text-slate-200">•</span>
            <span>Extração de Texto OCR</span>
            <span className="text-slate-200">•</span>
            <span>IA Jurídica PT</span>
          </div>
        </div>
      </div>
    );
  }

  if (isProcessing) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 space-y-8">
        <div className="relative">
          <div className="w-24 h-24 border-8 border-blue-100 border-t-blue-600 rounded-full animate-spin"></div>
          <Gavel className="absolute inset-0 m-auto w-8 h-8 text-blue-600" />
        </div>
        <div className="text-center space-y-3">
          <h2 className="text-2xl font-bold text-slate-900">
            {processingStep === 'extracting' ? 'Extraindo Texto do PDF' : 'Analisando Estrutura Jurídica'}
          </h2>
          <p className="text-slate-500 flex items-center justify-center">
            <Loader2 className="w-4 h-4 animate-spin mr-2" />
            {processingStep === 'extracting' 
              ? 'Processando as páginas localmente...' 
              : 'A IA está a segmentar e resumir os documentos...'}
          </p>
          <div className="w-64 h-1.5 bg-gray-200 rounded-full overflow-hidden mx-auto mt-4">
            <div className={`h-full bg-blue-600 transition-all duration-1000 ${processingStep === 'extracting' ? 'w-1/3' : 'w-2/3'}`}></div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      {/* Navbar */}
      <header className="sticky top-0 z-30 bg-white border-b shadow-sm px-6 py-3 flex items-center justify-between">
        <div className="flex items-center space-x-3">
          <div className="p-1.5 bg-blue-600 rounded-lg">
            <Gavel className="w-5 h-5 text-white" />
          </div>
          <div>
            <h1 className="text-sm font-black text-slate-900 uppercase tracking-tight">Citius Analytics Pro</h1>
            <p className="text-[10px] text-slate-500 font-bold leading-none">{analysis?.numero_processo || 'Processo em análise'}</p>
          </div>
        </div>

        <div className="flex-1 max-w-xl mx-8 relative hidden md:block">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          <input
            type="text"
            placeholder="Pesquisar nos documentos, partes ou texto..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-2 bg-gray-100 border-transparent focus:bg-white focus:border-blue-500 rounded-lg text-sm transition-all"
          />
        </div>

        <div className="flex items-center space-x-2">
          <button 
            onClick={() => { setAnalysis(null); setFile(null); }}
            className="px-4 py-2 text-xs font-bold text-gray-600 hover:bg-gray-100 rounded-lg transition-colors border"
          >
            Novo Ficheiro
          </button>
        </div>
      </header>

      {/* Main Layout */}
      <div className="flex-1 flex overflow-hidden">
        {/* Sidebar Filters */}
        <aside className="w-64 bg-white border-r hidden lg:flex flex-col p-6 space-y-6 overflow-y-auto">
          <div>
            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center">
              <Filter className="w-3 h-3 mr-2" /> Filtros
            </h3>
            <div className="space-y-1">
              <button
                onClick={() => setActiveFilter('all')}
                className={`w-full text-left px-3 py-2 rounded-lg text-sm font-medium transition-colors ${
                  activeFilter === 'all' ? 'bg-blue-50 text-blue-700' : 'text-gray-600 hover:bg-gray-50'
                }`}
              >
                Todos os Documentos
              </button>
              {docTypes.map(type => (
                <button
                  key={type}
                  onClick={() => setActiveFilter(type)}
                  className={`w-full text-left px-3 py-2 rounded-lg text-sm font-medium transition-colors ${
                    activeFilter === type ? 'bg-blue-50 text-blue-700' : 'text-gray-600 hover:bg-gray-50'
                  }`}
                >
                  {type}
                </button>
              ))}
            </div>
          </div>

          <div className="pt-6 border-t">
            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center">
              <LayoutGrid className="w-3 h-3 mr-2" /> Contexto
            </h3>
            <div className="p-3 bg-gray-50 rounded-lg border text-xs">
              <div className="font-bold text-gray-900 mb-1">{analysis?.tribunal}</div>
              <div className="text-gray-500">{analysis?.juizo}</div>
            </div>
          </div>
        </aside>

        {/* Content Area */}
        <main className="flex-1 overflow-y-auto p-8 bg-gray-50/50">
          <div className="max-w-7xl mx-auto">
            <div className="flex items-center justify-between mb-8">
              <div>
                <h2 className="text-2xl font-bold text-slate-900">Peças Processuais</h2>
                <p className="text-slate-500 text-sm">Documentos segmentados automaticamente do PDF.</p>
              </div>
              <div className="flex items-center space-x-3">
                <span className="text-xs font-medium text-slate-500 bg-white border px-3 py-1.5 rounded-full shadow-sm">
                  {filteredDocs.length} documentos encontrados
                </span>
              </div>
            </div>

            {filteredDocs.length > 0 ? (
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                {filteredDocs.map(doc => (
                  <DocumentCard 
                    key={doc.id_documento} 
                    doc={doc} 
                    onClick={setSelectedDoc} 
                  />
                ))}
              </div>
            ) : (
              <div className="flex flex-col items-center justify-center py-20 bg-white rounded-2xl border border-dashed border-gray-300">
                <FileText className="w-12 h-12 text-gray-300 mb-4" />
                <h3 className="text-lg font-semibold text-gray-600">Nenhum documento corresponde aos filtros</h3>
                <p className="text-gray-400 text-sm">Tente ajustar a pesquisa ou os filtros laterais.</p>
              </div>
            )}
          </div>
        </main>
      </div>

      {/* Document Detail View */}
      {selectedDoc && (
        <DocumentDetail 
          doc={selectedDoc} 
          onClose={() => setSelectedDoc(null)} 
          siblings={incidentSiblings}
          onSelectSibling={setSelectedDoc}
        />
      )}
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const analyzeProcessText = async (fullText: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Analise o seguinte texto de exportação de processo judicial Citius e extraia os documentos segmentados:\n\n${fullText}`,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          numero_processo: { type: Type.STRING },
          tribunal: { type: Type.STRING },
          juizo: { type: Type.STRING },
          documentos: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id_documento: { type: Type.STRING },
                numero_processo: { type: Type.STRING },
                ref_incidente: { type: Type.STRING },
                ref_formulario: { type: Type.STRING },
                tipo_documento_principal: { type: Type.STRING },
                tipo_documento_indice: { type: Type.STRING },
                parte_apresentante: { type: Type.STRING },
                mandatario: { type: Type.STRING },
                pagina_inicial: { type: Type.NUMBER },
                pagina_final: { type: Type.NUMBER },
                titulo_resumido: { type: Type.STRING },
                sumario: { type: Type.STRING },
                texto_integral: { type: Type.STRING },
                data_documento: { type: Type.STRING },
                campos_especificos: { 
                  type: Type.OBJECT, 
                  description: "Dicionário de metadados específicos extraídos do conteúdo do documento.",
                  properties: {
                    valor_monetario: { type: Type.STRING, description: "Valores em Euros encontrados (ex: taxa de justiça, valor da causa)." },
                    referencia_pagamento: { type: Type.STRING, description: "Referências de DUC ou Multibanco." },
                    artigos_aplicados: { type: Type.STRING, description: "Artigos de lei, normas ou princípios citados." },
                    decisao_resultado: { type: Type.STRING, description: "Resultado do despacho ou pedido (ex: deferido, admitido)." },
                    data_assinatura: { type: Type.STRING, description: "Data de assinatura ou emissão constante no documento." }
                  }
                }
              },
              required: ["id_documento", "tipo_documento_principal", "sumario", "texto_integral"]
            }
          }
        },
        required: ["numero_processo", "documentos"]
      }
    }
  });

  return JSON.parse(response.text);
};

import React from 'react';
import { DocumentMetadata, DocumentType } from '../types';
import { X, ExternalLink, FileText, Info, Layers, FileSearch } from 'lucide-react';
import { TYPE_COLORS } from '../constants';

interface DocumentDetailProps {
  doc: DocumentMetadata;
  file: File | null;
  onClose: () => void;
  siblings?: DocumentMetadata[];
  onSelectSibling: (doc: DocumentMetadata) => void;
}

export const DocumentDetail: React.FC<DocumentDetailProps> = ({ doc, file, onClose, siblings = [], onSelectSibling }) => {
  const colorClass = TYPE_COLORS[doc.tipo_documento_principal] || 'bg-gray-100 text-gray-800 border-gray-200';

  const handleOpenPdf = () => {
    if (!file) return;
    const fileUrl = URL.createObjectURL(file);
    // Tenta abrir o PDF na página específica (suportado por muitos browsers modernos)
    window.open(`${fileUrl}#page=${doc.pagina_inicial}`, '_blank');
  };

  const getMandatarioLabel = (type: DocumentType) => {
    if (type === DocumentType.DESPACHO_JUIZ || type === DocumentType.SENTENCA_ACORDAO) return "Juiz";
    if (type === DocumentType.DESPACHO_PARECER_MP) return "Procurador";
    return "Mandatário";
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-in fade-in duration-200">
      <div className="bg-white w-full max-w-6xl max-h-[95vh] rounded-2xl shadow-2xl overflow-hidden flex flex-col md:flex-row border border-gray-200">
        {/* Painel Esquerdo: Conteúdo */}
        <div className="flex-1 flex flex-col min-w-0 bg-white">
          <div className="px-8 py-5 border-b flex justify-between items-center bg-gray-50/80">
            <div className="flex flex-col">
              <span className={`w-fit px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider border mb-1.5 shadow-sm ${colorClass}`}>
                {doc.tipo_documento_principal}
              </span>
              <h2 className="text-xl font-extrabold text-gray-900 truncate pr-4 tracking-tight">
                {doc.titulo_resumido}
              </h2>
            </div>
            <div className="flex items-center space-x-2">
              <button 
                onClick={handleOpenPdf}
                className="flex items-center space-x-2 px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-bold hover:bg-blue-700 transition-all shadow-md shadow-blue-100 active:scale-95"
              >
                <FileSearch className="w-4 h-4" />
                <span>Ver PDF Original (Pág. {doc.pagina_inicial})</span>
              </button>
              <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full transition-colors">
                <X className="w-6 h-6 text-gray-500" />
              </button>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-8 space-y-10">
            <section>
              <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mb-4 flex items-center">
                <Info className="w-4 h-4 mr-2 text-blue-500" /> Sumário do Documento
              </h3>
              <div className="bg-blue-50/50 border-l-4 border-blue-500 p-6 rounded-r-xl">
                <p className="text-blue-900 leading-relaxed text-base italic font-medium">
                  {doc.sumario}
                </p>
              </div>
            </section>

            <section>
              <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mb-4 flex items-center">
                <FileText className="w-4 h-4 mr-2 text-slate-400" /> Transcrição Parcial / Texto Extraído
              </h3>
              <div className="bg-slate-50 p-8 rounded-xl border border-slate-200 text-sm font-mono whitespace-pre-wrap leading-relaxed text-slate-700 max-h-[500px] overflow-y-auto shadow-inner">
                {doc.texto_integral}
              </div>
              <p className="mt-3 text-xs text-slate-400 italic">
                * O texto acima é uma extração automática. Para visualização fiel, utilize o botão "Ver PDF Original".
              </p>
            </section>
          </div>
        </div>

        {/* Painel Direito: Metadados & Navegação */}
        <div className="w-full md:w-80 bg-gray-50 border-l border-gray-100 p-8 overflow-y-auto space-y-10">
          <div>
            <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mb-6">Metadados Citius</h3>
            <div className="space-y-5">
              <MetaItem label="Número do Processo" value={doc.numero_processo} />
              <MetaItem label="Ref. Incidente (Índice)" value={doc.ref_incidente} />
              {doc.ref_formulario && <MetaItem label="Ref. Formulário Citius" value={doc.ref_formulario} />}
              <MetaItem label="Parte Apresentante" value={doc.parte_apresentante} />
              <MetaItem label={getMandatarioLabel(doc.tipo_documento_principal)} value={doc.mandatario || 'Não identificado'} />
              <MetaItem label="Localização no PDF" value={`Páginas ${doc.pagina_inicial} a ${doc.pagina_final}`} />
              <MetaItem label="Data Identificada" value={doc.data_documento || '---'} />
            </div>
          </div>

          {siblings.length > 1 && (
            <div>
              <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mb-5 flex items-center">
                <Layers className="w-4 h-4 mr-2 text-slate-400" /> Peças do mesmo Incidente
              </h3>
              <div className="space-y-2.5">
                {siblings.map((sibling) => (
                  <button
                    key={sibling.id_documento}
                    onClick={() => onSelectSibling(sibling)}
                    className={`w-full text-left p-4 rounded-xl text-xs transition-all border shadow-sm ${
                      sibling.id_documento === doc.id_documento 
                        ? 'bg-blue-600 text-white border-blue-600 ring-4 ring-blue-50' 
                        : 'bg-white text-gray-700 border-gray-200 hover:border-blue-400 hover:shadow-md'
                    }`}
                  >
                    <div className="font-extrabold truncate mb-0.5 uppercase tracking-tighter">
                      {sibling.tipo_documento_principal}
                    </div>
                    <div className={`truncate opacity-80 ${sibling.id_documento === doc.id_documento ? 'text-blue-100' : 'text-gray-500'}`}>
                      {sibling.titulo_resumido}
                    </div>
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

const MetaItem = ({ label, value }: { label: string; value: string }) => (
  <div className="group">
    <span className="text-[10px] font-bold text-gray-400 uppercase block tracking-tight mb-1 group-hover:text-blue-500 transition-colors">
      {label}
    </span>
    <span className="text-sm font-semibold text-gray-800 break-words leading-tight block">
      {value}
    </span>
  </div>
);

import React, { useState, useMemo, useRef } from 'react';
import { DocumentMetadata, ProcessAnalysis, DocumentType } from './types';
import { analyzeProcessText } from './services/geminiService';
import { extractTextFromPdf } from './services/pdfService';
import { DocumentCard } from './components/DocumentCard';
import { DocumentDetail } from './components/DocumentDetail';
import { 
  Search, 
  Filter, 
  Upload, 
  Loader2, 
  Gavel, 
  FileText, 
  Menu,
  ChevronDown,
  LayoutGrid,
  AlertCircle,
  FileUp,
  X
} from 'lucide-react';

const App: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStep, setProcessingStep] = useState<'extracting' | 'analyzing' | null>(null);
  const [analysis, setAnalysis] = useState<ProcessAnalysis | null>(null);
  const [selectedDoc, setSelectedDoc] = useState<DocumentMetadata | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [activeFilter, setActiveFilter] = useState<string>('all');
  const [error, setError] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile && selectedFile.type === 'application/pdf') {
      setFile(selectedFile);
      setError(null);
    } else if (selectedFile) {
      setError('Por favor, selecione apenas ficheiros PDF.');
    }
  };

  const handleAnalyze = async () => {
    if (!file) return;

    setIsProcessing(true);
    setError(null);

    try {
      setProcessingStep('extracting');
      const extractedText = await extractTextFromPdf(file);

      setProcessingStep('analyzing');
      const result = await analyzeProcessText(extractedText);
      setAnalysis(result);
    } catch (err: any) {
      console.error(err);
      setError('Erro ao processar o ficheiro. Certifique-se que o PDF não está protegido por palavra-passe.');
    } finally {
      setIsProcessing(false);
      setProcessingStep(null);
    }
  };

  const filteredDocs = useMemo(() => {
    if (!analysis) return [];
    return analysis.documentos.filter(doc => {
      const matchesSearch = 
        doc.titulo_resumido.toLowerCase().includes(searchQuery.toLowerCase()) ||
        doc.texto_integral.toLowerCase().includes(searchQuery.toLowerCase()) ||
        doc.parte_apresentante.toLowerCase().includes(searchQuery.toLowerCase()) ||
        doc.ref_incidente.includes(searchQuery);

      const matchesFilter = activeFilter === 'all' || doc.tipo_documento_principal === activeFilter;

      return matchesSearch && matchesFilter;
    });
  }, [analysis, searchQuery, activeFilter]);

  const docTypes = useMemo(() => {
    if (!analysis) return [];
    return Array.from(new Set(analysis.documentos.map(d => d.tipo_documento_principal)));
  }, [analysis]);

  const incidentSiblings = useMemo(() => {
    if (!selectedDoc || !analysis) return [];
    return analysis.documentos.filter(d => d.ref_incidente === selectedDoc.ref_incidente);
  }, [selectedDoc, analysis]);

  if (!analysis && !isProcessing) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6">
        <div className="w-full max-w-2xl space-y-8 animate-in slide-in-from-bottom-4 duration-500">
          <div className="text-center">
            <div className="inline-flex items-center justify-center p-3 bg-blue-600 rounded-2xl shadow-lg mb-4">
              <Gavel className="w-10 h-10 text-white" />
            </div>
            <h1 className="text-4xl font-extrabold text-slate-900 tracking-tight">Citius Analytics Pro</h1>
            <p className="mt-3 text-lg text-slate-600 max-w-lg mx-auto leading-relaxed">
              Carregue o PDF de exportação do Citius para análise inteligente imediata.
            </p>
          </div>

          <div className="bg-white p-8 rounded-2xl shadow-xl border border-slate-200">
            <div 
              onClick={() => fileInputRef.current?.click()}
              onDragOver={(e) => { e.preventDefault(); e.stopPropagation(); }}
              onDrop={(e) => {
                e.preventDefault();
                e.stopPropagation();
                const droppedFile = e.dataTransfer.files[0];
                if (droppedFile?.type === 'application/pdf') {
                  setFile(droppedFile);
                  setError(null);
                }
              }}
              className={`border-2 border-dashed rounded-xl p-12 flex flex-col items-center justify-center transition-all cursor-pointer ${
                file ? 'border-blue-400 bg-blue-50' : 'border-slate-300 hover:border-blue-400 hover:bg-slate-50'
              }`}
            >
              <input 
                type="file" 
                ref={fileInputRef} 
                className="hidden" 
                accept=".pdf" 
                onChange={handleFileChange} 
              />

              {file ? (
                <div className="text-center">
                  <div className="bg-blue-600 p-3 rounded-full inline-flex mb-4">
                    <FileText className="w-8 h-8 text-white" />
                  </div>
                  <h3 className="font-bold text-slate-900">{file.name}</h3>
                  <p className="text-xs text-slate-500">{(file.size / 1024 / 1024).toFixed(2)} MB</p>
                  <button 
                    onClick={(e) => { e.stopPropagation(); setFile(null); }}
                    className="mt-4 text-xs font-bold text-red-500 flex items-center justify-center mx-auto hover:text-red-700"
                  >
                    <X className="w-3 h-3 mr-1" /> Remover ficheiro
                  </button>
                </div>
              ) : (
                <div className="text-center">
                  <FileUp className="w-12 h-12 text-slate-300 mb-4 mx-auto" />
                  <p className="text-slate-600 font-medium">Arraste o PDF aqui ou clique para procurar</p>
                  <p className="text-xs text-slate-400 mt-2">Apenas exportações do Citius / Tribunais</p>
                </div>
              )}
            </div>

            {error && (
              <div className="mt-4 flex items-center p-3 bg-red-50 border border-red-100 text-red-700 rounded-lg text-sm">
                <AlertCircle className="w-4 h-4 mr-2" />
                {error}
              </div>
            )}

            <button
              onClick={handleAnalyze}
              disabled={!file}
              className="w-full mt-6 py-4 px-6 bg-blue-600 text-white font-bold rounded-xl hover:bg-blue-700 active:scale-[0.98] transition-all flex items-center justify-center space-x-2 disabled:opacity-50 disabled:cursor-not-allowed shadow-lg shadow-blue-200"
            >
              <Upload className="w-5 h-5" />
              <span>Analisar Processo</span>
            </button>
          </div>

          <div className="flex justify-center space-x-8 text-xs text-slate-400 font-medium uppercase tracking-widest">
            <span>Privacidade Local</span>
            <span className="text-slate-200">•</span>
            <span>Extração de Texto OCR</span>
            <span className="text-slate-200">•</span>
            <span>IA Jurídica PT</span>
          </div>
        </div>
      </div>
    );
  }

  if (isProcessing) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 space-y-8">
        <div className="relative">
          <div className="w-24 h-24 border-8 border-blue-100 border-t-blue-600 rounded-full animate-spin"></div>
          <Gavel className="absolute inset-0 m-auto w-8 h-8 text-blue-600" />
        </div>
        <div className="text-center space-y-3">
          <h2 className="text-2xl font-bold text-slate-900">
            {processingStep === 'extracting' ? 'Extraindo Texto do PDF' : 'Analisando Estrutura Jurídica'}
          </h2>
          <p className="text-slate-500 flex items-center justify-center">
            <Loader2 className="w-4 h-4 animate-spin mr-2" />
            {processingStep === 'extracting' 
              ? 'Processando as páginas localmente...' 
              : 'A IA está a segmentar e resumir os documentos...'}
          </p>
          <div className="w-64 h-1.5 bg-gray-200 rounded-full overflow-hidden mx-auto mt-4">
            <div className={`h-full bg-blue-600 transition-all duration-1000 ${processingStep === 'extracting' ? 'w-1/3' : 'w-2/3'}`}></div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      {/* Navbar */}
      <header className="sticky top-0 z-30 bg-white border-b shadow-sm px-6 py-3 flex items-center justify-between">
        <div className="flex items-center space-x-3">
          <div className="p-1.5 bg-blue-600 rounded-lg">
            <Gavel className="w-5 h-5 text-white" />
          </div>
          <div>
            <h1 className="text-sm font-black text-slate-900 uppercase tracking-tight">Citius Analytics Pro</h1>
            <p className="text-[10px] text-slate-500 font-bold leading-none">{analysis?.numero_processo || 'Processo em análise'}</p>
          </div>
        </div>

        <div className="flex-1 max-w-xl mx-8 relative hidden md:block">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          <input
            type="text"
            placeholder="Pesquisar nos documentos, partes ou texto..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-2 bg-gray-100 border-transparent focus:bg-white focus:border-blue-500 rounded-lg text-sm transition-all"
          />
        </div>

        <div className="flex items-center space-x-2">
          <button 
            onClick={() => { setAnalysis(null); setFile(null); }}
            className="px-4 py-2 text-xs font-bold text-gray-600 hover:bg-gray-100 rounded-lg transition-colors border"
          >
            Novo Ficheiro
          </button>
        </div>
      </header>

      {/* Main Layout */}
      <div className="flex-1 flex overflow-hidden">
        {/* Sidebar Filters */}
        <aside className="w-64 bg-white border-r hidden lg:flex flex-col p-6 space-y-6 overflow-y-auto">
          <div>
            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center">
              <Filter className="w-3 h-3 mr-2" /> Filtros
            </h3>
            <div className="space-y-1">
              <button
                onClick={() => setActiveFilter('all')}
                className={`w-full text-left px-3 py-2 rounded-lg text-sm font-medium transition-colors ${
                  activeFilter === 'all' ? 'bg-blue-50 text-blue-700' : 'text-gray-600 hover:bg-gray-50'
                }`}
              >
                Todos os Documentos
              </button>
              {docTypes.map(type => (
                <button
                  key={type}
                  onClick={() => setActiveFilter(type)}
                  className={`w-full text-left px-3 py-2 rounded-lg text-sm font-medium transition-colors ${
                    activeFilter === type ? 'bg-blue-50 text-blue-700' : 'text-gray-600 hover:bg-gray-50'
                  }`}
                >
                  {type}
                </button>
              ))}
            </div>
          </div>

          <div className="pt-6 border-t">
            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center">
              <LayoutGrid className="w-3 h-3 mr-2" /> Contexto
            </h3>
            <div className="p-3 bg-gray-50 rounded-lg border text-xs">
              <div className="font-bold text-gray-900 mb-1">{analysis?.tribunal}</div>
              <div className="text-gray-500">{analysis?.juizo}</div>
            </div>
          </div>
        </aside>

        {/* Content Area */}
        <main className="flex-1 overflow-y-auto p-8 bg-gray-50/50">
          <div className="max-w-7xl mx-auto">
            <div className="flex items-center justify-between mb-8">
              <div>
                <h2 className="text-2xl font-bold text-slate-900">Peças Processuais</h2>
                <p className="text-slate-500 text-sm">Documentos segmentados automaticamente do PDF.</p>
              </div>
              <div className="flex items-center space-x-3">
                <span className="text-xs font-medium text-slate-500 bg-white border px-3 py-1.5 rounded-full shadow-sm">
                  {filteredDocs.length} documentos encontrados
                </span>
              </div>
            </div>

            {filteredDocs.length > 0 ? (
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                {filteredDocs.map(doc => (
                  <DocumentCard 
                    key={doc.id_documento} 
                    doc={doc} 
                    onClick={setSelectedDoc} 
                  />
                ))}
              </div>
            ) : (
              <div className="flex flex-col items-center justify-center py-20 bg-white rounded-2xl border border-dashed border-gray-300">
                <FileText className="w-12 h-12 text-gray-300 mb-4" />
                <h3 className="text-lg font-semibold text-gray-600">Nenhum documento corresponde aos filtros</h3>
                <p className="text-gray-400 text-sm">Tente ajustar a pesquisa ou os filtros laterais.</p>
              </div>
            )}
          </div>
        </main>
      </div>

      {/* Document Detail View */}
      {selectedDoc && (
        <DocumentDetail 
          doc={selectedDoc} 
          file={file}
          onClose={() => setSelectedDoc(null)} 
          siblings={incidentSiblings}
          onSelectSibling={setSelectedDoc}
        />
      )}
    </div>
  );
};

export default App;

export enum DocumentType {
  DESPACHO_JUIZ = 'Despacho do juiz',
  SENTENCA_ACORDAO = 'Sentença/acórdão',
  DESPACHO_PARECER_MP = 'Despacho/parecer do Ministério Público',
  FORMULARIO_CITIUS = 'Formulário Citius',
  ALEGACOES_RECURSO = 'Alegações de recurso',
  CONTRA_ALEGACOES = 'Contra-alegações',
  REQUERIMENTO = 'Requerimento',
  PETICAO_INICIAL = 'Petição inicial',
  CONTESTACAO = 'Contestação',
  PROCURACAO = 'Procuração',
  DUC = 'DUC (Documento Único de Cobrança)',
  COMPROVATIVO_PAGAMENTO = 'Comprovativo de pagamento',
  CONTRATO_TRABALHO = 'Contrato de trabalho',
  FATURA = 'Factura/fatura',
  ATA_JULGAMENTO = 'Ata de julgamento',
  OUTRO = 'Outro'
}

export interface DocumentMetadata {
  id_documento: string;
  numero_processo: string;
  ref_ato: string;        // Referência do Ato (ex: 20239895)
  ref_documento: string;  // Referência do Documento (ex: 23170940)
  ref_formulario?: string;
  tipo_documento_principal: DocumentType;
  tipo_documento_indice: string;
  parte_apresentante: string;
  mandatario?: string;
  pagina_inicial: number;
  pagina_final: number;
  titulo_resumido: string;
  sumario: string;
  texto_integral: string;
  data_documento?: string;
  campos_especificos: Record<string, any>;
}

export interface ProcessAnalysis {
  numero_processo: string;
  tribunal: string;
  juizo: string;
  documentos: DocumentMetadata[];
}

import { GoogleGenAI, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const analyzeProcessText = async (fullText: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Analise o seguinte texto de exportação de processo judicial Citius e extraia os documentos segmentados:\n\n${fullText}`,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          numero_processo: { type: Type.STRING },
          tribunal: { type: Type.STRING },
          juizo: { type: Type.STRING },
          documentos: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id_documento: { type: Type.STRING },
                numero_processo: { type: Type.STRING },
                ref_ato: { type: Type.STRING, description: "A referência do ato/incidente (primeiro número da linha do índice)." },
                ref_documento: { type: Type.STRING, description: "A referência específica do documento no Citius." },
                ref_formulario: { type: Type.STRING },
                tipo_documento_principal: { type: Type.STRING },
                tipo_documento_indice: { type: Type.STRING },
                parte_apresentante: { type: Type.STRING },
                mandatario: { type: Type.STRING },
                pagina_inicial: { type: Type.NUMBER },
                pagina_final: { type: Type.NUMBER },
                titulo_resumido: { type: Type.STRING },
                sumario: { type: Type.STRING, description: "Sumário fiel ao texto sem interpretações excessivas." },
                texto_integral: { type: Type.STRING },
                data_documento: { type: Type.STRING },
                campos_especificos: { 
                  type: Type.OBJECT, 
                  description: "Dicionário de metadados específicos.",
                  properties: {
                    valor_monetario: { type: Type.STRING },
                    referencia_pagamento: { type: Type.STRING },
                    artigos_aplicados: { type: Type.STRING },
                    decisao_resultado: { type: Type.STRING },
                    data_assinatura: { type: Type.STRING }
                  }
                }
              },
              required: ["id_documento", "tipo_documento_principal", "sumario", "ref_ato", "ref_documento"]
            }
          }
        },
        required: ["numero_processo", "documentos"]
      }
    }
  });

  return JSON.parse(response.text);
};

import React from 'react';
import { DocumentMetadata, DocumentType } from '../types';
import { X, FileText, Info, Layers, FileSearch } from 'lucide-react';
import { TYPE_COLORS } from '../constants';

interface DocumentDetailProps {
  doc: DocumentMetadata;
  file: File | null;
  onClose: () => void;
  siblings?: DocumentMetadata[];
  onSelectSibling: (doc: DocumentMetadata) => void;
}

export const DocumentDetail: React.FC<DocumentDetailProps> = ({ doc, file, onClose, siblings = [], onSelectSibling }) => {
  const colorClass = TYPE_COLORS[doc.tipo_documento_principal] || 'bg-gray-100 text-gray-800 border-gray-200';

  const handleOpenPdf = () => {
    if (!file) return;
    const fileUrl = URL.createObjectURL(file);
    window.open(`${fileUrl}#page=${doc.pagina_inicial}`, '_blank');
  };

  const getMandatarioLabel = (type: DocumentType) => {
    if (type === DocumentType.DESPACHO_JUIZ || type === DocumentType.SENTENCA_ACORDAO) return "Juiz";
    if (type === DocumentType.DESPACHO_PARECER_MP) return "Procurador";
    return "Mandatário";
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-in fade-in duration-200">
      <div className="bg-white w-full max-w-6xl max-h-[95vh] rounded-2xl shadow-2xl overflow-hidden flex flex-col md:flex-row border border-gray-200">
        {/* Painel Esquerdo: Conteúdo Principal */}
        <div className="flex-1 flex flex-col min-w-0 bg-white">
          <div className="px-8 py-5 border-b flex justify-between items-center bg-gray-50/80">
            <div className="flex flex-col">
              <span className={`w-fit px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider border mb-1.5 shadow-sm ${colorClass}`}>
                {doc.tipo_documento_principal}
              </span>
              <h2 className="text-xl font-extrabold text-gray-900 truncate pr-4 tracking-tight">
                {doc.titulo_resumido}
              </h2>
            </div>
            <div className="flex items-center space-x-2">
              <button 
                onClick={handleOpenPdf}
                className="flex items-center space-x-2 px-5 py-2.5 bg-blue-600 text-white rounded-xl text-sm font-bold hover:bg-blue-700 transition-all shadow-lg shadow-blue-200 active:scale-95"
              >
                <FileSearch className="w-4 h-4" />
                <span>Ver PDF Original (Pág. {doc.pagina_inicial})</span>
              </button>
              <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full transition-colors ml-2">
                <X className="w-6 h-6 text-gray-400" />
              </button>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-8">
            <section>
              <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mb-4 flex items-center">
                <Info className="w-4 h-4 mr-2 text-blue-500" /> Sumário Fiel do Documento
              </h3>
              <div className="bg-blue-50/30 border-l-4 border-blue-500 p-8 rounded-r-2xl">
                <p className="text-blue-950 leading-relaxed text-lg italic font-medium">
                  {doc.sumario}
                </p>
              </div>
              <p className="mt-6 text-sm text-gray-500 leading-relaxed">
                Este sumário foi gerado automaticamente através da análise do documento original no sistema Citius, respeitando integralmente o teor da decisão ou requerimento.
              </p>
            </section>
          </div>
        </div>

        {/* Painel Direito: Metadados Estruturados */}
        <div className="w-full md:w-80 bg-gray-50 border-l border-gray-100 p-8 overflow-y-auto space-y-10">
          <div>
            <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mb-6">Identificação Citius</h3>
            <div className="space-y-6">
              <MetaItem label="Número do Processo" value={doc.numero_processo} />
              <div className="grid grid-cols-1 gap-4">
                <MetaItem label="Ref. do Ato" value={doc.ref_ato} highlight />
                <MetaItem label="Ref. do Documento" value={doc.ref_documento} highlight />
              </div>
              <MetaItem label="Apresentante" value={doc.parte_apresentante} />
              <MetaItem label={getMandatarioLabel(doc.tipo_documento_principal)} value={doc.mandatario || 'Não identificado'} />
              <MetaItem label="Posição no PDF" value={`Páginas ${doc.pagina_inicial} a ${doc.pagina_final}`} />
              <MetaItem label="Data Identificada" value={doc.data_documento || '---'} />
            </div>
          </div>

          {siblings.length > 1 && (
            <div>
              <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mb-5 flex items-center">
                <Layers className="w-4 h-4 mr-2 text-slate-400" /> Peças do mesmo Ato
              </h3>
              <div className="space-y-2">
                {siblings.map((sibling) => (
                  <button
                    key={sibling.id_documento}
                    onClick={() => onSelectSibling(sibling)}
                    className={`w-full text-left p-4 rounded-xl text-xs transition-all border shadow-sm ${
                      sibling.id_documento === doc.id_documento 
                        ? 'bg-blue-600 text-white border-blue-600 ring-4 ring-blue-50' 
                        : 'bg-white text-gray-700 border-gray-200 hover:border-blue-400 hover:shadow-md'
                    }`}
                  >
                    <div className="font-extrabold truncate mb-0.5 uppercase tracking-tighter">
                      {sibling.tipo_documento_principal}
                    </div>
                    <div className={`truncate opacity-80 ${sibling.id_documento === doc.id_documento ? 'text-blue-100' : 'text-gray-500'}`}>
                      Ref Doc: {sibling.ref_documento}
                    </div>
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

const MetaItem = ({ label, value, highlight }: { label: string; value: string; highlight?: boolean }) => (
  <div className="group">
    <span className="text-[10px] font-bold text-gray-400 uppercase block tracking-tight mb-1 group-hover:text-blue-500 transition-colors">
      {label}
    </span>
    <span className={`text-sm font-semibold break-words leading-tight block ${highlight ? 'text-blue-700 font-bold' : 'text-gray-800'}`}>
      {value}
    </span>
  </div>
);

