import { GoogleGenAI, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";

// Correct initialization using named parameter and direct process.env.API_KEY as per guidelines
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeProcessText = async (fullText: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Analise o seguinte texto de exportação de processo judicial Citius e extraia os documentos segmentados:\n\n${fullText}`,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          numero_processo: { type: Type.STRING },
          tribunal: { type: Type.STRING },
          juizo: { type: Type.STRING },
          documentos: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id_documento: { type: Type.STRING },
                numero_processo: { type: Type.STRING },
                ref_ato: { type: Type.STRING, description: "A referência do ato/incidente (primeiro número da linha do índice)." },
                ref_documento: { type: Type.STRING, description: "A referência específica do documento no Citius." },
                ref_formulario: { type: Type.STRING },
                tipo_documento_principal: { type: Type.STRING },
                tipo_documento_indice: { type: Type.STRING },
                parte_apresentante: { type: Type.STRING },
                mandatario: { type: Type.STRING },
                pagina_inicial: { type: Type.NUMBER },
                pagina_final: { type: Type.NUMBER },
                titulo_resumido: { type: Type.STRING },
                sumario: { type: Type.STRING, description: "Sumário fiel ao texto sem interpretações excessivas." },
                texto_integral: { type: Type.STRING },
                data_documento: { type: Type.STRING },
                campos_especificos: { 
                  type: Type.OBJECT, 
                  description: "Dicionário de metadados específicos.",
                  properties: {
                    valor_monetario: { type: Type.STRING },
                    referencia_pagamento: { type: Type.STRING },
                    artigos_aplicados: { type: Type.STRING },
                    decisao_resultado: { type: Type.STRING },
                    data_assinatura: { type: Type.STRING }
                  }
                }
              },
              required: ["id_documento", "tipo_documento_principal", "sumario", "ref_ato", "ref_documento"]
            }
          }
        },
        required: ["numero_processo", "documentos"]
      }
    }
  });

  return JSON.parse(response.text);
};

