          {/* Ordenação na Barra Lateral */}
          <div>
            <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-4 flex items-center">
              <SortAsc className="w-3.5 h-3.5 mr-2 text-blue-500" /> Ordenação das Peças
            </h3>
            <div className="flex flex-col bg-slate-50 p-1.5 rounded-2xl border border-slate-200 shadow-inner space-y-1">
              <button 
                onClick={() => setSortOrder('chronological')}
                className={`flex items-center space-x-3 px-4 py-2.5 rounded-xl text-xs font-bold transition-all ${
                  sortOrder === 'chronological' ? 'bg-white text-blue-700 shadow-sm border border-slate-200' : 'text-gray-500 hover:text-gray-700'
                }`}
              >
                <Clock className="w-4 h-4" />
                <span>Cronológica (PDF)</span>
              </button>
              <button 
                onClick={() => setSortOrder('alphabetical')}
                className={`flex items-center space-x-3 px-4 py-2.5 rounded-xl text-xs font-bold transition-all ${
                  sortOrder === 'alphabetical' ? 'bg-white text-blue-700 shadow-sm border border-slate-200' : 'text-gray-500 hover:text-gray-700'
                }`}
              >
                <SortAsc className="w-4 h-4" />
                <span>Alfabética (A-Z)</span>
              </button>
            </div>
          </div>

          <div>
            <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-4 flex items-center">
              <Filter className="w-3 h-3 mr-2 text-blue-500" /> Filtrar por Tipo (A-Z)
            </h3>
            <div className="space-y-1">
              <button
                onClick={() => setActiveFilter('all')}
                className={`w-full text-left px-3 py-2.5 rounded-xl text-xs font-bold transition-all ${
                  activeFilter === 'all' ? 'bg-blue-600 text-white shadow-md shadow-blue-100' : 'text-gray-600 hover:bg-gray-50'
                }`}
              >
                Todos os Documentos
              </button>
              {docTypes.map(type => (
                <button
                  key={type}
                  onClick={() => setActiveFilter(type)}
                  className={`w-full text-left px-3 py-2.5 rounded-xl text-xs font-bold transition-all ${
                    activeFilter === type ? 'bg-blue-600 text-white shadow-md shadow-blue-100' : 'text-gray-600 hover:bg-gray-50'
                  }`}
                >
                  {type}
                </button>
              ))}
            </div>
          </div>

          <div className="pt-8 border-t">
            <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-4 flex items-center">
              <LayoutGrid className="w-3 h-3 mr-2 text-slate-400" /> Contexto do Processo
            </h3>
            <div className="p-4 bg-slate-50 rounded-xl border border-slate-100 text-[11px] space-y-2">
              <div className="font-black text-slate-900 uppercase leading-tight">{analysis?.tribunal}</div>
              <div className="text-slate-500 font-medium">{analysis?.juizo}</div>
            </div>
          </div>
        </aside>

        <main className="flex-1 overflow-y-auto p-8 bg-gray-50/50">
          <div className="max-w-7xl mx-auto">
            <div className="flex flex-col md:flex-row md:items-center justify-between mb-10 space-y-4 md:space-y-0">
              <div>
                <h2 className="text-2xl font-black text-slate-900 tracking-tight">Peças Processuais</h2>
                <p className="text-slate-500 text-sm font-medium">Documentos segmentados e analisados automaticamente.</p>
              </div>

              <div className="flex items-center space-x-3">
                <span className="text-xs font-bold text-slate-400 bg-white border px-4 py-2 rounded-xl shadow-sm">
                  {filteredDocs.length} documentos encontrados
                </span>
              </div>
            </div>

            {filteredDocs.length > 0 ? (
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6 animate-in fade-in duration-500">
                {filteredDocs.map(doc => (
                  <DocumentCard key={doc.id_documento} doc={doc} onClick={setSelectedDoc} />
                ))}
              </div>
            ) : (
              <div className="flex flex-col items-center justify-center py-24 bg-white rounded-3xl border border-dashed border-gray-200">
                <FileText className="w-16 h-16 text-gray-200 mb-6" />
                <h3 className="text-xl font-bold text-gray-800">Sem resultados para os filtros aplicados</h3>
                <p className="text-gray-400 text-sm mt-2">Ajuste a sua pesquisa ou filtros laterais.</p>
              </div>
            )}
          </div>
        </main>
      </div>

      {selectedDoc && (
        <DocumentDetail 
          doc={selectedDoc} 
          file={file}
          onClose={() => setSelectedDoc(null)} 
          siblings={incidentSiblings}
          onSelectSibling={setSelectedDoc}
        />
      )}
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { DocumentMetadata, DocumentType } from '../types';
import { X, Info, Layers, FileSearch } from 'lucide-react';
import { TYPE_COLORS } from '../constants';

interface DocumentDetailProps {
  doc: DocumentMetadata;
  file: File | null;
  onClose: () => void;
  siblings?: DocumentMetadata[];
  onSelectSibling: (doc: DocumentMetadata) => void;
}

export const DocumentDetail: React.FC<DocumentDetailProps> = ({ doc, file, onClose, siblings = [], onSelectSibling }) => {
  const colorClass = TYPE_COLORS[doc.tipo_documento_principal] || 'bg-gray-100 text-gray-800 border-gray-200';

  const handleOpenPdf = () => {
    if (!file) return;
    const fileUrl = URL.createObjectURL(file);
    window.open(`${fileUrl}#page=${doc.pagina_inicial}`, '_blank');
  };

  const getRoleLabel = (type: DocumentType) => {
    if (type === DocumentType.DESPACHO_JUIZ || type === DocumentType.SENTENCA_ACORDAO) return "Juiz";
    if (type === DocumentType.DESPACHO_PARECER_MP) return "Procurador";
    return "Mandatário";
  };

  // Se for um despacho judicial ou parecer do MP, é considerado um ato autónomo.
  // Nestes casos, não mostramos peças do "mesmo ato" conforme solicitado pelo utilizador.
  const hasSiblings = useMemo(() => {
    const isAutonomousAct = 
      doc.tipo_documento_principal === DocumentType.DESPACHO_JUIZ || 
      doc.tipo_documento_principal === DocumentType.SENTENCA_ACORDAO || 
      doc.tipo_documento_principal === DocumentType.DESPACHO_PARECER_MP;

    if (isAutonomousAct) return false;

    return siblings.length > 1;
  }, [siblings, doc.tipo_documento_principal]);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm p-4 animate-in fade-in duration-300">
      <div className="bg-white w-full max-w-6xl max-h-[90vh] rounded-3xl shadow-2xl overflow-hidden flex flex-col md:flex-row border border-white/20">

        {/* Painel Esquerdo: Sumário */}
        <div className="flex-1 flex flex-col min-w-0 bg-white">
          <div className="px-10 py-6 border-b flex justify-between items-center bg-gray-50/50">
            <div className="flex flex-col">
              <span className={`w-fit px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border mb-2 shadow-sm ${colorClass}`}>
                {doc.tipo_documento_principal}
              </span>
              <h2 className="text-2xl font-black text-gray-900 truncate pr-6 tracking-tight">
                {doc.titulo_resumido}
              </h2>
            </div>
            <div className="flex items-center space-x-3">
              <button 
                onClick={handleOpenPdf}
                className="flex items-center space-x-2 px-6 py-3 bg-blue-600 text-white rounded-2xl text-sm font-black hover:bg-blue-700 transition-all shadow-xl shadow-blue-200 active:scale-95"
              >
                <FileSearch className="w-5 h-5" />
                <span>Ver PDF Original (Pág. {doc.pagina_inicial})</span>
              </button>
              <button onClick={onClose} className="p-2.5 hover:bg-gray-200 rounded-full transition-colors text-gray-400">
                <X className="w-7 h-7" />
              </button>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-10">
            <section>
              <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.3em] mb-6 flex items-center">
                <Info className="w-4 h-4 mr-2 text-blue-500" /> Sumário Fiel ao Texto Original
              </h3>
              <div className="bg-blue-50/20 border-l-[6px] border-blue-500 p-10 rounded-r-3xl shadow-inner">
                <p className="text-blue-950 leading-relaxed text-xl font-medium whitespace-pre-wrap italic">
                  {doc.sumario}
                </p>
              </div>
              <div className="mt-8 p-6 bg-amber-50 rounded-2xl border border-amber-100/50 flex items-start space-x-4">
                <div className="bg-amber-100 p-2 rounded-lg shrink-0">
                  <Info className="w-4 h-4 text-amber-600" />
                </div>
                <p className="text-xs text-amber-800 font-medium leading-relaxed">
                  Este sumário é uma transcrição e resumo estruturado fiel ao conteúdo jurídico da peça processual. 
                  Para consulta probatória legal, utilize sempre o botão <span className="font-bold">"Ver PDF Original"</span> acima para aceder ao documento oficial digitalizado.
                </p>
              </div>
            </section>
          </div>
        </div>

        {/* Painel Direito: Metadados Citius */}
        <div className="w-full md:w-80 bg-gray-50 border-l border-gray-100 p-10 overflow-y-auto space-y-10">
          <div>
            <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.3em] mb-8">Metadados Processuais</h3>
            <div className="space-y-8">
              <MetaItem label="Número do Processo" value={doc.numero_processo} />

              <div className="space-y-4">
                <MetaItem label="Ref. do Ato (Incidente)" value={doc.ref_ato} isBadge />
                <MetaItem label="Ref. do Documento" value={doc.ref_documento} isBadge />
              </div>

              <MetaItem label="Apresentante" value={doc.parte_apresentante} />

              <div className="group">
                <span className="text-[10px] font-black text-gray-400 uppercase block tracking-tight mb-2 group-hover:text-blue-500 transition-colors">
                  {getRoleLabel(doc.tipo_documento_principal)}
                </span>
                <span className="text-sm font-extrabold text-gray-900 block leading-snug">
                  {doc.mandatario || 'Não identificado'}
                </span>
              </div>

              <MetaItem label="Localização no PDF" value={`Páginas ${doc.pagina_inicial} a ${doc.pagina_final}`} />
              <MetaItem label="Data do Documento" value={doc.data_documento || 'Sem data identificada'} />
            </div>
          </div>

          {hasSiblings && (
            <div className="pt-8 border-t border-gray-200">
              <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.3em] mb-6 flex items-center">
                <Layers className="w-4 h-4 mr-2 text-slate-400" /> Peças do Mesmo Ato
              </h3>
              <div className="space-y-3">
                {siblings.map((sibling) => (
                  <button
                    key={sibling.id_documento}
                    onClick={() => onSelectSibling(sibling)}
                    className={`w-full text-left p-4 rounded-2xl text-[11px] font-bold transition-all border shadow-sm ${
                      sibling.id_documento === doc.id_documento 
                        ? 'bg-blue-600 text-white border-blue-600 ring-4 ring-blue-50 scale-[1.02]' 
                        : 'bg-white text-gray-700 border-gray-200 hover:border-blue-400 hover:shadow-md'
                    }`}
                  >
                    <div className="uppercase tracking-tighter mb-1 truncate">{sibling.tipo_documento_principal}</div>
                    <div className={`truncate font-medium ${sibling.id_documento === doc.id_documento ? 'text-blue-100' : 'text-gray-400'}`}>
                      Ref Doc: {sibling.ref_documento}
                    </div>
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

const MetaItem = ({ label, value, isBadge }: { label: string; value: string; isBadge?: boolean }) => (
  <div className="group">
    <span className="text-[10px] font-black text-gray-400 uppercase block tracking-tight mb-2 group-hover:text-blue-500 transition-colors">
      {label}
    </span>
    <span className={`text-sm font-extrabold block break-words leading-tight ${isBadge ? 'text-blue-700 bg-blue-50 px-2 py-1 rounded-lg border border-blue-100 w-fit' : 'text-gray-900'}`}>
      {value}
    </span>
  </div>
);

import React, { useState, useMemo, useRef } from 'react';
import { DocumentMetadata, ProcessAnalysis, DocumentType, SortOrder } from './types';
import { analyzeProcessText } from './services/geminiService';
import { extractTextFromPdf } from './services/pdfService';
import { DocumentCard } from './components/DocumentCard';
import { DocumentDetail } from './components/DocumentDetail';
import { 
  Search, 
  Filter, 
  Upload, 
  Loader2, 
  Gavel, 
  FileText, 
  LayoutGrid,
  AlertCircle,
  FileUp,
  X,
  SortAsc,
  Clock
} from 'lucide-react';

const App: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStep, setProcessingStep] = useState<'extracting' | 'analyzing' | null>(null);
  const [analysis, setAnalysis] = useState<ProcessAnalysis | null>(null);
  const [selectedDoc, setSelectedDoc] = useState<DocumentMetadata | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [activeFilter, setActiveFilter] = useState<string>('all');
  const [sortOrder, setSortOrder] = useState<SortOrder>('chronological');
  const [error, setError] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile && selectedFile.type === 'application/pdf') {
      setFile(selectedFile);
      setError(null);
    } else if (selectedFile) {
      setError('Por favor, selecione apenas ficheiros PDF.');
    }
  };

  const handleAnalyze = async () => {
    if (!file) return;
    setIsProcessing(true);
    setError(null);
    try {
      setProcessingStep('extracting');
      const extractedText = await extractTextFromPdf(file);
      setProcessingStep('analyzing');
      const result = await analyzeProcessText(extractedText);
      setAnalysis(result);
    } catch (err: any) {
      console.error(err);
      setError('Erro ao processar o ficheiro. Certifique-se que o PDF não está protegido por palavra-passe.');
    } finally {
      setIsProcessing(false);
      setProcessingStep(null);
    }
  };

  const filteredDocs = useMemo(() => {
    if (!analysis) return [];
    const query = searchQuery.toLowerCase();

    let docs = [...analysis.documentos].filter(doc => {
      const titulo = (doc.titulo_resumido || '').toLowerCase();
      const texto = (doc.texto_integral || '').toLowerCase();
      const apresentante = (doc.parte_apresentante || '').toLowerCase();
      const refAto = (doc.ref_ato || '');
      const refDoc = (doc.ref_documento || '');

      const matchesSearch = 
        titulo.includes(query) ||
        texto.includes(query) ||
        apresentante.includes(query) ||
        refAto.includes(searchQuery) ||
        refDoc.includes(searchQuery);

      const matchesFilter = activeFilter === 'all' || doc.tipo_documento_principal === activeFilter;
      return matchesSearch && matchesFilter;
    });

    if (sortOrder === 'alphabetical') {
      docs.sort((a: DocumentMetadata, b: DocumentMetadata) => 
        (a.titulo_resumido || '').localeCompare(b.titulo_resumido || '')
      );
    } else {
      docs.sort((a: DocumentMetadata, b: DocumentMetadata) => 
        (a.pagina_inicial || 0) - (b.pagina_inicial || 0)
      );
    }

    return docs;
  }, [analysis, searchQuery, activeFilter, sortOrder]);

  const docTypes = useMemo(() => {
    if (!analysis) return [];
    const types = Array.from(new Set(analysis.documentos.map(d => d.tipo_documento_principal).filter(Boolean)));
    return types.sort((a: string, b: string) => a.localeCompare(b));
  }, [analysis]);

  const incidentSiblings = useMemo(() => {
    if (!selectedDoc || !analysis) return [];
    return analysis.documentos.filter(d => d.ref_ato === selectedDoc.ref_ato);
  }, [selectedDoc, analysis]);

  if (!analysis && !isProcessing) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6">
        <div className="w-full max-w-2xl space-y-8 animate-in slide-in-from-bottom-4 duration-500">
          <div className="text-center">
            <div className="inline-flex items-center justify-center p-3 bg-blue-600 rounded-2xl shadow-lg mb-4">
              <Gavel className="w-10 h-10 text-white" />
            </div>
            <h1 className="text-4xl font-extrabold text-slate-900 tracking-tight">Citius Analytics Pro</h1>
            <p className="mt-3 text-lg text-slate-600 max-w-lg mx-auto leading-relaxed">
              Carregue o PDF de exportação do Citius para análise inteligente imediata.
            </p>
          </div>

          <div className="bg-white p-8 rounded-2xl shadow-xl border border-slate-200">
            <div 
              onClick={() => fileInputRef.current?.click()}
              onDragOver={(e) => { e.preventDefault(); e.stopPropagation(); }}
              onDrop={(e) => {
                e.preventDefault();
                e.stopPropagation();
                const droppedFile = e.dataTransfer.files[0];
                if (droppedFile?.type === 'application/pdf') {
                  setFile(droppedFile);
                  setError(null);
                }
              }}
              className={`border-2 border-dashed rounded-xl p-12 flex flex-col items-center justify-center transition-all cursor-pointer ${
                file ? 'border-blue-400 bg-blue-50' : 'border-slate-300 hover:border-blue-400 hover:bg-slate-50'
              }`}
            >
              <input type="file" ref={fileInputRef} className="hidden" accept=".pdf" onChange={handleFileChange} />
              {file ? (
                <div className="text-center">
                  <div className="bg-blue-600 p-3 rounded-full inline-flex mb-4">
                    <FileText className="w-8 h-8 text-white" />
                  </div>
                  <h3 className="font-bold text-slate-900">{file.name}</h3>
                  <p className="text-xs text-slate-500">{(file.size / 1024 / 1024).toFixed(2)} MB</p>
                  <button onClick={(e) => { e.stopPropagation(); setFile(null); }} className="mt-4 text-xs font-bold text-red-500 flex items-center justify-center mx-auto hover:text-red-700">
                    <X className="w-3 h-3 mr-1" /> Remover ficheiro
                  </button>
                </div>
              ) : (
                <div className="text-center">
                  <FileUp className="w-12 h-12 text-slate-300 mb-4 mx-auto" />
                  <p className="text-slate-600 font-medium">Arraste o PDF aqui ou clique para procurar</p>
                  <p className="text-xs text-slate-400 mt-2">Apenas exportações do Citius / Tribunais</p>
                </div>
              )}
            </div>
            {error && (
              <div className="mt-4 flex items-center p-3 bg-red-50 border border-red-100 text-red-700 rounded-lg text-sm">
                <AlertCircle className="w-4 h-4 mr-2" /> {error}
              </div>
            )}
            <button onClick={handleAnalyze} disabled={!file} className="w-full mt-6 py-4 px-6 bg-blue-600 text-white font-bold rounded-xl hover:bg-blue-700 active:scale-[0.98] transition-all flex items-center justify-center space-x-2 disabled:opacity-50 disabled:cursor-not-allowed shadow-lg shadow-blue-200">
              <Upload className="w-5 h-5" />
              <span>Analisar Processo</span>
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (isProcessing) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 space-y-8">
        <div className="relative">
          <div className="w-24 h-24 border-8 border-blue-100 border-t-blue-600 rounded-full animate-spin"></div>
          <Gavel className="absolute inset-0 m-auto w-8 h-8 text-blue-600" />
        </div>
        <div className="text-center space-y-3">
          <h2 className="text-2xl font-bold text-slate-900">
            {processingStep === 'extracting' ? 'Extraindo Texto do PDF' : 'Analisando Estrutura Jurídica'}
          </h2>
          <p className="text-slate-500 flex items-center justify-center italic">
            <Loader2 className="w-4 h-4 animate-spin mr-2" />
            {processingStep === 'extracting' ? 'Processando as páginas localmente...' : 'A IA está a segmentar e resumir os documentos...'}
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      <header className="sticky top-0 z-30 bg-white border-b shadow-sm px-6 py-3 flex items-center justify-between">
        <div className="flex items-center space-x-3">
          <div className="p-1.5 bg-blue-600 rounded-lg">
            <Gavel className="w-5 h-5 text-white" />
          </div>
          <div>
            <h1 className="text-sm font-black text-slate-900 uppercase tracking-tight">Citius Analytics Pro</h1>
            <p className="text-[10px] text-slate-500 font-bold leading-none">{analysis?.numero_processo || 'Processo em análise'}</p>
          </div>
        </div>

        <div className="flex-1 max-w-xl mx-8 relative hidden md:block">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          <input
            type="text"
            placeholder="Pesquisar por texto, referências ou partes..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-2 bg-gray-100 border-transparent focus:bg-white focus:border-blue-500 rounded-lg text-sm transition-all"
          />
        </div>

        <button onClick={() => { setAnalysis(null); setFile(null); }} className="px-4 py-2 text-xs font-bold text-gray-600 hover:bg-gray-100 rounded-lg transition-colors border">
          Novo Ficheiro
        </button>
      </header>

      <div className="flex-1 flex overflow-hidden">
        <aside className="w-72 bg-white border-r hidden lg:flex flex-col p-6 space-y-8 overflow-y-auto">
          {/* Ordenação na Barra Lateral */}
          <div>
            <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-4 flex items-center">
              <SortAsc className="w-3.5 h-3.5 mr-2 text-blue-500" /> Ordenação das Peças
            </h3>
            <div className="flex flex-col bg-slate-50 p-1.5 rounded-2xl border border-slate-200 shadow-inner space-y-1">
              <button 
                onClick={() => setSortOrder('chronological')}
                className={`flex items-center space-x-3 px-4 py-2.5 rounded-xl text-xs font-bold transition-all ${
                  sortOrder === 'chronological' ? 'bg-white text-blue-700 shadow-sm border border-slate-200' : 'text-gray-500 hover:text-gray-700'
                }`}
              >
                <Clock className="w-4 h-4" />
                <span>Cronológica (PDF)</span>
              </button>
              <button 
                onClick={() => setSortOrder('alphabetical')}
                className={`flex items-center space-x-3 px-4 py-2.5 rounded-xl text-xs font-bold transition-all ${
                  sortOrder === 'alphabetical' ? 'bg-white text-blue-700 shadow-sm border border-slate-200' : 'text-gray-500 hover:text-gray-700'
                }`}
              >
                <SortAsc className="w-4 h-4" />
