import { GoogleGenAI, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";

// Inicialização correta conforme as diretrizes
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeProcessText = async (fullText: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Identifique e extraia TODOS os documentos do índice deste processo Citius. 
    Para cada documento, limite o 'texto_integral' aos 500 caracteres mais importantes para garantir que a resposta caiba no limite de tokens do sistema.

    TEXTO DO PROCESSO:\n\n${fullText}`,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      responseMimeType: "application/json",
      temperature: 0.1,
      // Não definimos maxOutputTokens para deixar o modelo usar o máximo disponível sem bloqueios artificiais,
      // confiando na instrução de brevidade do texto_integral.
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          numero_processo: { type: Type.STRING },
          tribunal: { type: Type.STRING },
          juizo: { type: Type.STRING },
          documentos: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id_documento: { type: Type.STRING },
                numero_processo: { type: Type.STRING },
                ref_ato: { type: Type.STRING },
                ref_documento: { type: Type.STRING },
                ref_formulario: { type: Type.STRING },
                tipo_documento_principal: { type: Type.STRING },
                tipo_documento_indice: { type: Type.STRING },
                parte_apresentante: { type: Type.STRING },
                mandatario: { type: Type.STRING },
                pagina_inicial: { type: Type.NUMBER },
                pagina_final: { type: Type.NUMBER },
                titulo_resumido: { type: Type.STRING },
                sumario: { type: Type.STRING },
                texto_integral: { type: Type.STRING },
                data_documento: { type: Type.STRING },
                sub_documentos: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: {
                      id: { type: Type.STRING },
                      titulo: { type: Type.STRING },
                      descricao: { type: Type.STRING },
                      pagina_relativa: { type: Type.NUMBER }
                    }
                  }
                }
              },
              required: ["id_documento", "tipo_documento_principal", "ref_ato", "ref_documento", "pagina_inicial"]
            }
          }
        },
        required: ["numero_processo", "documentos"]
      }
    }
  });

  let jsonText = response.text.trim();

  // Limpeza de possíveis delimitadores
  if (jsonText.startsWith("```")) {
    jsonText = jsonText.replace(/^```(?:json)?\s*/, "").replace(/\s*```$/, "");
  }

  try {
    return JSON.parse(jsonText);
  } catch (e) {
    console.error("Erro crítico de parsing JSON:", e);

    // Tenta uma recuperação mínima se o JSON parecer apenas faltar o fechamento de array/objeto no final
    if (jsonText.length > 1000) {
      try {
        // Tentativa desesperada de fechar o JSON se ele foi truncado no final do array de documentos
        const fixedJson = jsonText.endsWith("}") ? jsonText : jsonText + ']}';
        return JSON.parse(fixedJson);
      } catch (innerError) {
        throw new Error("O processo é demasiado longo para ser analisado de uma só vez. Por favor, tente carregar um ficheiro com menos páginas.");
      }
    }

    throw new Error("Não foi possível processar a estrutura do documento. Tente novamente.");
  }
};

