    // Tentativa de reparação se terminar abruptamente
    if (jsonText.length > 500 && !jsonText.endsWith("}")) {
       try {
         const fixed = jsonText + (jsonText.includes("[") ? "]}" : "}");
         return JSON.parse(fixed);
       } catch (inner) {}
    }
    throw new Error("O processo é demasiado complexo para a análise atual. Tente selecionar um intervalo menor de páginas.");
  }
