              <button onClick={onClose} className="p-2.5 hover:bg-gray-200 rounded-full transition-colors text-gray-400">
                <X className="w-7 h-7" />
              </button>
            </div>
          </div>

          {/* Abas de Navegação Interna */}
          <div className="flex px-10 bg-white border-b">
            <button 
              onClick={() => setActiveTab('summary')}
              className={`px-6 py-4 text-xs font-black uppercase tracking-widest border-b-2 transition-all ${activeTab === 'summary' ? 'border-blue-600 text-blue-600' : 'border-transparent text-gray-400 hover:text-gray-600'}`}
            >
