/**
 * Tenta reparar um JSON que foi cortado abruptamente pela IA.
 * Útil para casos de "Unterminated string" ou arrays/objetos não fechados.
 */
function attemptJsonRepair(jsonStr: string): any {
  let repaired = jsonStr.trim();

  // Se termina dentro de uma string (sem fechar aspas)
  if ((repaired.match(/"/g) || []).length % 2 !== 0) {
    repaired += '"';
  }

  // Tenta fechar níveis de objetos e arrays
  const stack = [];
  for (let i = 0; i < repaired.length; i++) {
    if (repaired[i] === '{') stack.push('}');
    else if (repaired[i] === '[') stack.push(']');
    else if (repaired[i] === '}' || repaired[i] === ']') stack.pop();
  }

  while (stack.length > 0) {
    repaired += stack.pop();
  }

  try {
    return JSON.parse(repaired);
  } catch (e) {
    return null;
  }
}

