import { GoogleGenAI, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Tenta reparar um JSON truncado fechando aspas, objetos e arrays.
 * Fundamental para processos com centenas de documentos que excedem o limite de tokens de saída.
 */
function attemptJsonRepair(jsonStr: string): any {
  let repaired = jsonStr.trim();

  // 1. Limpeza de blocos de código markdown
  repaired = repaired.replace(/^```json\s*/, "").replace(/\s*```$/, "");

  // 2. Correção de aspas pendentes no final (comum em truncagem no meio de uma string)
  if (repaired.endsWith('\\')) repaired = repaired.slice(0, -1);
  const unescapedQuotes = repaired.replace(/\\"/g, '').match(/"/g) || [];
  if (unescapedQuotes.length % 2 !== 0) {
    repaired += '"';
  }

  // 3. Fecho de estruturas (Objetos e Arrays)
  const stack: string[] = [];
  const openChars = ['{', '['];
  const closeChars = ['}', ']'];
  const map: Record<string, string> = { '{': '}', '[': ']' };

  for (let i = 0; i < repaired.length; i++) {
    const char = repaired[i];
    if (openChars.includes(char)) {
      stack.push(map[char]);
    } else if (closeChars.includes(char)) {
      if (stack.length > 0 && stack[stack.length - 1] === char) {
        stack.pop();
      }
    }
  }

  // Se a estrutura estiver incompleta, fechamos de trás para a frente
  while (stack.length > 0) {
    const closer = stack.pop()!;
    // Remove vírgulas residuais antes de fechar o objeto/array
    repaired = repaired.trim().replace(/,$/, "");
    repaired += closer;
  }

  try {
    const parsed = JSON.parse(repaired);
    // Validação mínima para garantir que temos a estrutura básica
    if (parsed && typeof parsed === 'object') return parsed;
    return null;
  } catch (e) {
    // 4. Última tentativa: Cortar o JSON até ao último objeto válido do array de documentos
    try {
      const match = repaired.match(/(.*"documentos"\s*:\s*\[)(.*)/s);
      if (match) {
        const prefix = match[1];
        const list = match[2];
        const lastValidIndex = list.lastIndexOf('}');
        if (lastValidIndex !== -1) {
          const validPart = list.substring(0, lastValidIndex + 1);
          const finalJson = prefix + validPart + ']}';
          return JSON.parse(finalJson);
        }
      }
    } catch (innerE) {
      return null;
    }
    return null;
  }
}

export const analyzeProcessText = async (fullText: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `EXTRATA CADA LINHA DO ÍNDICE COMO UM OBJETO.
    ATENÇÃO: Diferencie as peças! No ato "Petição", o "Formulário" é Tipo 'Formulário Citius', a "Petição" é Tipo 'Petição inicial' e os anexos são Tipo 'Outro'. Não rotule tudo como Petição.

    ULTRA-BREVIDADE: Use apenas 20 caracteres para 'texto_integral' e 80 para 'sumario'. O JSON NÃO PODE SER TRUNCADO.

    TEXTO DO PROCESSO:\n\n${fullText}`,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      responseMimeType: "application/json",
      temperature: 0,
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          numero_processo: { type: Type.STRING },
          tribunal: { type: Type.STRING },
          juizo: { type: Type.STRING },
          documentos: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id_documento: { type: Type.STRING },
                numero_processo: { type: Type.STRING },
                ref_ato: { type: Type.STRING },
                ref_documento: { type: Type.STRING },
                tipo_documento_principal: { type: Type.STRING },
                tipo_documento_indice: { type: Type.STRING },
                parte_apresentante: { type: Type.STRING },
                mandatario: { type: Type.STRING },
                pagina_inicial: { type: Type.NUMBER },
                pagina_final: { type: Type.NUMBER },
                titulo_resumido: { type: Type.STRING },
                sumario: { type: Type.STRING },
                texto_integral: { type: Type.STRING },
                data_documento: { type: Type.STRING },
                sub_documentos: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: {
                      id: { type: Type.STRING },
                      titulo: { type: Type.STRING },
                      descricao: { type: Type.STRING },
                      pagina_pdf: { type: Type.NUMBER }
                    }
                  }
                }
              },
              required: ["id_documento", "tipo_documento_principal", "ref_ato", "ref_documento", "pagina_inicial", "sumario"]
            }
          }
        },
        required: ["numero_processo", "documentos"]
      }
    }
  });

  let jsonText = response.text.trim();
  if (jsonText.startsWith("```")) {
    jsonText = jsonText.replace(/^```(?:json)?\s*/, "").replace(/\s*```$/, "");
  }

  try {
    return JSON.parse(jsonText);
  } catch (e) {
    console.error("Erro inicial de parsing. Tentando reparar JSON truncado...");
    const repaired = attemptJsonRepair(jsonText);
    if (repaired && repaired.documentos && repaired.documentos.length > 0) {
      console.log("JSON reparado com sucesso!");
      return repaired;
    }
    throw new Error("O processo é demasiado longo ou complexo. Tente carregar um intervalo menor de páginas (ex: 50 de cada vez).");
  }
};

import React, { useState, useMemo, useRef } from 'react';
import { DocumentMetadata, ProcessAnalysis, SortOrder } from './types';
import { analyzeProcessText } from './services/geminiService';
