import { GoogleGenAI, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

function attemptJsonRepair(jsonStr: string): any {
  let repaired = jsonStr.trim();
  repaired = repaired.replace(/^```json\s*/, "").replace(/\s*```$/, "");
  if (repaired.endsWith('\\')) repaired = repaired.slice(0, -1);
  const unescapedQuotes = repaired.replace(/\\"/g, '').match(/"/g) || [];
  if (unescapedQuotes.length % 2 !== 0) {
    repaired += '"';
  }
  const stack: string[] = [];
  const openChars = ['{', '['];
  const closeChars = ['}', ']'];
  const map: Record<string, string> = { '{': '}', '[': ']' };
  for (let i = 0; i < repaired.length; i++) {
    const char = repaired[i];
    if (openChars.includes(char)) {
      stack.push(map[char]);
    } else if (closeChars.includes(char)) {
      if (stack.length > 0 && stack[stack.length - 1] === char) {
        stack.pop();
      }
    }
  }
  while (stack.length > 0) {
    const closer = stack.pop()!;
    repaired = repaired.trim().replace(/,$/, "");
    repaired += closer;
  }
  try {
    const parsed = JSON.parse(repaired);
    if (parsed && typeof parsed === 'object') return parsed;
    return null;
  } catch (e) {
    try {
      const match = repaired.match(/(.*"documentos"\s*:\s*\[)(.*)/s);
      if (match) {
        const prefix = match[1];
        const list = match[2];
        const lastValidIndex = list.lastIndexOf('}');
        if (lastValidIndex !== -1) {
          const validPart = list.substring(0, lastValidIndex + 1);
          const finalJson = prefix + validPart + ']}';
          return JSON.parse(finalJson);
        }
      }
    } catch (innerE) {
      return null;
    }
    return null;
  }
}

export const analyzeProcessText = async (fullText: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `PROCESSE TODAS AS LINHAS DO ÍNDICE. NÃO SALTE NENHUMA.

    Cada 'Ref Doc' no índice DEVE ser um objeto independente no array 'documentos'.
    Exemplo: Se há 8 documentos "Outro" com números de referência diferentes (23003766 a 23003772), você deve criar 7 objetos separados, um para cada.

    Identifique o conteúdo real de cada "Outro" (ex: "Recibo de vencimento", "Contrato") lendo o início do texto na página correspondente.

    TEXTO DO PROCESSO:\n\n${fullText}`,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      responseMimeType: "application/json",
      temperature: 0,
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          numero_processo: { type: Type.STRING },
          tribunal: { type: Type.STRING },
          juizo: { type: Type.STRING },
          documentos: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id_documento: { type: Type.STRING },
                numero_processo: { type: Type.STRING },
                ref_ato: { type: Type.STRING },
                ref_documento: { type: Type.STRING },
                tipo_documento_principal: { type: Type.STRING },
                tipo_documento_indice: { type: Type.STRING },
                parte_apresentante: { type: Type.STRING },
                mandatario: { type: Type.STRING },
                pagina_inicial: { type: Type.NUMBER },
                pagina_final: { type: Type.NUMBER },
                titulo_resumido: { type: Type.STRING },
                sumario: { type: Type.STRING },
                texto_integral: { type: Type.STRING },
                data_documento: { type: Type.STRING },
                sub_documentos: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: {
                      id: { type: Type.STRING },
                      titulo: { type: Type.STRING },
                      descricao: { type: Type.STRING },
                      pagina_pdf: { type: Type.NUMBER }
                    }
                  }
                }
              },
              required: ["id_documento", "tipo_documento_principal", "ref_ato", "ref_documento", "pagina_inicial", "sumario"]
            }
          }
        },
        required: ["numero_processo", "documentos"]
      }
    }
  });

  let jsonText = response.text.trim();
  if (jsonText.startsWith("```")) {
    jsonText = jsonText.replace(/^```(?:json)?\s*/, "").replace(/\s*```$/, "");
  }

  try {
    return JSON.parse(jsonText);
  } catch (e) {
    const repaired = attemptJsonRepair(jsonText);
    if (repaired && repaired.documentos) return repaired;
    throw new Error("Erro crítico na análise. O índice é demasiado extenso para uma única passagem.");
  }
};

