import { GoogleGenAI, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Função de reparação de JSON existente mantida...
function attemptJsonRepair(jsonStr: string): any {
  let repaired = jsonStr.trim();
  repaired = repaired.replace(/^```json\s*/, "").replace(/\s*```$/, "");
  if (repaired.endsWith('\\')) repaired = repaired.slice(0, -1);
  const unescapedQuotes = repaired.replace(/\\"/g, '').match(/"/g) || [];
  if (unescapedQuotes.length % 2 !== 0) {
    repaired += '"';
  }
  const stack: string[] = [];
  const openChars = ['{', '['];
  const closeChars = ['}', ']'];
  const map: Record<string, string> = { '{': '}', '[': ']' };
  for (let i = 0; i < repaired.length; i++) {
    const char = repaired[i];
    if (openChars.includes(char)) {
      stack.push(map[char]);
    } else if (closeChars.includes(char)) {
      if (stack.length > 0 && stack[stack.length - 1] === char) {
        stack.pop();
      }
    }
  }
  while (stack.length > 0) {
    const closer = stack.pop()!;
    repaired = repaired.trim().replace(/,$/, "");
    repaired += closer;
  }
  try {
    const parsed = JSON.parse(repaired);
    if (parsed && typeof parsed === 'object') return parsed;
    return null;
  } catch (e) {
    try {
      const match = repaired.match(/(.*"documentos"\s*:\s*\[)(.*)/s);
      if (match) {
        const prefix = match[1];
        const list = match[2];
        const lastValidIndex = list.lastIndexOf('}');
        if (lastValidIndex !== -1) {
          const validPart = list.substring(0, lastValidIndex + 1);
          const finalJson = prefix + validPart + ']}';
          return JSON.parse(finalJson);
        }
      }
    } catch (innerE) {
      return null;
    }
    return null;
  }
}

export const analyzeProcessText = async (fullText: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `PROCESSE TODAS AS LINHAS DO ÍNDICE. NÃO SALTE NENHUMA.

    Cada 'Ref Doc' no índice DEVE ser um objeto independente no array 'documentos'.
    Exemplo: Se há 8 documentos "Outro" com números de referência diferentes (23003766 a 23003772), você deve criar 7 objetos separados, um para cada.

    Identifique o conteúdo real de cada "Outro" (ex: "Recibo de vencimento", "Contrato") lendo o início do texto na página correspondente.

    TEXTO DO PROCESSO:\n\n${fullText}`,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      responseMimeType: "application/json",
      temperature: 0,
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          numero_processo: { type: Type.STRING },
          tribunal: { type: Type.STRING },
          juizo: { type: Type.STRING },
          documentos: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id_documento: { type: Type.STRING },
                numero_processo: { type: Type.STRING },
                ref_ato: { type: Type.STRING },
                ref_documento: { type: Type.STRING },
                tipo_documento_principal: { type: Type.STRING },
                tipo_documento_indice: { type: Type.STRING },
                parte_apresentante: { type: Type.STRING },
                mandatario: { type: Type.STRING },
                pagina_inicial: { type: Type.NUMBER },
                pagina_final: { type: Type.NUMBER },
                titulo_resumido: { type: Type.STRING },
                sumario: { type: Type.STRING },
                texto_integral: { type: Type.STRING },
                data_documento: { type: Type.STRING },
                sub_documentos: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: {
                      id: { type: Type.STRING },
                      titulo: { type: Type.STRING },
                      descricao: { type: Type.STRING },
                      pagina_pdf: { type: Type.NUMBER }
                    }
                  }
                }
              },
              required: ["id_documento", "tipo_documento_principal", "ref_ato", "ref_documento", "pagina_inicial", "sumario"]
            }
          }
        },
        required: ["numero_processo", "documentos"]
      }
    }
  });

  let jsonText = response.text.trim();
  if (jsonText.startsWith("```")) {
    jsonText = jsonText.replace(/^```(?:json)?\s*/, "").replace(/\s*```$/, "");
  }

  try {
    return JSON.parse(jsonText);
  } catch (e) {
    const repaired = attemptJsonRepair(jsonText);
    if (repaired && repaired.documentos) return repaired;
    throw new Error("Erro crítico na análise. O índice é demasiado extenso para uma única passagem.");
  }
};

export const analyzeArticuladoFacts = async (articuladoText: string, allDocsMetadata: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Analise o articulado jurídico fornecido e extraia a relação entre Factos (Artigos) e Provas (Documentos).

    INSTRUÇÕES:
    1. Identifique cada parágrafo numerado (Artigo) no articulado.
    2. Para cada artigo, verifique se há referências explícitas a documentos (ex: "conforme doc. 1", "vidé anexo", "recibo junto").
    3. Se não houver referência explícita, use inferência lógica para associar o facto aos documentos listados nos metadados do processo.
    4. Retorne apenas os artigos que possuem provas relacionadas.

    METADADOS DOS DOCUMENTOS DO PROCESSO:
    ${allDocsMetadata}

    TEXTO DO ARTICULADO:
    ${articuladoText}`,
    config: {
      systemInstruction: "Você é um perito em análise forense. Sua tarefa é mapear a prova documental aos factos alegados num articulado. Responda em JSON.",
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          mappings: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                artigo: { type: Type.STRING, description: "Número do artigo/parágrafo" },
                texto_artigo: { type: Type.STRING, description: "Texto integral do artigo" },
                documentos_refs: { 
                  type: Type.ARRAY, 
                  items: { type: Type.STRING },
                  description: "Lista de 'Ref Doc' (referências de documentos) associadas"
                }
              },
              required: ["artigo", "texto_artigo", "documentos_refs"]
            }
          }
        },
        required: ["mappings"]
      }
    }
  });

  return JSON.parse(response.text);
};

import React, { useState } from 'react';
import { DocumentMetadata, DocumentType, ArticuladoAnalysis, FactMapping } from '../types';
import { analyzeArticuladoFacts } from '../services/geminiService';
import { FileText, Play, Table as TableIcon, CheckCircle2, Info, ExternalLink, Loader2, X } from 'lucide-react';

interface FactAnalysisViewProps {
  documents: DocumentMetadata[];
  file: File | null;
}

export const FactAnalysisView: React.FC<FactAnalysisViewProps> = ({ documents, file }) => {
  const [selectedDocs, setSelectedDocs] = useState<string[]>([]);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [results, setResults] = useState<ArticuladoAnalysis[]>([]);
  const [modalContent, setModalContent] = useState<FactMapping | null>(null);

  const articulados = documents.filter(doc => 
    [DocumentType.PETICAO_INICIAL, DocumentType.CONTESTACAO, DocumentType.REQUERIMENTO, DocumentType.ALEGACOES_RECURSO].includes(doc.tipo_documento_principal)
  );

  const toggleSelection = (id: string) => {
    setSelectedDocs(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const handleProcess = async () => {
    if (selectedDocs.length === 0) return;
    setIsAnalyzing(true);

    try {
      const allMetadataString = documents.map(d => 
        `Ref Doc: ${d.ref_documento} | Titulo: ${d.titulo_resumido} | Sumario: ${d.sumario}`
      ).join('\n');

      const newResults: ArticuladoAnalysis[] = [];

      for (const id of selectedDocs) {
        const doc = documents.find(d => d.id_documento === id);
        if (doc) {
          const analysis = await analyzeArticuladoFacts(doc.texto_integral, allMetadataString);
          newResults.push({
            id_documento: doc.id_documento,
            titulo: doc.titulo_resumido,
            mappings: analysis.mappings
          });
        }
      }
      setResults(newResults);
    } catch (error) {
      console.error(error);
      alert("Erro ao processar factos. Tente novamente.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const openPdfByRef = (refDoc: string) => {
    const doc = documents.find(d => d.ref_documento === refDoc);
    if (doc && file) {
      const fileUrl = URL.createObjectURL(file);
      window.open(`${fileUrl}#page=${doc.pagina_inicial}`, '_blank');
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
        <h3 className="text-lg font-black text-slate-900 mb-6 flex items-center">
          <FileText className="w-5 h-5 mr-2 text-blue-600" /> Seleção de Articulados para Análise
        </h3>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 mb-8">
          {articulados.map(doc => (
            <div 
              key={doc.id_documento}
              onClick={() => toggleSelection(doc.id_documento)}
              className={`p-4 rounded-2xl border-2 cursor-pointer transition-all flex items-center space-x-4 ${
                selectedDocs.includes(doc.id_documento) 
                  ? 'border-blue-600 bg-blue-50 shadow-md' 
                  : 'border-slate-100 bg-slate-50 hover:border-slate-300'
              }`}
            >
              <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center ${
                selectedDocs.includes(doc.id_documento) ? 'bg-blue-600 border-blue-600' : 'bg-white border-slate-300'
              }`}>
                {selectedDocs.includes(doc.id_documento) && <CheckCircle2 className="w-3 h-3 text-white" />}
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-[10px] font-black uppercase text-blue-600 truncate">{doc.tipo_documento_principal}</p>
                <p className="text-xs font-bold text-slate-800 truncate">{doc.titulo_resumido}</p>
              </div>
            </div>
          ))}
        </div>

        <button 
          onClick={handleProcess}
          disabled={isAnalyzing || selectedDocs.length === 0}
          className="w-full py-4 bg-blue-600 text-white font-black rounded-2xl flex items-center justify-center space-x-3 hover:bg-blue-700 transition-all shadow-xl shadow-blue-100 disabled:opacity-50 uppercase tracking-widest text-xs"
        >
          {isAnalyzing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Play className="w-4 h-4" />}
          <span>Relacionar Factos e Provas</span>
        </button>
      </div>

      <div className="space-y-12">
        {results.map(res => (
          <div key={res.id_documento} className="bg-white rounded-3xl border border-slate-200 overflow-hidden shadow-sm">
            <div className="bg-slate-900 px-8 py-5 flex items-center justify-between">
              <h4 className="text-white font-black text-sm uppercase tracking-wider flex items-center">
                <TableIcon className="w-4 h-4 mr-3 text-blue-400" /> Mapa de Prova: {res.titulo}
              </h4>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b border-slate-200">
                    <th className="px-8 py-4 text-[10px] font-black uppercase text-slate-400 tracking-widest w-24 text-center">Artigo</th>
                    <th className="px-8 py-4 text-[10px] font-black uppercase text-slate-400 tracking-widest">Documentos de Prova Relacionados</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {res.mappings.map((m, i) => (
                    <tr key={i} className="hover:bg-slate-50/50 transition-colors">
                      <td className="px-8 py-6 align-top text-center">
                        <button 
                          onClick={() => setModalContent(m)}
                          className="w-10 h-10 rounded-xl bg-blue-50 text-blue-600 font-black hover:bg-blue-600 hover:text-white transition-all border border-blue-100 shadow-sm flex items-center justify-center mx-auto"
                        >
                          {m.artigo}
                        </button>
                      </td>
                      <td className="px-8 py-6">
                        <div className="flex flex-wrap gap-2">
                          {m.documentos_refs.map(ref => {
                            const found = documents.find(d => d.ref_documento === ref);
                            return (
                              <button 
                                key={ref}
                                onClick={() => openPdfByRef(ref)}
                                className="inline-flex items-center px-4 py-2 bg-white border border-slate-200 rounded-xl text-[10px] font-black text-slate-700 hover:border-blue-500 hover:text-blue-600 transition-all shadow-sm group"
                              >
                                <ExternalLink className="w-3 h-3 mr-2 text-slate-300 group-hover:text-blue-500" />
                                {found ? found.titulo_resumido : `Doc. Ref ${ref}`}
                              </button>
                            );
                          })}
                          {m.documentos_refs.length === 0 && <span className="text-xs italic text-slate-400">Nenhum documento correlacionado.</span>}
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        ))}
      </div>

      {modalContent && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm p-6">
          <div className="bg-white w-full max-w-2xl rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200 border border-white/20">
            <div className="px-8 py-6 border-b flex justify-between items-center bg-slate-50">
              <div className="flex items-center space-x-3">
                <div className="bg-blue-600 text-white w-8 h-8 rounded-lg flex items-center justify-center font-black">
                  {modalContent.artigo}
                </div>
                <h3 className="font-black text-slate-900 uppercase text-xs tracking-widest">Texto do Articulado</h3>
              </div>
              <button onClick={() => setModalContent(null)} className="p-2 hover:bg-slate-200 rounded-full text-slate-400">
                <X className="w-5 h-5" />
              </button>
            </div>
