            <div className="bg-slate-50 p-1.5 rounded-2xl border flex flex-col space-y-1">
              <button onClick={() => setSortOrder('chronological')} className={`flex items-center space-x-3 px-3 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${sortOrder === 'chronological' ? 'bg-white shadow-sm border text-blue-600' : 'text-slate-400'}`}>
