export const FactAnalysisView: React.FC<FactAnalysisViewProps> = ({ documents, file }) => {
  const [selectedDocs, setSelectedDocs] = useState<string[]>([]);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [results, setResults] = useState<ArticuladoAnalysis[]>([]);
  const [modalContent, setModalContent] = useState<FactMapping | null>(null);
  const [filterQuery, setFilterQuery] = useState('');

  const filteredSelectionList = useMemo(() => {
    return documents.filter(doc => {
      const query = filterQuery.toLowerCase();
      return doc.titulo_resumido.toLowerCase().includes(query) || 
             doc.tipo_documento_principal.toLowerCase().includes(query) ||
             doc.ref_documento.includes(filterQuery);
    });
  }, [documents, filterQuery]);

  const toggleSelection = (id: string) => {
    setSelectedDocs(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const handleProcess = async () => {
    if (selectedDocs.length === 0) return;
    setIsAnalyzing(true);

    try {
      const allMetadataString = documents.map(d => 
        `Ref Doc: ${d.ref_documento} | Titulo: ${d.titulo_resumido} | Tipo: ${d.tipo_documento_principal} | Sumario: ${d.sumario}`
      ).join('\n');

      const newResults: ArticuladoAnalysis[] = [];

      for (const id of selectedDocs) {
        const doc = documents.find(d => d.id_documento === id);
        if (doc) {
          const analysis = await analyzeArticuladoFacts(doc.texto_integral, allMetadataString);
          newResults.push({
            id_documento: doc.id_documento,
            titulo: doc.titulo_resumido,
            mappings: analysis.mappings
          });
        }
      }
      setResults(newResults);
    } catch (error) {
      console.error(error);
      alert("Erro ao processar. Verifique se a IA retornou dados válidos.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const openPdfByRef = (refDoc: string) => {
    const doc = documents.find(d => d.ref_documento === refDoc);
    if (doc && file) {
      const fileUrl = URL.createObjectURL(file);
      window.open(`${fileUrl}#page=${doc.pagina_inicial}`, '_blank');
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
          <div>
            <h3 className="text-lg font-black text-slate-900 flex items-center">
              <FileText className="w-5 h-5 mr-2 text-blue-600" /> Seletor de Peças para Correlação
            </h3>
            <p className="text-xs text-slate-500 font-bold uppercase tracking-wider mt-1">
              Escolha as peças (Petições, Contestações, Requerimentos) para mapear factos.
            </p>
          </div>

          <div className="relative w-full md:w-72">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
            <input 
              type="text"
              placeholder="Pesquisar na lista..."
              value={filterQuery}
              onChange={(e) => setFilterQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-2 bg-slate-50 border-transparent focus:bg-white focus:border-blue-500 rounded-xl text-xs font-bold transition-all border"
            />
          </div>
        </div>

        <div className="max-h-[400px] overflow-y-auto border border-slate-100 rounded-2xl bg-slate-50/50 p-4 mb-8 space-y-2">
          {filteredSelectionList.map(doc => {
             const colorClass = TYPE_COLORS[doc.tipo_documento_principal] || 'bg-gray-100 text-gray-800 border-gray-200';
             const isSelected = selectedDocs.includes(doc.id_documento);
             return (
              <div 
                key={doc.id_documento}
                onClick={() => toggleSelection(doc.id_documento)}
                className={`flex items-center space-x-4 p-3 rounded-xl border-2 transition-all cursor-pointer ${
                  isSelected ? 'border-blue-600 bg-white shadow-md' : 'border-transparent bg-white/50 hover:bg-white hover:border-slate-200'
                }`}
              >
                <div className={`w-5 h-5 rounded-md border-2 flex items-center justify-center transition-colors ${
                  isSelected ? 'bg-blue-600 border-blue-600' : 'bg-white border-slate-300'
                }`}>
                  {isSelected && <CheckCircle2 className="w-3.5 h-3.5 text-white" />}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center space-x-2">
                    <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase border tracking-widest ${colorClass}`}>
                      {doc.tipo_documento_principal}
                    </span>
                    <span className="text-[10px] font-black text-slate-400">Ref: {doc.ref_documento}</span>
                  </div>
                  <h4 className="text-[13px] font-bold text-slate-800 truncate">{doc.titulo_resumido}</h4>
                </div>
                <span className="text-[10px] font-black text-slate-400 px-3">Pág. {doc.pagina_inicial}</span>
              </div>
             );
          })}
        </div>

        <button 
          onClick={handleProcess}
          disabled={isAnalyzing || selectedDocs.length === 0}
          className="w-full py-4 bg-blue-600 text-white font-black rounded-2xl flex items-center justify-center space-x-3 hover:bg-blue-700 transition-all shadow-xl shadow-blue-100 disabled:opacity-50 uppercase tracking-widest text-xs"
        >
          {isAnalyzing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Play className="w-4 h-4" />}
          <span>Relacionar Factos e Provas ({selectedDocs.length})</span>
        </button>
      </div>

      <div className="space-y-12">
        {results.map(res => (
          <div key={res.id_documento} className="bg-white rounded-3xl border border-slate-200 overflow-hidden shadow-sm animate-in slide-in-from-bottom-4">
