import { GoogleGenAI, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

function attemptJsonRepair(jsonStr: string): any {
  let repaired = jsonStr.trim();
  repaired = repaired.replace(/^```json\s*/, "").replace(/\s*```$/, "");
  if (repaired.endsWith('\\')) repaired = repaired.slice(0, -1);
  const unescapedQuotes = repaired.replace(/\\"/g, '').match(/"/g) || [];
  if (unescapedQuotes.length % 2 !== 0) {
    repaired += '"';
  }
  const stack: string[] = [];
  const openChars = ['{', '['];
  const closeChars = ['}', ']'];
  const map: Record<string, string> = { '{': '}', '[': ']' };
  for (let i = 0; i < repaired.length; i++) {
    const char = repaired[i];
    if (openChars.includes(char)) {
      stack.push(map[char]);
    } else if (closeChars.includes(char)) {
      if (stack.length > 0 && stack[stack.length - 1] === char) {
        stack.pop();
      }
    }
  }
  while (stack.length > 0) {
    const closer = stack.pop()!;
    repaired = repaired.trim().replace(/,$/, "");
    repaired += closer;
  }
  try {
    return JSON.parse(repaired);
  } catch (e) {
    return null;
  }
}

/**
 * Utilitário para extrair texto entre páginas específicas do log de texto bruto do PDF
 */
export const sliceTextByPages = (fullText: string, startPage: number, endPage: number): string => {
  const lines = fullText.split('\n');
  let result = "";
  let capturing = false;

  // Se a página final não for informada, assume-se a página seguinte do índice ou fim do PDF
  const end = endPage || startPage + 5; 

  for (const line of lines) {
    const match = line.match(/--- PÁGINA (\d+) ---/);
    if (match) {
      const pageNum = parseInt(match[1]);
      if (pageNum === startPage) capturing = true;
      if (pageNum > end) capturing = false;
    }
    if (capturing) result += line + "\n";
  }
  return result;
};

export const analyzeProcessText = async (fullText: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Analise este processo judicial.
    REGRAS:
    1. Identifique cada linha do índice.
    2. Atribua pagina_inicial e pagina_final corretamente.
    3. Crie sumários breves.

    TEXTO:\n\n${fullText}`,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      responseMimeType: "application/json",
      temperature: 0,
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          numero_processo: { type: Type.STRING },
          tribunal: { type: Type.STRING },
