import { GoogleGenAI, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

function attemptJsonRepair(jsonStr: string): any {
  let repaired = jsonStr.trim();
  repaired = repaired.replace(/^```json\s*/, "").replace(/\s*```$/, "");
  if (repaired.endsWith('\\')) repaired = repaired.slice(0, -1);
  const unescapedQuotes = repaired.replace(/\\"/g, '').match(/"/g) || [];
  if (unescapedQuotes.length % 2 !== 0) {
    repaired += '"';
  }
  const stack: string[] = [];
  const openChars = ['{', '['];
  const closeChars = ['}', ']'];
  const map: Record<string, string> = { '{': '}', '[': ']' };
  for (let i = 0; i < repaired.length; i++) {
    const char = repaired[i];
    if (openChars.includes(char)) {
      stack.push(map[char]);
    } else if (closeChars.includes(char)) {
      if (stack.length > 0 && stack[stack.length - 1] === char) {
        stack.pop();
      }
    }
  }
  while (stack.length > 0) {
    const closer = stack.pop()!;
    repaired = repaired.trim().replace(/,$/, "");
    repaired += closer;
  }
  try {
    return JSON.parse(repaired);
  } catch (e) {
    return null;
  }
}

/**
 * Fatiamento robusto de texto baseado em índices de busca
 */
export const sliceTextByPages = (fullText: string, startPage: number, endPage: number): string => {
  const startMarker = `--- PÁGINA ${startPage} ---`;
  // Capturamos até a página seguinte à final para garantir o conteúdo completo
  const endMarker = `--- PÁGINA ${(endPage || startPage) + 1} ---`;

  const startIndex = fullText.indexOf(startMarker);
  if (startIndex === -1) return "";

  let endIndex = fullText.indexOf(endMarker, startIndex + startMarker.length);

  // Se não encontrar o próximo marcador (fim do doc), pega até o fim do texto
  if (endIndex === -1) {
    return fullText.substring(startIndex);
  }

  return fullText.substring(startIndex, endIndex);
};

export const analyzeProcessText = async (fullText: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Analise este processo judicial português.
    MISSÃO: Mapear a estrutura do PDF.
    1. Identifique cada linha do índice (Refª Ato, Refª Doc, Página).
    2. Determine com precisão a página inicial e final de cada peça.

    TEXTO:\n\n${fullText}`,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      responseMimeType: "application/json",
      temperature: 0,
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          numero_processo: { type: Type.STRING },
          tribunal: { type: Type.STRING },
          juizo: { type: Type.STRING },
          documentos: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id_documento: { type: Type.STRING },
                ref_ato: { type: Type.STRING },
                ref_documento: { type: Type.STRING },
                tipo_documento_principal: { type: Type.STRING },
                tipo_documento_indice: { type: Type.STRING },
                parte_apresentante: { type: Type.STRING },
                mandatario: { type: Type.STRING },
                pagina_inicial: { type: Type.NUMBER },
                pagina_final: { type: Type.NUMBER },
                titulo_resumido: { type: Type.STRING },
                sumario: { type: Type.STRING },
                data_documento: { type: Type.STRING }
              },
              required: ["id_documento", "ref_ato", "ref_documento", "pagina_inicial"]
            }
          }
        },
        required: ["numero_processo", "documentos"]
      }
    }
  });

  let jsonText = response.text.trim();
  try {
    return JSON.parse(jsonText);
  } catch (e) {
    return attemptJsonRepair(jsonText) || { documentos: [] };
  }
};

