export const FactAnalysisView: React.FC<FactAnalysisViewProps> = ({ documents, file, rawText }) => {
  const [selectedDocs, setSelectedDocs] = useState<string[]>([]);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [results, setResults] = useState<ArticuladoAnalysis[]>([]);
  const [modalContent, setModalContent] = useState<FactMapping | null>(null);
  const [filterQuery, setFilterQuery] = useState('');

  const filteredSelectionList = useMemo(() => {
    return documents.filter(doc => {
      const query = filterQuery.toLowerCase();
      return doc.titulo_resumido.toLowerCase().includes(query) || 
             doc.tipo_documento_principal.toLowerCase().includes(query) ||
             doc.ref_documento.includes(filterQuery);
    });
  }, [documents, filterQuery]);

  const toggleSelection = (id: string) => {
    setSelectedDocs(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const handleProcess = async () => {
    if (selectedDocs.length === 0) return;
    setIsAnalyzing(true);
    setResults([]); 

    try {
      // Metadados enriquecidos para a IA conseguir ligar "Doc 1" ao Ref Doc real
      const allMetadataString = documents
        .sort((a, b) => a.pagina_inicial - b.pagina_inicial)
        .map((d, index) => {
          // Tenta adivinhar se é um "Doc X" baseado na ordem em que aparece após o formulário
          return `[Ref Doc: ${d.ref_documento}] Titulo: ${d.titulo_resumido} | Sugestão de referência: Doc ${index + 1} | Tipo: ${d.tipo_documento_principal}`;
        }).join('\n');

      const newResults: ArticuladoAnalysis[] = [];

      for (const id of selectedDocs) {
        const doc = documents.find(d => d.id_documento === id);
        if (doc) {
          const literalText = sliceTextByPages(rawText, doc.pagina_inicial, doc.pagina_final);

          if (!literalText || literalText.length < 100) {
             console.warn("Texto extraído muito curto para o doc:", doc.id_documento);
          }

          const analysis = await analyzeArticuladoFacts(literalText, allMetadataString);

          if (analysis && analysis.mappings && analysis.mappings.length > 0) {
            newResults.push({
              id_documento: doc.id_documento,
              titulo: doc.titulo_resumido,
              mappings: analysis.mappings
            });
          } else {
            newResults.push({
              id_documento: doc.id_documento,
              titulo: doc.titulo_resumido,
              mappings: []
            });
          }
        }
      }
      setResults(newResults);
    } catch (error) {
      console.error(error);
