  const [activeFilter, setActiveFilter] = useState<string>('all');
  const [sortOrder, setSortOrder] = useState<SortOrder>('chronological');
  const [error, setError] = useState<{ message: string; isQuota?: boolean } | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [activeTab, setActiveTab] = useState<'timeline' | 'facts'>('timeline');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const jsonInputRef = useRef<HTMLInputElement>(null);

  const handleOpenKeySelection = async () => {
    try {
      await window.aistudio.openSelectKey();
      setError(null);
    } catch (err) {
      console.error("Failed to open key selection", err);
    }
  };

  const validateAndSetFile = (selectedFile: File) => {
    if (selectedFile && selectedFile.type === 'application/pdf') {
      setFile(selectedFile);
      setError(null);
    } else {
      setError({ message: 'Por favor, selecione apenas ficheiros PDF para análise.' });
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile) validateAndSetFile(selectedFile);
  };

  const handleAnalyze = async () => {
    if (!file) return;
    setIsProcessing(true);
    setError(null);
    try {
      setProcessingStep('extracting');
      const extractedText = await extractTextFromPdf(file);
      setRawText(extractedText);
      setProcessingStep('analyzing');
      const result = await analyzeProcessText(extractedText);
      setAnalysis(result);
    } catch (err: any) {
      console.error(err);
      const isQuota = err?.message?.includes('429') || err?.status === 429;
      const isNotFound = err?.message?.includes('Requested entity was not found');

      setError({ 
        message: isQuota 
          ? 'Limite de cota excedido. Por favor, utilize a sua própria chave da API para continuar.' 
          : isNotFound 
            ? 'Projeto ou chave não encontrada. Por favor, selecione novamente a sua chave da API.'
            : 'Erro ao processar o ficheiro. Certifique-se que o PDF não é protegido.',
        isQuota: isQuota || isNotFound
      });
    } finally {
      setIsProcessing(false);
      setProcessingStep(null);
    }
  };

  const handleSaveProject = () => {
    if (!analysis) return;
    const projectData = { ...analysis, _rawText: rawText };
    const blob = new Blob([JSON.stringify(projectData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Citius_Project_${analysis.numero_processo.replace(/\//g, '_') || 'Export'}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleLoadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (!selectedFile) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json && json.documentos) {
          setAnalysis(json);
          if (json._rawText) setRawText(json._rawText);
          setFile(null);
          setError(null);
        } else {
          setError({ message: 'O ficheiro JSON selecionado não é um projeto Citius Pro válido.' });
        }
      } catch (err) {
        setError({ message: 'Erro ao ler o ficheiro JSON.' });
      }
    };
    reader.readAsText(selectedFile);
    e.target.value = '';
  };

  const groupedDocs = useMemo(() => {
    if (!analysis) return [];
    const query = searchQuery.toLowerCase();

    let baseDocs = analysis.documentos.filter(doc => {
      const titulo = (doc.titulo_resumido || '').toLowerCase();
      const sumario = (doc.sumario || '').toLowerCase();
      const apresentante = (doc.parte_apresentante || '').toLowerCase();
      const refAto = (doc.ref_ato || '');
      const refDoc = (doc.ref_documento || '');

      const matchesSearch = 
        titulo.includes(query) ||
        sumario.includes(query) ||
        apresentante.includes(query) ||
        refAto.includes(searchQuery) ||
        refDoc.includes(searchQuery);

      const matchesFilter = activeFilter === 'all' || doc.tipo_documento_principal === activeFilter;
      return matchesSearch && matchesFilter;
    });

    if (sortOrder === 'alphabetical') {
      baseDocs.sort((a, b) => (a.titulo_resumido || '').localeCompare(b.titulo_resumido || ''));
    } else {
      baseDocs.sort((a, b) => (a.pagina_inicial || 0) - (b.pagina_inicial || 0));
    }

    const groups: { refAto: string, docs: DocumentMetadata[] }[] = [];
    const seenRefs = new Set<string>();

    baseDocs.forEach(doc => {
      const ref = doc.ref_ato || 'Sem Ref';
      if (!seenRefs.has(ref)) {
        seenRefs.add(ref);
        groups.push({
          refAto: ref,
          docs: baseDocs.filter(d => d.ref_ato === ref)
        });
      }
    });

    return groups;
  }, [analysis, searchQuery, activeFilter, sortOrder]);

  const docTypes = useMemo(() => {
    if (!analysis) return [];
    const types = Array.from(new Set(analysis.documentos.map(d => d.tipo_documento_principal).filter(Boolean)));
    return types.sort((a, b) => a.localeCompare(b));
  }, [analysis]);

  const incidentSiblings = useMemo(() => {
    if (!selectedDoc || !analysis) return [];
    return analysis.documentos.filter(d => d.ref_ato === selectedDoc.ref_ato);
  }, [selectedDoc, analysis]);

  if (!analysis && !isProcessing) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 text-slate-900">
        <div className="w-full max-w-2xl space-y-8 animate-in slide-in-from-bottom-4 duration-500">
          <div className="text-center">
            <div className="inline-flex items-center justify-center p-3 bg-blue-600 rounded-2xl shadow-lg mb-4">
              <Gavel className="w-10 h-10 text-white" />
            </div>
            <h1 className="text-4xl font-black tracking-tight">Citius Analytics Pro</h1>
            <p className="mt-3 text-lg text-slate-600 max-w-lg mx-auto leading-relaxed">
              Análise inteligente de processos judiciais exportados.
            </p>
          </div>

          <div className="bg-white p-8 rounded-3xl shadow-2xl border border-slate-200">
            <div 
              onClick={() => fileInputRef.current?.click()}
              onDragOver={handleDragOver}
              onDragEnter={handleDragEnter}
              onDragLeave={handleDragLeave}
              onDrop={handleDrop}
              className={`border-2 border-dashed rounded-2xl p-12 flex flex-col items-center justify-center transition-all cursor-pointer ${
                isDragging ? 'border-blue-600 bg-blue-100 scale-[1.02]' : 
                file ? 'border-blue-400 bg-blue-50' : 'border-slate-300 hover:border-blue-400 hover:bg-slate-50'
              }`}
            >
              <input type="file" ref={fileInputRef} className="hidden" accept=".pdf" onChange={handleFileChange} />
              {file ? (
                <div className="text-center">
                  <FileText className="w-12 h-12 text-blue-600 mb-4 mx-auto" />
                  <h3 className="font-black text-slate-900">{file.name}</h3>
                  <button onClick={(e) => { e.stopPropagation(); setFile(null); }} className="mt-4 text-xs font-bold text-red-500 uppercase tracking-widest hover:text-red-700">
                    Remover ficheiro
                  </button>
                </div>
              ) : (
                <div className="text-center">
                  <FileUp className={`w-12 h-12 mb-4 mx-auto transition-colors ${isDragging ? 'text-blue-600' : 'text-slate-300'}`} />
                  <p className="text-slate-600 font-bold">
                    {isDragging ? 'Solte o ficheiro aqui' : 'Arraste o PDF ou clique para procurar'}
                  </p>
                </div>
              )}
            </div>

            {error && (
              <div className={`mt-4 p-4 rounded-xl border flex items-start gap-3 ${error.isQuota ? 'bg-amber-50 border-amber-200 text-amber-800' : 'bg-red-50 border-red-200 text-red-700'}`}>
                {error.isQuota ? <AlertTriangle className="w-5 h-5 shrink-0 mt-0.5" /> : <AlertTriangle className="w-5 h-5 shrink-0 mt-0.5" />}
                <div className="flex-1">
                  <p className="text-xs font-bold leading-relaxed">{error.message}</p>
                  {error.isQuota && (
                    <div className="mt-3 flex flex-wrap gap-3">
                      <button 
                        onClick={handleOpenKeySelection}
                        className="flex items-center gap-2 bg-amber-600 text-white px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-wider hover:bg-amber-700 transition-colors"
                      >
                        <Key className="w-3.5 h-3.5" /> Configurar Chave Própria
                      </button>
                      <a 
                        href="https://ai.google.dev/gemini-api/docs/billing" 
                        target="_blank" 
                        rel="noreferrer"
                        className="flex items-center gap-2 text-[10px] font-black uppercase text-amber-700 hover:underline"
                      >
                        Docs Faturação <ExternalLink className="w-3 h-3" />
                      </a>
                    </div>
                  )}
                </div>
              </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-6">
              <button onClick={handleAnalyze} disabled={!file} className="py-4 bg-blue-600 text-white font-black rounded-2xl hover:bg-blue-700 active:scale-[0.98] transition-all flex items-center justify-center space-x-2 shadow-xl shadow-blue-100 disabled:opacity-50 uppercase tracking-widest text-xs">
                <Upload className="w-4 h-4 mr-2" /> Analisar Processo
              </button>

              <button 
                onClick={() => jsonInputRef.current?.click()} 
                className="py-4 bg-white border border-slate-200 text-slate-700 font-black rounded-2xl hover:bg-slate-50 active:scale-[0.98] transition-all flex items-center justify-center space-x-2 uppercase tracking-widest text-xs"
              >
                <FolderOpen className="w-4 h-4 mr-2" /> Recuperar Projeto
              </button>
              <input type="file" ref={jsonInputRef} className="hidden" accept=".json" onChange={handleLoadProject} />
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (isProcessing) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 space-y-8">
        <div className="relative">
          <div className="w-20 h-20 border-8 border-blue-50 border-t-blue-600 rounded-full animate-spin"></div>
          <Gavel className="absolute inset-0 m-auto w-8 h-8 text-blue-600" />
        </div>
        <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tight">
          {processingStep === 'extracting' ? 'Extraindo Dados' : 'Analisando Estrutura'}
        </h2>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <header className="sticky top-0 z-30 bg-white border-b px-6 py-3 flex items-center justify-between shadow-sm">
        <div className="flex items-center space-x-4">
          <Gavel className="w-6 h-6 text-blue-600" />
          <div>
            <h1 className="text-xs font-black text-slate-900 uppercase tracking-widest leading-none mb-1">Citius Pro</h1>
            <p className="text-[10px] text-slate-400 font-bold leading-none">{analysis?.numero_processo}</p>
          </div>
        </div>

        <div className="flex-1 max-w-xl mx-8 relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
          <input
            type="text"
            placeholder="Pesquisar referências, partes ou texto..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border-transparent focus:bg-white focus:border-blue-500 rounded-xl text-xs transition-all border font-medium"
          />
        </div>

        <div className="flex items-center space-x-2">
          <button 
            onClick={handleSaveProject}
            className="flex items-center space-x-2 px-4 py-2 text-[10px] font-black uppercase bg-blue-50 text-blue-600 border border-blue-100 rounded-xl hover:bg-blue-100 transition-colors"
            title="Guardar análise atual num ficheiro JSON"
          >
            <Download className="w-3.5 h-3.5" />
            <span className="hidden md:inline">Guardar Projeto</span>
          </button>

          <div className="w-px h-6 bg-slate-200 mx-2" />

          <button onClick={() => { setAnalysis(null); setFile(null); setRawText(''); }} className="px-4 py-2 text-[10px] font-black uppercase bg-white border border-slate-200 rounded-xl hover:bg-slate-50 transition-colors">
            Novo Processo
          </button>
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden">
        <aside className="w-72 bg-white border-r hidden lg:flex flex-col p-6 space-y-8 overflow-y-auto">
          <div>
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center">
              <ListFilter className="w-3 h-3 mr-2 text-blue-600" /> Filtrar Tipo
            </h3>
            <div className="space-y-1">
              <button onClick={() => setActiveFilter('all')} className={`w-full text-left px-3 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${activeFilter === 'all' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>
                Todos
              </button>
              {docTypes.map(type => (
                <button key={type} onClick={() => setActiveFilter(type)} className={`w-full text-left px-3 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${activeFilter === type ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>
                  {type}
                </button>
              ))}
            </div>
          </div>

          <div>
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center">
              <SortAsc className="w-3 h-3 mr-2 text-blue-600" /> Ordenação
            </h3>
            <div className="bg-slate-50 p-1.5 rounded-2xl border flex flex-col space-y-1">
              <button onClick={() => setSortOrder('chronological')} className={`flex items-center space-x-3 px-3 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${sortOrder === 'chronological' ? 'bg-white shadow-sm border text-blue-600' : 'text-slate-400'}`}>
                <Clock className="w-3.5 h-3.5" /> <span>Índice / Página</span>
              </button>
              <button onClick={() => setSortOrder('alphabetical')} className={`flex items-center space-x-3 px-3 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${sortOrder === 'alphabetical' ? 'bg-white shadow-sm border text-blue-600' : 'text-slate-400'}`}>
                <SortAsc className="w-3.5 h-3.5" /> <span>Alfabética</span>
              </button>
            </div>
          </div>
        </aside>

        <main className="flex-1 overflow-y-auto p-10 bg-slate-50">
          <div className="max-w-5xl mx-auto">
            <div className="mb-10 flex flex-col md:flex-row md:items-end justify-between gap-6">
              <div>
                <h2 className="text-2xl font-black text-slate-900 tracking-tight">Painel de Trabalho</h2>
                <p className="text-slate-500 text-sm font-medium">Análise estruturada e correlação de provas.</p>
              </div>

              <div className="flex bg-white p-1 rounded-2xl border border-slate-200 shadow-sm">
                <button 
                  onClick={() => setActiveTab('timeline')}
                  className={`flex items-center space-x-2 px-6 py-2.5 rounded-xl text-xs font-black uppercase transition-all ${
                    activeTab === 'timeline' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-50'
                  }`}
                >
                  <LayoutGrid className="w-4 h-4" />
                  <span>Timeline</span>
                </button>
                <button 
                  onClick={() => setActiveTab('facts')}
                  className={`flex items-center space-x-2 px-6 py-2.5 rounded-xl text-xs font-black uppercase transition-all ${
                    activeTab === 'facts' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-50'
                  }`}
                >
                  <Zap className="w-4 h-4" />
                  <span>Análise de Factos</span>
                </button>
              </div>
            </div>

            {activeTab === 'timeline' ? (
              groupedDocs.length > 0 ? (
                <div className="space-y-2">
                  {groupedDocs.map(group => (
                    <DocumentGroup 
                      key={group.refAto} 
                      refAto={group.refAto} 
                      documents={group.docs} 
                      onDocumentClick={setSelectedDoc}
                    />
                  ))}
                </div>
              ) : (
                <div className="py-24 text-center bg-white rounded-3xl border-2 border-dashed border-slate-100">
                  <FileText className="w-12 h-12 text-slate-200 mx-auto mb-4" />
                  <h3 className="text-slate-900 font-black uppercase text-xs tracking-widest">Nenhum resultado</h3>
                </div>
              )
            ) : (
              <FactAnalysisView documents={analysis.documentos} file={file} rawText={rawText} />
            )}
          </div>
        </main>
      </div>

      {selectedDoc && (
        <DocumentDetail 
          doc={selectedDoc} 
          file={file}
          onClose={() => setSelectedDoc(null)} 
          siblings={incidentSiblings}
          onSelectSibling={setSelectedDoc}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { DocumentMetadata, DocumentType, ArticuladoAnalysis, FactMapping } from '../types';
import { analyzeArticuladoFacts, sliceTextByPages } from '../services/geminiService';
import { FileText, Play, Table as TableIcon, CheckCircle2, Search, ExternalLink, Loader2, X, Info, AlertCircle, Layers, Key } from 'lucide-react';
import { TYPE_COLORS } from '../constants';

interface FactAnalysisViewProps {
  documents: DocumentMetadata[];
  file: File | null;
  rawText: string;
}

export const FactAnalysisView: React.FC<FactAnalysisViewProps> = ({ documents, file, rawText }) => {
  const [selectedDocs, setSelectedDocs] = useState<string[]>([]);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [results, setResults] = useState<ArticuladoAnalysis[]>([]);
  const [modalContent, setModalContent] = useState<FactMapping | null>(null);
  const [filterQuery, setFilterQuery] = useState('');
  const [quotaError, setQuotaError] = useState(false);

  const filteredSelectionList = useMemo(() => {
    return documents.filter(doc => {
      const query = filterQuery.toLowerCase();
      return doc.titulo_resumido.toLowerCase().includes(query) || 
             doc.tipo_documento_principal.toLowerCase().includes(query) ||
             doc.ref_documento.includes(filterQuery);
    });
  }, [documents, filterQuery]);

  const toggleSelection = (id: string) => {
    setSelectedDocs(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const handleProcess = async () => {
    if (selectedDocs.length === 0) return;
    setIsAnalyzing(true);
    setResults([]); 
    setQuotaError(false);

    try {
      const allMetadataString = documents
        .sort((a, b) => a.pagina_inicial - b.pagina_inicial)
        .map((d, index) => {
          return `[Ref Doc: ${d.ref_documento}] Titulo: ${d.titulo_resumido} | Sugestão de referência: Doc ${index + 1} | Tipo: ${d.tipo_documento_principal}`;
        }).join('\n');

      const newResults: ArticuladoAnalysis[] = [];

      for (const id of selectedDocs) {
        const doc = documents.find(d => d.id_documento === id);
        if (doc) {
          const literalText = sliceTextByPages(rawText, doc.pagina_inicial, doc.pagina_final);

          if (!literalText || literalText.length < 100) {
             console.warn("Texto extraído muito curto para o doc:", doc.id_documento);
          }

          const analysis = await analyzeArticuladoFacts(literalText, allMetadataString);

          if (analysis && analysis.mappings && analysis.mappings.length > 0) {
            newResults.push({
              id_documento: doc.id_documento,
              titulo: doc.titulo_resumido,
              mappings: analysis.mappings
            });
          } else {
            newResults.push({
              id_documento: doc.id_documento,
              titulo: doc.titulo_resumido,
              mappings: []
            });
          }
        }
      }
      setResults(newResults);
    } catch (error: any) {
      console.error(error);
      const isQuota = error?.message?.includes('429') || error?.status === 429;
      if (isQuota) {
        setQuotaError(true);
      } else {
        alert("Erro na análise. Verifique a ligação à API.");
      }
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleOpenKeySelection = async () => {
    try {
      await window.aistudio.openSelectKey();
      setQuotaError(false);
    } catch (err) {
      console.error("Failed to open key selection", err);
    }
  };

  const openPdfByRef = (refDoc: string) => {
    const doc = documents.find(d => d.ref_documento === refDoc);
    if (doc && file) {
      const fileUrl = URL.createObjectURL(file);
      window.open(`${fileUrl}#page=${doc.pagina_inicial}`, '_blank');
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
          <div>
            <h3 className="text-lg font-black text-slate-900 flex items-center">
              <Layers className="w-5 h-5 mr-2 text-blue-600" /> Seletor de Articulados
            </h3>
            <p className="text-xs text-slate-500 font-bold uppercase tracking-wider mt-1">
              Selecione as peças (PI, Contestação) para gerar o mapa de prova.
            </p>
          </div>

          <div className="relative w-full md:w-72">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
            <input 
              type="text"
              placeholder="Pesquisar peças..."
              value={filterQuery}
              onChange={(e) => setFilterQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border-transparent focus:bg-white focus:border-blue-500 rounded-xl text-xs font-bold transition-all border shadow-inner"
            />
          </div>
        </div>

        <div className="max-h-[400px] overflow-y-auto border-2 border-slate-50 rounded-2xl bg-slate-50/30 p-2 mb-8 space-y-1">
          {filteredSelectionList.map(doc => {
             const colorClass = TYPE_COLORS[doc.tipo_documento_principal] || 'bg-gray-100 text-gray-800 border-gray-200';
             const isSelected = selectedDocs.includes(doc.id_documento);
             return (
              <div 
                key={doc.id_documento}
                onClick={() => toggleSelection(doc.id_documento)}
                className={`flex items-center space-x-4 p-3 rounded-xl border transition-all cursor-pointer ${
                  isSelected ? 'border-blue-500 bg-blue-50 shadow-sm' : 'border-slate-100 bg-white hover:border-blue-200'
                }`}
              >
                <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center transition-all ${
                  isSelected ? 'bg-blue-600 border-blue-600 scale-110 shadow-md' : 'bg-white border-slate-200'
                }`}>
                  {isSelected && <CheckCircle2 className="w-3.5 h-3.5 text-white" />}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center space-x-2 mb-0.5">
                    <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase border tracking-widest ${colorClass}`}>
                      {doc.tipo_documento_principal}
                    </span>
                    <span className="text-[9px] font-black text-slate-400">Ref: {doc.ref_documento}</span>
                  </div>
                  <h4 className="text-[12px] font-black text-slate-800 truncate">{doc.titulo_resumido}</h4>
                </div>
                <div className="text-[10px] font-black text-slate-400 bg-slate-100 px-2 py-1 rounded">Pág. {doc.pagina_inicial}</div>
              </div>
             );
          })}
        </div>

        {quotaError && (
          <div className="mb-6 p-4 bg-amber-50 border border-amber-200 rounded-2xl flex items-start gap-3 text-amber-800">
            <AlertCircle className="w-5 h-5 shrink-0 mt-0.5" />
            <div className="flex-1">
              <p className="text-xs font-bold leading-relaxed mb-3">
                Limite de utilização da IA atingido. Para realizar análises detalhadas com o Gemini Pro, configure a sua própria chave da API num projeto pago.
              </p>
              <button 
                onClick={handleOpenKeySelection}
                className="flex items-center gap-2 bg-amber-600 text-white px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-wider hover:bg-amber-700 transition-colors shadow-sm"
              >
                <Key className="w-4 h-4" /> Configurar Chave Pessoal
              </button>
            </div>
          </div>
        )}

        <button 
          onClick={handleProcess}
          disabled={isAnalyzing || selectedDocs.length === 0}
          className="w-full py-5 bg-blue-600 text-white font-black rounded-2xl flex items-center justify-center space-x-3 hover:bg-blue-700 transition-all shadow-xl shadow-blue-100 disabled:opacity-50 uppercase tracking-widest text-xs"
        >
          {isAnalyzing ? (
            <>
              <Loader2 className="w-5 h-5 animate-spin" />
              <span>Analizando Texto (Gemini Pro)...</span>
            </>
          ) : (
            <>
              <Play className="w-4 h-4" />
              <span>Gerar Mapas de Prova ({selectedDocs.length})</span>
            </>
          )}
        </button>
      </div>

      <div className="space-y-12">
        {results.map(res => (
          <div key={res.id_documento} className="bg-white rounded-3xl border border-slate-200 overflow-hidden shadow-sm animate-in slide-in-from-bottom-6 duration-500">
            <div className="bg-slate-900 px-8 py-5 flex items-center justify-between">
              <div className="flex items-center space-x-4">
                <div className="p-2 bg-blue-600 rounded-lg">
                  <TableIcon className="w-4 h-4 text-white" />
                </div>
                <h4 className="text-white font-black text-sm uppercase tracking-wider">
                  Mapa de Prova: {res.titulo}
                </h4>
              </div>
              <button onClick={() => setResults(prev => prev.filter(r => r.id_documento !== res.id_documento))} className="text-slate-400 hover:text-white p-2">
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50/80 border-b border-slate-200">
                    <th className="px-8 py-5 text-[10px] font-black uppercase text-slate-400 tracking-widest w-24 text-center border-r">Artigo</th>
                    <th className="px-8 py-5 text-[10px] font-black uppercase text-slate-400 tracking-widest">Factos e Provas Relacionadas</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {res.mappings.length > 0 ? res.mappings.map((m, i) => (
                    <tr key={i} className="hover:bg-slate-50/30 transition-colors group">
                      <td className="px-8 py-8 align-top text-center border-r">
                        <button 
                          onClick={() => setModalContent(m)}
                          className="w-12 h-12 rounded-2xl bg-blue-50 text-blue-600 font-black hover:bg-blue-600 hover:text-white transition-all border border-blue-100 shadow-sm flex items-center justify-center mx-auto text-sm group-hover:scale-110"
                        >
                          {m.artigo}
                        </button>
                      </td>
                      <td className="px-8 py-8">
                        <div className="mb-4">
                          <p className="text-[13px] text-slate-700 font-medium leading-relaxed mb-6 bg-slate-50/50 p-4 rounded-xl border border-slate-100">
                            {m.texto_artigo}
                          </p>
                          <div className="flex flex-wrap gap-2">
                            {m.documentos_refs && m.documentos_refs.length > 0 ? m.documentos_refs.map(ref => {
                              const found = documents.find(d => d.ref_documento === ref);
                              return (
                                <button 
                                  key={ref}
                                  onClick={() => openPdfByRef(ref)}
                                  className="inline-flex items-center px-4 py-2 bg-white border border-slate-200 rounded-xl text-[10px] font-black text-slate-700 hover:border-blue-500 hover:text-blue-600 transition-all shadow-sm hover:shadow-md"
                                >
                                  <ExternalLink className="w-3 h-3 mr-2 text-blue-500" />
                                  {found ? found.titulo_resumido : `Peça Ref. ${ref}`}
                                </button>
                              );
                            }) : (
                              <div className="flex items-center space-x-2 text-[10px] font-black text-slate-400 uppercase bg-slate-100/50 px-3 py-1.5 rounded-lg border border-dashed">
                                <Info className="w-3 h-3" />
                                <span>Sem referência documental detetada</span>
                              </div>
                            )}
                          </div>
                        </div>
                      </td>
                    </tr>
                  )) : (
                    <tr>
                      <td colSpan={2} className="px-8 py-20 text-center">
                        <AlertCircle className="w-12 h-12 text-amber-400 mx-auto mb-4 opacity-50" />
                        <h5 className="text-slate-900 font-black uppercase text-xs tracking-widest mb-1">Padrões não detetados</h5>
                        <p className="text-[11px] font-bold text-slate-400 uppercase tracking-tight">O Gemini não conseguiu isolar artigos numerados neste bloco de texto.</p>
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        ))}
      </div>

      {modalContent && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-slate-900/80 backdrop-blur-md p-6 animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-3xl rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300 border border-white/20">
            <div className="px-10 py-8 border-b flex justify-between items-center bg-slate-50/50">
              <div className="flex items-center space-x-5">
                <div className="bg-blue-600 text-white w-14 h-14 rounded-[1.25rem] flex items-center justify-center font-black text-xl shadow-xl shadow-blue-200">
                  {modalContent.artigo}
                </div>
                <div>
                  <h3 className="font-black text-slate-900 uppercase text-xs tracking-[0.2em]">Conteúdo do Artigo</h3>
                </div>
              </div>
              <button onClick={() => setModalContent(null)} className="p-3 hover:bg-slate-200 rounded-full text-slate-400 transition-all">
                <X className="w-6 h-6" />
              </button>
            </div>
            <div className="p-12 max-h-[60vh] overflow-y-auto">
              <p className="text-slate-700 leading-relaxed text-lg font-medium whitespace-pre-wrap">
                {modalContent.texto_artigo}
              </p>
            </div>
            <div className="px-10 py-6 bg-slate-50 border-t text-right">
              <button onClick={() => setModalContent(null)} className="px-8 py-3 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-800 transition-all shadow-lg">
                Fechar Visualização
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useRef } from 'react';
import { DocumentMetadata, ProcessAnalysis, SortOrder } from './types';
import { analyzeProcessText } from './services/geminiService';
import { extractTextFromPdf } from './services/pdfService';
import { DocumentGroup } from './components/DocumentGroup';
import { DocumentDetail } from './components/DocumentDetail';
import { FactAnalysisView } from './components/FactAnalysisView';
import { 
  Search, 
  Upload, 
  Gavel, 
  FileText, 
  FileUp,
  Clock,
  SortAsc,
  ListFilter,
  Download,
  FolderOpen,
  LayoutGrid,
  Zap,
  Key,
  AlertTriangle,
  ExternalLink
} from 'lucide-react';

// Removed redundant and conflicting declare global for aistudio as it's provided by the environment

const App: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [rawText, setRawText] = useState<string>(''); 
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStep, setProcessingStep] = useState<'extracting' | 'analyzing' | null>(null);
  const [analysis, setAnalysis] = useState<ProcessAnalysis | null>(null);
  const [selectedDoc, setSelectedDoc] = useState<DocumentMetadata | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [activeFilter, setActiveFilter] = useState<string>('all');
  const [sortOrder, setSortOrder] = useState<SortOrder>('chronological');
  const [error, setError] = useState<{ message: string; isQuota?: boolean } | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [activeTab, setActiveTab] = useState<'timeline' | 'facts'>('timeline');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const jsonInputRef = useRef<HTMLInputElement>(null);

  const handleOpenKeySelection = async () => {
    try {
      // @ts-ignore - aistudio is expected to be provided by the environment
      await window.aistudio.openSelectKey();
      setError(null);
    } catch (err) {
      console.error("Failed to open key selection", err);
    }
  };

  const validateAndSetFile = (selectedFile: File) => {
    if (selectedFile && selectedFile.type === 'application/pdf') {
      setFile(selectedFile);
      setError(null);
    } else {
      setError({ message: 'Por favor, selecione apenas ficheiros PDF para análise.' });
    }
  };

  // Implement missing drag and drop handlers
  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(true);
  };

  const handleDragEnter = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);

    const droppedFile = e.dataTransfer.files?.[0];
    if (droppedFile) {
      validateAndSetFile(droppedFile);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile) validateAndSetFile(selectedFile);
  };

  const handleAnalyze = async () => {
    if (!file) return;
    setIsProcessing(true);
    setError(null);
    try {
      setProcessingStep('extracting');
      const extractedText = await extractTextFromPdf(file);
      setRawText(extractedText);
      setProcessingStep('analyzing');
      const result = await analyzeProcessText(extractedText);
      setAnalysis(result);
    } catch (err: any) {
      console.error(err);
      const isQuota = err?.message?.includes('429') || err?.status === 429;
      const isNotFound = err?.message?.includes('Requested entity was not found');

      setError({ 
        message: isQuota 
          ? 'Limite de cota excedido. Por favor, utilize a sua própria chave da API para continuar.' 
          : isNotFound 
            ? 'Projeto ou chave não encontrada. Por favor, selecione novamente a sua chave da API.'
            : 'Erro ao processar o ficheiro. Certifique-se que o PDF não é protegido.',
        isQuota: isQuota || isNotFound
      });
    } finally {
      setIsProcessing(false);
      setProcessingStep(null);
    }
  };

  const handleSaveProject = () => {
    if (!analysis) return;
    const projectData = { ...analysis, _rawText: rawText };
    const blob = new Blob([JSON.stringify(projectData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Citius_Project_${analysis.numero_processo.replace(/\//g, '_') || 'Export'}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleLoadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (!selectedFile) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json && json.documentos) {
          setAnalysis(json);
          if (json._rawText) setRawText(json._rawText);
          setFile(null);
          setError(null);
        } else {
          setError({ message: 'O ficheiro JSON selecionado não é um projeto Citius Pro válido.' });
        }
      } catch (err) {
        setError({ message: 'Erro ao ler o ficheiro JSON.' });
      }
    };
    reader.readAsText(selectedFile);
    e.target.value = '';
  };

  const groupedDocs = useMemo(() => {
    if (!analysis) return [];
    const query = searchQuery.toLowerCase();

    let baseDocs = analysis.documentos.filter(doc => {
      const titulo = (doc.titulo_resumido || '').toLowerCase();
      const sumario = (doc.sumario || '').toLowerCase();
      const apresentante = (doc.parte_apresentante || '').toLowerCase();
      const refAto = (doc.ref_ato || '');
      const refDoc = (doc.ref_documento || '');

      const matchesSearch = 
        titulo.includes(query) ||
        sumario.includes(query) ||
        apresentante.includes(query) ||
        refAto.includes(searchQuery) ||
        refDoc.includes(searchQuery);

      const matchesFilter = activeFilter === 'all' || doc.tipo_documento_principal === activeFilter;
      return matchesSearch && matchesFilter;
    });

    if (sortOrder === 'alphabetical') {
      baseDocs.sort((a, b) => (a.titulo_resumido || '').localeCompare(b.titulo_resumido || ''));
    } else {
      baseDocs.sort((a, b) => (a.pagina_inicial || 0) - (b.pagina_inicial || 0));
    }

    const groups: { refAto: string, docs: DocumentMetadata[] }[] = [];
    const seenRefs = new Set<string>();

    baseDocs.forEach(doc => {
      const ref = doc.ref_ato || 'Sem Ref';
      if (!seenRefs.has(ref)) {
        seenRefs.add(ref);
        groups.push({
          refAto: ref,
          docs: baseDocs.filter(d => d.ref_ato === ref)
        });
      }
    });

    return groups;
  }, [analysis, searchQuery, activeFilter, sortOrder]);

  const docTypes = useMemo(() => {
    if (!analysis) return [];
    const types = Array.from(new Set(analysis.documentos.map(d => d.tipo_documento_principal).filter(Boolean)));
    return types.sort((a, b) => a.localeCompare(b));
  }, [analysis]);

  const incidentSiblings = useMemo(() => {
    if (!selectedDoc || !analysis) return [];
    return analysis.documentos.filter(d => d.ref_ato === selectedDoc.ref_ato);
  }, [selectedDoc, analysis]);

  if (!analysis && !isProcessing) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 text-slate-900">
        <div className="w-full max-w-2xl space-y-8 animate-in slide-in-from-bottom-4 duration-500">
          <div className="text-center">
            <div className="inline-flex items-center justify-center p-3 bg-blue-600 rounded-2xl shadow-lg mb-4">
              <Gavel className="w-10 h-10 text-white" />
            </div>
            <h1 className="text-4xl font-black tracking-tight">Citius Analytics Pro</h1>
            <p className="mt-3 text-lg text-slate-600 max-w-lg mx-auto leading-relaxed">
              Análise inteligente de processos judiciais exportados.
            </p>
          </div>

          <div className="bg-white p-8 rounded-3xl shadow-2xl border border-slate-200">
            <div 
              onClick={() => fileInputRef.current?.click()}
              onDragOver={handleDragOver}
              onDragEnter={handleDragEnter}
              onDragLeave={handleDragLeave}
              onDrop={handleDrop}
              className={`border-2 border-dashed rounded-2xl p-12 flex flex-col items-center justify-center transition-all cursor-pointer ${
                isDragging ? 'border-blue-600 bg-blue-100 scale-[1.02]' : 
                file ? 'border-blue-400 bg-blue-50' : 'border-slate-300 hover:border-blue-400 hover:bg-slate-50'
              }`}
            >
              <input type="file" ref={fileInputRef} className="hidden" accept=".pdf" onChange={handleFileChange} />
              {file ? (
                <div className="text-center">
                  <FileText className="w-12 h-12 text-blue-600 mb-4 mx-auto" />
                  <h3 className="font-black text-slate-900">{file.name}</h3>
                  <button onClick={(e) => { e.stopPropagation(); setFile(null); }} className="mt-4 text-xs font-bold text-red-500 uppercase tracking-widest hover:text-red-700">
                    Remover ficheiro
                  </button>
                </div>
              ) : (
                <div className="text-center">
                  <FileUp className={`w-12 h-12 mb-4 mx-auto transition-colors ${isDragging ? 'text-blue-600' : 'text-slate-300'}`} />
                  <p className="text-slate-600 font-bold">
                    {isDragging ? 'Solte o ficheiro aqui' : 'Arraste o PDF ou clique para procurar'}
                  </p>
                </div>
              )}
            </div>

            {error && (
              <div className={`mt-4 p-4 rounded-xl border flex items-start gap-3 ${error.isQuota ? 'bg-amber-50 border-amber-200 text-amber-800' : 'bg-red-50 border-red-200 text-red-700'}`}>
                {error.isQuota ? <AlertTriangle className="w-5 h-5 shrink-0 mt-0.5" /> : <AlertTriangle className="w-5 h-5 shrink-0 mt-0.5" />}
                <div className="flex-1">
                  <p className="text-xs font-bold leading-relaxed">{error.message}</p>
                  {error.isQuota && (
                    <div className="mt-3 flex flex-wrap gap-3">
                      <button 
                        onClick={handleOpenKeySelection}
                        className="flex items-center gap-2 bg-amber-600 text-white px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-wider hover:bg-amber-700 transition-colors"
                      >
                        <Key className="w-3.5 h-3.5" /> Configurar Chave Própria
                      </button>
                      <a 
                        href="https://ai.google.dev/gemini-api/docs/billing" 
                        target="_blank" 
                        rel="noreferrer"
                        className="flex items-center gap-2 text-[10px] font-black uppercase text-amber-700 hover:underline"
                      >
                        Docs Faturação <ExternalLink className="w-3 h-3" />
                      </a>
                    </div>
                  )}
                </div>
              </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-6">
              <button onClick={handleAnalyze} disabled={!file} className="py-4 bg-blue-600 text-white font-black rounded-2xl hover:bg-blue-700 active:scale-[0.98] transition-all flex items-center justify-center space-x-2 shadow-xl shadow-blue-100 disabled:opacity-50 uppercase tracking-widest text-xs">
                <Upload className="w-4 h-4 mr-2" /> Analisar Processo
              </button>

              <button 
                onClick={() => jsonInputRef.current?.click()} 
                className="py-4 bg-white border border-slate-200 text-slate-700 font-black rounded-2xl hover:bg-slate-50 active:scale-[0.98] transition-all flex items-center justify-center space-x-2 uppercase tracking-widest text-xs"
              >
                <FolderOpen className="w-4 h-4 mr-2" /> Recuperar Projeto
              </button>
              <input type="file" ref={jsonInputRef} className="hidden" accept=".json" onChange={handleLoadProject} />
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (isProcessing) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 space-y-8">
        <div className="relative">
          <div className="w-20 h-20 border-8 border-blue-50 border-t-blue-600 rounded-full animate-spin"></div>
          <Gavel className="absolute inset-0 m-auto w-8 h-8 text-blue-600" />
        </div>
        <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tight">
          {processingStep === 'extracting' ? 'Extraindo Dados' : 'Analisando Estrutura'}
        </h2>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <header className="sticky top-0 z-30 bg-white border-b px-6 py-3 flex items-center justify-between shadow-sm">
        <div className="flex items-center space-x-4">
          <Gavel className="w-6 h-6 text-blue-600" />
          <div>
            <h1 className="text-xs font-black text-slate-900 uppercase tracking-widest leading-none mb-1">Citius Pro</h1>
            <p className="text-[10px] text-slate-400 font-bold leading-none">{analysis?.numero_processo}</p>
          </div>
        </div>

        <div className="flex-1 max-w-xl mx-8 relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
          <input
            type="text"
            placeholder="Pesquisar referências, partes ou texto..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border-transparent focus:bg-white focus:border-blue-500 rounded-xl text-xs transition-all border font-medium"
          />
        </div>

        <div className="flex items-center space-x-2">
          <button 
            onClick={handleSaveProject}
            className="flex items-center space-x-2 px-4 py-2 text-[10px] font-black uppercase bg-blue-50 text-blue-600 border border-blue-100 rounded-xl hover:bg-blue-100 transition-colors"
            title="Guardar análise atual num ficheiro JSON"
          >
            <Download className="w-3.5 h-3.5" />
            <span className="hidden md:inline">Guardar Projeto</span>
          </button>

          <div className="w-px h-6 bg-slate-200 mx-2" />

          <button onClick={() => { setAnalysis(null); setFile(null); setRawText(''); }} className="px-4 py-2 text-[10px] font-black uppercase bg-white border border-slate-200 rounded-xl hover:bg-slate-50 transition-colors">
            Novo Processo
          </button>
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden">
        <aside className="w-72 bg-white border-r hidden lg:flex flex-col p-6 space-y-8 overflow-y-auto">
          <div>
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center">
              <ListFilter className="w-3 h-3 mr-2 text-blue-600" /> Filtrar Tipo
            </h3>
            <div className="space-y-1">
              <button onClick={() => setActiveFilter('all')} className={`w-full text-left px-3 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${activeFilter === 'all' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>
                Todos
              </button>
              {docTypes.map(type => (
                <button key={type} onClick={() => setActiveFilter(type)} className={`w-full text-left px-3 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${activeFilter === type ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>
                  {type}
                </button>
              ))}
            </div>
          </div>

          <div>
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center">
              <SortAsc className="w-3 h-3 mr-2 text-blue-600" /> Ordenação
            </h3>
            <div className="bg-slate-50 p-1.5 rounded-2xl border flex flex-col space-y-1">
              <button onClick={() => setSortOrder('chronological')} className={`flex items-center space-x-3 px-3 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${sortOrder === 'chronological' ? 'bg-white shadow-sm border text-blue-600' : 'text-slate-400'}`}>
                <Clock className="w-3.5 h-3.5" /> <span>Índice / Página</span>
              </button>
              <button onClick={() => setSortOrder('alphabetical')} className={`flex items-center space-x-3 px-3 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${sortOrder === 'alphabetical' ? 'bg-white shadow-sm border text-blue-600' : 'text-slate-400'}`}>
                <SortAsc className="w-3.5 h-3.5" /> <span>Alfabética</span>
              </button>
            </div>
          </div>
        </aside>

        <main className="flex-1 overflow-y-auto p-10 bg-slate-50">
          <div className="max-w-5xl mx-auto">
            <div className="mb-10 flex flex-col md:flex-row md:items-end justify-between gap-6">
              <div>
                <h2 className="text-2xl font-black text-slate-900 tracking-tight">Painel de Trabalho</h2>
                <p className="text-slate-500 text-sm font-medium">Análise estruturada e correlação de provas.</p>
              </div>

              <div className="flex bg-white p-1 rounded-2xl border border-slate-200 shadow-sm">
                <button 
                  onClick={() => setActiveTab('timeline')}
                  className={`flex items-center space-x-2 px-6 py-2.5 rounded-xl text-xs font-black uppercase transition-all ${
                    activeTab === 'timeline' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-50'
                  }`}
                >
                  <LayoutGrid className="w-4 h-4" />
                  <span>Timeline</span>
                </button>
                <button 
                  onClick={() => setActiveTab('facts')}
                  className={`flex items-center space-x-2 px-6 py-2.5 rounded-xl text-xs font-black uppercase transition-all ${
                    activeTab === 'facts' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-50'
                  }`}
                >
                  <Zap className="w-4 h-4" />
                  <span>Análise de Factos</span>
                </button>
              </div>
            </div>

            {activeTab === 'timeline' ? (
              groupedDocs.length > 0 ? (
                <div className="space-y-2">
                  {groupedDocs.map(group => (
                    <DocumentGroup 
                      key={group.refAto} 
                      refAto={group.refAto} 
                      documents={group.docs} 
