export const AssistantView: React.FC<AssistantViewProps> = ({ 
  documents, 
  file, 
  rawText, 
  chatHistory, 
  setChatHistory,
  onFileLink
}) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Criar uma URL de blob estável para o PDF
  const pdfUrl = useMemo(() => {
    if (!file) return null;
    return URL.createObjectURL(file);
  }, [file]);

  // Limpeza da URL ao desmontar
  useEffect(() => {
    return () => {
      if (pdfUrl) URL.revokeObjectURL(pdfUrl);
    };
  }, [pdfUrl]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [chatHistory, isLoading]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMessage: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      timestamp: Date.now()
    };

    setChatHistory(prev => [...prev, userMessage]);
    setInput('');
    setIsLoading(true);

    try {
      const docsContext = documents.map(d => 
        `Ref Doc: ${d.ref_documento} | Titulo: ${d.titulo_resumido} | Pagina: ${d.pagina_inicial}`
      ).join('\n');

      const result = await askAssistant(input, rawText, docsContext);

      const assistantMessage: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: result.answer,
        citations: result.citations,
        metrics: result.metrics,
        timestamp: Date.now()
      };

      setChatHistory(prev => [...prev, assistantMessage]);
    } catch (error) {
      console.error(error);
      const errorMessage: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: "Lamento, ocorreu um erro ao processar a sua pergunta. Verifique a ligação e tente novamente.",
