  const downloadToWord = (msg?: ChatMessage) => {
    let content = "";
    if (msg) {
      const userContent = chatHistory.find(m => m.timestamp < msg.timestamp && m.role === 'user')?.content;
      content = `PERGUNTA: ${userContent}\n\nRESPOSTA:\n${msg.content}\n\nDocumentos citados:\n${msg.citations?.map(c => `- ${c.titulo} (Ref: ${c.ref_documento}, Pág: ${c.pagina})`).join('\n')}`;
    } else {
      content = chatHistory.map(m => {
