import React, { useEffect, useRef, useState } from 'react';
import * as pdfjsLib from 'pdfjs-dist';

interface PdfPagePreviewProps {
  file: File | null;
  pageNumber: number;
  className?: string;
}

export const PdfPagePreview: React.FC<PdfPagePreviewProps> = ({ file, pageNumber, className }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let isMounted = true;
    if (!file) return;

    const renderPage = async () => {
      try {
        setLoading(true);
        const arrayBuffer = await file.arrayBuffer();
        const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
        const page = await pdf.getPage(pageNumber);

        if (!isMounted || !canvasRef.current) return;

        const viewport = page.getViewport({ scale: 0.8 });
        const canvas = canvasRef.current;
        const context = canvas.getContext('2d');

        if (context) {
          canvas.height = viewport.height;
          canvas.width = viewport.width;

          await page.render({
            canvasContext: context,
            viewport: viewport,
          }).promise;
        }
        setLoading(false);
      } catch (err) {
        console.error("Error rendering PDF preview:", err);
        setLoading(false);
      }
    };

    renderPage();
    return () => { isMounted = false; };
  }, [file, pageNumber]);

  return (
    <div className={`relative overflow-y-auto overflow-x-hidden border border-slate-200 rounded-lg bg-slate-100 ${className}`} style={{ maxHeight: '120px' }}>
      {loading && (
        <div className="absolute inset-0 flex items-center justify-center bg-slate-50/80 z-10">
          <div className="w-4 h-4 border-2 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
        </div>
      )}
      <canvas ref={canvasRef} className="w-full h-auto block" />
    </div>
  );
};

