import React, { useEffect, useRef, useState } from 'react';
import * as pdfjsLib from 'pdfjs-dist';

interface PdfPagePreviewProps {
  file: File | null;
  pageNumber: number;
  className?: string;
  autoHeight?: boolean;
}

export const PdfPagePreview: React.FC<PdfPagePreviewProps> = ({ file, pageNumber, className, autoHeight = false }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let isMounted = true;
    if (!file) return;

    const renderPage = async () => {
      try {
        setLoading(true);
        const arrayBuffer = await file.arrayBuffer();
        const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
        const page = await pdf.getPage(pageNumber);

        if (!isMounted || !canvasRef.current) return;

        // Renderiza com escala maior para permitir scroll legível
        const viewport = page.getViewport({ scale: 1.5 });
        const canvas = canvasRef.current;
        const context = canvas.getContext('2d');

        if (context) {
          canvas.height = viewport.height;
          canvas.width = viewport.width;

          await page.render({
            canvasContext: context,
            viewport: viewport,
          }).promise;
        }
        setLoading(false);
      } catch (err) {
        console.error("Error rendering PDF preview:", err);
        setLoading(false);
      }
    };

    renderPage();
    return () => { isMounted = false; };
  }, [file, pageNumber]);

  return (
    <div className={`relative overflow-y-auto bg-slate-100 rounded-xl border border-slate-200 ${className}`} style={{ height: autoHeight ? 'auto' : '600px' }}>
      {loading && (
        <div className="absolute inset-0 flex items-center justify-center bg-white/80 z-10">
          <div className="flex flex-col items-center gap-3">
            <div className="w-8 h-8 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
            <span className="text-[10px] font-black uppercase text-slate-400">A carregar página {pageNumber}...</span>
          </div>
        </div>
      )}
      <canvas ref={canvasRef} className="mx-auto shadow-2xl my-4" style={{ maxWidth: '100%' }} />
    </div>
  );
};

