import * as pdfjsLib from 'pdfjs-dist';

// Configuração do worker necessária para o pdf.js via ESM
pdfjsLib.GlobalWorkerOptions.workerSrc = `https://esm.sh/pdfjs-dist@${pdfjsLib.version}/build/pdf.worker.min.mjs`;

// Cache para evitar recarregar o PDF múltiplas vezes
let cachedPdf: pdfjsLib.PDFDocumentProxy | null = null;
let cachedFile: File | null = null;

export const getPdfDocument = async (file: File): Promise<pdfjsLib.PDFDocumentProxy> => {
  if (cachedPdf && cachedFile === file) {
    return cachedPdf;
  }

  const arrayBuffer = await file.arrayBuffer();
  cachedPdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
  cachedFile = file;
  return cachedPdf;
};

export const getPageSnapshot = async (file: File, pageNumber: number): Promise<string> => {
  const pdf = await getPdfDocument(file);
  const page = await pdf.getPage(pageNumber);

  const viewport = page.getViewport({ scale: 1.2 });
  const canvas = document.createElement('canvas');
  const context = canvas.getContext('2d');

  if (!context) throw new Error("Could not get canvas context");

  canvas.height = viewport.height;
  canvas.width = viewport.width;

  await page.render({
    canvasContext: context,
    viewport: viewport,
  }).promise;

  return canvas.toDataURL('image/jpeg', 0.7);
};

export const extractTextFromPdf = async (file: File): Promise<string> => {
  const pdf = await getPdfDocument(file);
  let fullText = "";

  for (let i = 1; i <= pdf.numPages; i++) {
    const page = await pdf.getPage(i);
    const textContent = await page.getTextContent();
    const pageText = textContent.items
      .map((item: any) => item.str)
      .join(" ");

    fullText += `\n--- PÁGINA ${i} ---\n${pageText}\n`;
  }

  return fullText;
};

import React, { useState, useMemo, useRef } from 'react';
import { DocumentMetadata, ProcessAnalysis, SortOrder, TokenMetrics, ChatMessage } from './types';
import { analyzeProcessText } from './services/geminiService';
import { extractTextFromPdf, getPageSnapshot } from './services/pdfService';
import { DocumentGroup } from './components/DocumentGroup';
import { DocumentDetail } from './components/DocumentDetail';
import { AssistantView } from './components/AssistantView';
import { 
  Search, 
  Upload, 
  Gavel, 
  FileText, 
  FileUp,
  Clock,
  SortAsc,
  ListFilter,
  Download,
  FolderOpen,
  LayoutGrid,
  Bot,
  Key,
  AlertTriangle,
  ExternalLink,
  Cpu,
  Loader2
} from 'lucide-react';

const App: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [rawText, setRawText] = useState<string>(''); 
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStep, setProcessingStep] = useState<'extracting' | 'analyzing' | 'snapshots' | null>(null);
  const [snapshotProgress, setSnapshotProgress] = useState({ current: 0, total: 0 });
  const [analysis, setAnalysis] = useState<ProcessAnalysis | null>(null);
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [selectedDoc, setSelectedDoc] = useState<DocumentMetadata | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [activeFilter, setActiveFilter] = useState<string>('all');
  const [sortOrder, setSortOrder] = useState<SortOrder>('chronological');
  const [error, setError] = useState<{ message: string; isQuota?: boolean } | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [activeTab, setActiveTab] = useState<'timeline' | 'assistant'>('timeline');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const jsonInputRef = useRef<HTMLInputElement>(null);

  const handleOpenKeySelection = async () => {
    try {
      // @ts-ignore
      await window.aistudio.openSelectKey();
      setError(null);
    } catch (err) {
      console.error("Failed to open key selection", err);
    }
  };

  const validateAndSetFile = (selectedFile: File) => {
    if (selectedFile && selectedFile.type === 'application/pdf') {
      setFile(selectedFile);
      setError(null);
    } else {
      setError({ message: 'Por favor, selecione apenas ficheiros PDF para análise.' });
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(true);
  };

  const handleDragEnter = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);

    const droppedFile = e.dataTransfer.files?.[0];
    if (droppedFile) {
      validateAndSetFile(droppedFile);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile) validateAndSetFile(selectedFile);
  };

  const handleAnalyze = async () => {
    if (!file) return;
    setIsProcessing(true);
    setError(null);
    try {
      setProcessingStep('extracting');
      const extractedText = await extractTextFromPdf(file);
      setRawText(extractedText);

      setProcessingStep('analyzing');
      const result = await analyzeProcessText(extractedText);

      // Geração de Snapshots para velocidade instantânea depois
      setProcessingStep('snapshots');
      setSnapshotProgress({ current: 0, total: result.documentos.length });

      for (let i = 0; i < result.documentos.length; i++) {
        const doc = result.documentos[i];
        try {
          doc.snapshot = await getPageSnapshot(file, doc.pagina_inicial);
        } catch (e) {
          console.warn(`Could not generate snapshot for doc ${doc.id_documento}`);
        }
        setSnapshotProgress(prev => ({ ...prev, current: i + 1 }));
      }

      setAnalysis(result);
      setChatHistory([]); 
    } catch (err: any) {
      console.error(err);
      const isQuota = err?.message?.includes('429') || err?.status === 429;
      const isNotFound = err?.message?.includes('Requested entity was not found');

      setError({ 
        message: isQuota 
          ? 'Limite de cota excedido. Por favor, utilize a sua própria chave da API para continuar.' 
          : isNotFound 
            ? 'Projeto ou chave não encontrada. Por favor, selecione novamente a sua chave da API.'
            : 'Erro ao processar o ficheiro. Certifique-se que o PDF não é protegido.',
        isQuota: isQuota || isNotFound
      });
    } finally {
      setIsProcessing(false);
      setProcessingStep(null);
    }
  };

  const handleSaveProject = () => {
    if (!analysis) return;
    const projectData = { 
      ...analysis, 
      _rawText: rawText,
      chatHistory: chatHistory 
    };
    const blob = new Blob([JSON.stringify(projectData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Citius_Project_${analysis.numero_processo.replace(/\//g, '_') || 'Export'}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleLoadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (!selectedFile) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json && json.documentos) {
          setAnalysis(json);
          if (json._rawText) setRawText(json._rawText);
          if (json.chatHistory) setChatHistory(json.chatHistory);
          setFile(null); 
          setError(null);
        } else {
          setError({ message: 'O ficheiro JSON selecionado não é um projeto Citius Pro válido.' });
        }
      } catch (err) {
        setError({ message: 'Erro ao ler o ficheiro JSON.' });
      }
    };
    reader.readAsText(selectedFile);
    e.target.value = '';
  };

  const groupedDocs = useMemo(() => {
    if (!analysis) return [];
    const query = searchQuery.toLowerCase();

    let baseDocs = analysis.documentos.filter(doc => {
      const titulo = (doc.titulo_resumido || '').toLowerCase();
      const sumario = (doc.sumario || '').toLowerCase();
      const apresentante = (doc.parte_apresentante || '').toLowerCase();
      const refAto = (doc.ref_ato || '');
      const refDoc = (doc.ref_documento || '');

      const matchesSearch = 
        titulo.includes(query) ||
        sumario.includes(query) ||
        apresentante.includes(query) ||
        refAto.includes(searchQuery) ||
        refDoc.includes(searchQuery);

      const matchesFilter = activeFilter === 'all' || doc.tipo_documento_principal === activeFilter;
      return matchesSearch && matchesFilter;
    });

    if (sortOrder === 'alphabetical') {
      baseDocs.sort((a, b) => (a.titulo_resumido || '').localeCompare(b.titulo_resumido || ''));
    } else {
      baseDocs.sort((a, b) => (a.pagina_inicial || 0) - (b.pagina_inicial || 0));
    }

    const groups: { refAto: string, docs: DocumentMetadata[] }[] = [];
    const seenRefs = new Set<string>();

    baseDocs.forEach(doc => {
      const ref = doc.ref_ato || 'Sem Ref';
      if (!seenRefs.has(ref)) {
        seenRefs.add(ref);
        groups.push({
          refAto: ref,
          docs: baseDocs.filter(d => d.ref_ato === ref)
        });
      }
    });

    return groups;
  }, [analysis, searchQuery, activeFilter, sortOrder]);

  const docTypes = useMemo(() => {
    if (!analysis) return [];
    const types = Array.from(new Set(analysis.documentos.map(d => d.tipo_documento_principal).filter(Boolean)));
    return types.sort((a, b) => a.localeCompare(b));
  }, [analysis]);

  const incidentSiblings = useMemo(() => {
    if (!selectedDoc || !analysis) return [];
    return analysis.documentos.filter(d => d.ref_ato === selectedDoc.ref_ato);
  }, [selectedDoc, analysis]);

  if (!analysis && !isProcessing) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 text-slate-900">
        <div className="w-full max-w-2xl space-y-8 animate-in slide-in-from-bottom-4 duration-500">
          <div className="text-center">
            <div className="inline-flex items-center justify-center p-3 bg-blue-600 rounded-2xl shadow-lg mb-4">
              <Gavel className="w-10 h-10 text-white" />
            </div>
            <h1 className="text-4xl font-black tracking-tight">Citius Analytics Pro</h1>
            <p className="mt-3 text-lg text-slate-600 max-w-lg mx-auto leading-relaxed">
              Análise inteligente de processos judiciais exportados.
            </p>
          </div>

          <div className="bg-white p-8 rounded-3xl shadow-2xl border border-slate-200">
            <div 
              onClick={() => fileInputRef.current?.click()}
              onDragOver={handleDragOver}
              onDragEnter={handleDragEnter}
              onDragLeave={handleDragLeave}
              onDrop={handleDrop}
              className={`border-2 border-dashed rounded-2xl p-12 flex flex-col items-center justify-center transition-all cursor-pointer ${
                isDragging ? 'border-blue-600 bg-blue-100 scale-[1.02]' : 
                file ? 'border-blue-400 bg-blue-50' : 'border-slate-300 hover:border-blue-400 hover:bg-slate-50'
              }`}
            >
              <input type="file" ref={fileInputRef} className="hidden" accept=".pdf" onChange={handleFileChange} />
              {file ? (
                <div className="text-center">
                  <FileText className="w-12 h-12 text-blue-600 mb-4 mx-auto" />
                  <h3 className="font-black text-slate-900">{file.name}</h3>
                  <button onClick={(e) => { e.stopPropagation(); setFile(null); }} className="mt-4 text-xs font-bold text-red-500 uppercase tracking-widest hover:text-red-700">
                    Remover ficheiro
                  </button>
                </div>
              ) : (
                <div className="text-center">
                  <FileUp className={`w-12 h-12 mb-4 mx-auto transition-colors ${isDragging ? 'text-blue-600' : 'text-slate-300'}`} />
                  <p className="text-slate-600 font-bold">
                    {isDragging ? 'Solte o ficheiro aqui' : 'Arraste o PDF ou clique para procurar'}
                  </p>
                </div>
              )}
            </div>

            {error && (
              <div className={`mt-4 p-4 rounded-xl border flex items-start gap-3 ${error.isQuota ? 'bg-amber-50 border-amber-200 text-amber-800' : 'bg-red-50 border-red-200 text-red-700'}`}>
                <AlertTriangle className="w-5 h-5 shrink-0 mt-0.5" />
                <div className="flex-1">
                  <p className="text-xs font-bold leading-relaxed">{error.message}</p>
                  {error.isQuota && (
                    <div className="mt-3 flex flex-wrap gap-3">
                      <button 
                        onClick={handleOpenKeySelection}
                        className="flex items-center gap-2 bg-amber-600 text-white px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-wider hover:bg-amber-700 transition-colors"
                      >
                        <Key className="w-3.5 h-3.5" /> Configurar Chave Própria
                      </button>
                      <a 
                        href="https://ai.google.dev/gemini-api/docs/billing" 
                        target="_blank" 
                        rel="noreferrer"
                        className="flex items-center gap-2 text-[10px] font-black uppercase text-amber-700 hover:underline"
                      >
                        Docs Faturação <ExternalLink className="w-3 h-3" />
                      </a>
                    </div>
                  )}
                </div>
              </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-6">
              <button onClick={handleAnalyze} disabled={!file} className="py-4 bg-blue-600 text-white font-black rounded-2xl hover:bg-blue-700 active:scale-[0.98] transition-all flex items-center justify-center space-x-2 shadow-xl shadow-blue-100 disabled:opacity-50 uppercase tracking-widest text-xs">
                <Upload className="w-4 h-4 mr-2" /> Analisar Processo
              </button>

              <button 
                onClick={() => jsonInputRef.current?.click()} 
                className="py-4 bg-white border border-slate-200 text-slate-700 font-black rounded-2xl hover:bg-slate-50 active:scale-[0.98] transition-all flex items-center justify-center space-x-2 uppercase tracking-widest text-xs"
              >
                <FolderOpen className="w-4 h-4 mr-2" /> Recuperar Projeto
              </button>
              <input type="file" ref={jsonInputRef} className="hidden" accept=".json" onChange={handleLoadProject} />
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (isProcessing) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 space-y-8">
        <div className="relative">
          <div className="w-20 h-20 border-8 border-blue-50 border-t-blue-600 rounded-full animate-spin"></div>
          <Gavel className="absolute inset-0 m-auto w-8 h-8 text-blue-600" />
        </div>
        <div className="text-center max-w-sm">
          <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tight mb-2">
            {processingStep === 'extracting' ? 'Extraindo Dados' : 
             processingStep === 'analyzing' ? 'Analisando Estrutura' : 'Gerando Previews Instantâneos'}
          </h2>
          {processingStep === 'snapshots' && (
            <div className="w-full bg-slate-200 h-2 rounded-full mt-4 overflow-hidden">
              <div 
                className="bg-blue-600 h-full transition-all duration-300" 
                style={{ width: `${(snapshotProgress.current / snapshotProgress.total) * 100}%` }}
              />
            </div>
          )}
          <p className="text-[10px] text-slate-400 font-bold uppercase tracking-[0.2em] mt-3 animate-pulse">
            {processingStep === 'snapshots' 
              ? `A processar ${snapshotProgress.current} de ${snapshotProgress.total} peças...` 
              : 'Isto pode demorar alguns segundos...'}
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <header className="sticky top-0 z-30 bg-white border-b px-6 py-3 flex items-center justify-between shadow-sm">
        <div className="flex items-center space-x-4">
          <Gavel className="w-6 h-6 text-blue-600" />
          <div>
            <h1 className="text-xs font-black text-slate-900 uppercase tracking-widest leading-none mb-1">Citius Pro</h1>
            <p className="text-[10px] text-slate-400 font-bold leading-none">{analysis?.numero_processo || 'Processo Indetificado'}</p>
          </div>
        </div>

        <div className="flex-1 max-w-xl mx-8 relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
          <input
            type="text"
            placeholder="Pesquisar referências, partes ou texto..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border-transparent focus:bg-white focus:border-blue-500 rounded-xl text-xs transition-all border font-medium"
