  const [snapshotProgress, setSnapshotProgress] = useState({ current: 0, total: 0 });
  const [analysis, setAnalysis] = useState<ProcessAnalysis | null>(null);
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [selectedDoc, setSelectedDoc] = useState<DocumentMetadata | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [activeFilter, setActiveFilter] = useState<string>('all');
  const [sortOrder, setSortOrder] = useState<SortOrder>('chronological');
  const [error, setError] = useState<{ message: string; isQuota?: boolean } | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [activeTab, setActiveTab] = useState<'timeline' | 'assistant'>('timeline');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const jsonInputRef = useRef<HTMLInputElement>(null);
  const relinkPdfInputRef = useRef<HTMLInputElement>(null);

  const handleOpenKeySelection = async () => {
    try {
      // @ts-ignore
      await window.aistudio.openSelectKey();
      setError(null);
    } catch (err) {
      console.error("Failed to open key selection", err);
    }
  };

  const validateAndSetFile = (selectedFile: File) => {
    if (selectedFile && selectedFile.type === 'application/pdf') {
      setFile(selectedFile);
      setError(null);
    } else {
      setError({ message: 'Por favor, selecione apenas ficheiros PDF para análise.' });
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(true);
  };

  const handleDragEnter = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);

    const droppedFile = e.dataTransfer.files?.[0];
    if (droppedFile) {
      validateAndSetFile(droppedFile);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile) validateAndSetFile(selectedFile);
  };

  const handleAnalyze = async () => {
    if (!file) return;
    setIsProcessing(true);
    setError(null);
    try {
      setProcessingStep('extracting');
      const extractedText = await extractTextFromPdf(file);
      setRawText(extractedText);

      setProcessingStep('analyzing');
      const result = await analyzeProcessText(extractedText);

      setProcessingStep('snapshots');
      setSnapshotProgress({ current: 0, total: result.documentos.length });

      for (let i = 0; i < result.documentos.length; i++) {
        const doc = result.documentos[i];
        // Garantir propagação do número do processo
        doc.numero_processo = result.numero_processo || analysis?.numero_processo || '';
        try {
          doc.snapshot = await getPageSnapshot(file, doc.pagina_inicial);
        } catch (e) {
          console.warn(`Could not generate snapshot for doc ${doc.id_documento}`);
        }
        setSnapshotProgress(prev => ({ ...prev, current: i + 1 }));
      }

      setAnalysis(result);
      setChatHistory([]); 
    } catch (err: any) {
      console.error(err);
      const isQuota = err?.message?.includes('429') || err?.status === 429;
      const isNotFound = err?.message?.includes('Requested entity was not found');

      setError({ 
        message: isQuota 
          ? 'Limite de cota excedido. Por favor, utilize a sua própria chave da API para continuar.' 
          : isNotFound 
            ? 'Projeto ou chave não encontrada. Por favor, selecione novamente a sua chave da API.'
            : 'Erro ao processar o ficheiro. Certifique-se que o PDF não é protegido.',
        isQuota: isQuota || isNotFound
      });
    } finally {
      setIsProcessing(false);
      setProcessingStep(null);
    }
  };

  const handleSaveProject = () => {
    if (!analysis) return;
    const projectData = { 
      ...analysis, 
      _rawText: rawText,
      chatHistory: chatHistory 
    };
    const blob = new Blob([JSON.stringify(projectData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Citius_Project_${analysis.numero_processo.replace(/\//g, '_') || 'Export'}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleLoadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (!selectedFile) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json && json.documentos) {
          setAnalysis(json);
          if (json._rawText) setRawText(json._rawText);
          if (json.chatHistory) setChatHistory(json.chatHistory);
          setFile(null); 
          setError(null);
        } else {
          setError({ message: 'O ficheiro JSON selecionado não é um projeto Citius Pro válido.' });
        }
      } catch (err) {
        setError({ message: 'Erro ao ler o ficheiro JSON.' });
      }
    };
    reader.readAsText(selectedFile);
    e.target.value = '';
  };

  const groupedDocs = useMemo(() => {
    if (!analysis) return [];
    const query = searchQuery.toLowerCase();

    let baseDocs = analysis.documentos.filter(doc => {
      const titulo = (doc.titulo_resumido || '').toLowerCase();
      const sumario = (doc.sumario || '').toLowerCase();
      const apresentante = (doc.parte_apresentante || '').toLowerCase();
      const refAto = (doc.ref_ato || '');
      const refDoc = (doc.ref_documento || '');

      const matchesSearch = 
        titulo.includes(query) ||
        sumario.includes(query) ||
        apresentante.includes(query) ||
        refAto.includes(searchQuery) ||
        refDoc.includes(searchQuery);

      const matchesFilter = activeFilter === 'all' || doc.tipo_documento_principal === activeFilter;
      return matchesSearch && matchesFilter;
    });

    if (sortOrder === 'alphabetical') {
      baseDocs.sort((a, b) => (a.titulo_resumido || '').localeCompare(b.titulo_resumido || ''));
    } else {
      baseDocs.sort((a, b) => (a.pagina_inicial || 0) - (b.pagina_inicial || 0));
    }

    const groups: { refAto: string, docs: DocumentMetadata[] }[] = [];
    const seenRefs = new Set<string>();

    baseDocs.forEach(doc => {
      const ref = doc.ref_ato || 'Sem Ref';
      if (!seenRefs.has(ref)) {
        seenRefs.add(ref);
        groups.push({
          refAto: ref,
          docs: baseDocs.filter(d => d.ref_ato === ref)
        });
      }
    });

    return groups;
  }, [analysis, searchQuery, activeFilter, sortOrder]);

  const docTypes = useMemo(() => {
    if (!analysis) return [];
    const types = Array.from(new Set(analysis.documentos.map(d => d.tipo_documento_principal).filter(Boolean)));
    return types.sort((a, b) => a.localeCompare(b));
  }, [analysis]);

  const incidentSiblings = useMemo(() => {
    if (!selectedDoc || !analysis) return [];
    return analysis.documentos.filter(d => d.ref_ato === selectedDoc.ref_ato);
  }, [selectedDoc, analysis]);

  if (!analysis && !isProcessing) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 text-slate-900">
        <div className="w-full max-w-2xl space-y-8 animate-in slide-in-from-bottom-4 duration-500">
          <div className="text-center">
            <div className="inline-flex items-center justify-center p-3 bg-blue-600 rounded-2xl shadow-lg mb-4">
              <Gavel className="w-10 h-10 text-white" />
            </div>
            <h1 className="text-4xl font-black tracking-tight">Citius Analytics Pro</h1>
            <p className="mt-3 text-lg text-slate-600 max-w-lg mx-auto leading-relaxed">
              Análise inteligente de processos judiciais exportados.
            </p>
          </div>

          <div className="bg-white p-8 rounded-3xl shadow-2xl border border-slate-200">
            <div 
              onClick={() => fileInputRef.current?.click()}
              onDragOver={handleDragOver}
              onDragEnter={handleDragEnter}
              onDragLeave={handleDragLeave}
              onDrop={handleDrop}
              className={`border-2 border-dashed rounded-2xl p-12 flex flex-col items-center justify-center transition-all cursor-pointer ${
                isDragging ? 'border-blue-600 bg-blue-100 scale-[1.02]' : 
                file ? 'border-blue-400 bg-blue-50' : 'border-slate-300 hover:border-blue-400 hover:bg-slate-50'
              }`}
            >
              <input type="file" ref={fileInputRef} className="hidden" accept=".pdf" onChange={handleFileChange} />
              {file ? (
                <div className="text-center">
                  <FileText className="w-12 h-12 text-blue-600 mb-4 mx-auto" />
                  <h3 className="font-black text-slate-900">{file.name}</h3>
                  <button onClick={(e) => { e.stopPropagation(); setFile(null); }} className="mt-4 text-xs font-bold text-red-500 uppercase tracking-widest hover:text-red-700">
                    Remover ficheiro
                  </button>
                </div>
              ) : (
                <div className="text-center">
                  <FileUp className={`w-12 h-12 mb-4 mx-auto transition-colors ${isDragging ? 'text-blue-600' : 'text-slate-300'}`} />
                  <p className="text-slate-600 font-bold">
                    {isDragging ? 'Solte o ficheiro aqui' : 'Arraste o PDF ou clique para procurar'}
                  </p>
                </div>
              )}
            </div>

            {error && (
              <div className={`mt-4 p-4 rounded-xl border flex items-start gap-3 ${error.isQuota ? 'bg-amber-50 border-amber-200 text-amber-800' : 'bg-red-50 border-red-200 text-red-700'}`}>
                <AlertTriangle className="w-5 h-5 shrink-0 mt-0.5" />
                <div className="flex-1">
                  <p className="text-xs font-bold leading-relaxed">{error.message}</p>
                  {error.isQuota && (
                    <div className="mt-3 flex flex-wrap gap-3">
                      <button 
                        onClick={handleOpenKeySelection}
                        className="flex items-center gap-2 bg-amber-600 text-white px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-wider hover:bg-amber-700 transition-colors"
                      >
                        <Key className="w-3.5 h-3.5" /> Configurar Chave Própria
                      </button>
                      <a 
                        href="https://ai.google.dev/gemini-api/docs/billing" 
                        target="_blank" 
                        rel="noreferrer"
                        className="flex items-center gap-2 text-[10px] font-black uppercase text-amber-700 hover:underline"
                      >
                        Docs Faturação <ExternalLink className="w-3 h-3" />
                      </a>
                    </div>
                  )}
                </div>
              </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-6">
              <button onClick={handleAnalyze} disabled={!file} className="py-4 bg-blue-600 text-white font-black rounded-2xl hover:bg-blue-700 active:scale-[0.98] transition-all flex items-center justify-center space-x-2 shadow-xl shadow-blue-100 disabled:opacity-50 uppercase tracking-widest text-xs">
                <Upload className="w-4 h-4 mr-2" /> Analisar Processo
              </button>

              <button 
                onClick={() => jsonInputRef.current?.click()} 
                className="py-4 bg-white border border-slate-200 text-slate-700 font-black rounded-2xl hover:bg-slate-50 active:scale-[0.98] transition-all flex items-center justify-center space-x-2 uppercase tracking-widest text-xs"
              >
                <FolderOpen className="w-4 h-4 mr-2" /> Recuperar Projeto
              </button>
              <input type="file" ref={jsonInputRef} className="hidden" accept=".json" onChange={handleLoadProject} />
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (isProcessing) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 space-y-8">
        <div className="relative">
          <div className="w-20 h-20 border-8 border-blue-50 border-t-blue-600 rounded-full animate-spin"></div>
          <Gavel className="absolute inset-0 m-auto w-8 h-8 text-blue-600" />
        </div>
        <div className="text-center max-w-sm">
          <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tight mb-2">
            {processingStep === 'extracting' ? 'Extraindo Dados' : 
             processingStep === 'analyzing' ? 'Analisando Estrutura' : 'Gerando Previews Instantâneos'}
          </h2>
          {processingStep === 'snapshots' && (
            <div className="w-full bg-slate-200 h-2 rounded-full mt-4 overflow-hidden">
              <div 
                className="bg-blue-600 h-full transition-all duration-300" 
                style={{ width: `${(snapshotProgress.current / snapshotProgress.total) * 100}%` }}
              />
            </div>
          )}
          <p className="text-[10px] text-slate-400 font-bold uppercase tracking-[0.2em] mt-3 animate-pulse">
            {processingStep === 'snapshots' 
              ? `A processar ${snapshotProgress.current} de ${snapshotProgress.total} peças...` 
              : 'Isto pode demorar alguns segundos...'}
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <header className="sticky top-0 z-30 bg-white border-b px-6 py-3 flex items-center justify-between shadow-sm">
        <div className="flex items-center space-x-4">
          <Gavel className="w-6 h-6 text-blue-600" />
          <div>
            <h1 className="text-xs font-black text-slate-900 uppercase tracking-widest leading-none mb-1">Citius Pro</h1>
            <p className="text-[10px] text-slate-400 font-bold leading-none">{analysis?.numero_processo || 'Processo Indetificado'}</p>
          </div>
        </div>

        <div className="flex-1 max-w-xl mx-8 relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
          <input
            type="text"
            placeholder="Pesquisar referências, partes ou texto..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border-transparent focus:bg-white focus:border-blue-500 rounded-xl text-xs transition-all border font-medium"
          />
        </div>

        <div className="flex items-center space-x-2">
          {analysis?.metrics && (
             <div className="hidden lg:flex items-center space-x-2 px-3 py-1.5 bg-slate-100 rounded-lg border border-slate-200 mr-2" title="Custo de tokens da análise inicial">
                <Cpu className="w-3.5 h-3.5 text-blue-500" />
                <span className="text-[10px] font-black text-slate-500 uppercase tracking-tighter">
                  {analysis.metrics.totalTokens} Tokens
                </span>
             </div>
          )}
          <button 
            onClick={handleSaveProject}
            className="flex items-center space-x-2 px-4 py-2 text-[10px] font-black uppercase bg-blue-50 text-blue-600 border border-blue-100 rounded-xl hover:bg-blue-100 transition-colors"
            title="Guardar análise atual num ficheiro JSON"
          >
            <Download className="w-3.5 h-3.5" />
            <span className="hidden md:inline">Guardar Projeto</span>
          </button>

          <div className="w-px h-6 bg-slate-200 mx-2" />

          <button onClick={() => { setAnalysis(null); setFile(null); setRawText(''); setChatHistory([]); }} className="px-4 py-2 text-[10px] font-black uppercase bg-white border border-slate-200 rounded-xl hover:bg-slate-50 transition-colors">
            Novo Processo
          </button>
        </div>
      </header>

      {!file && analysis && (
        <div className="bg-amber-50 border-b border-amber-200 px-6 py-2 flex items-center justify-between">
          <div className="flex items-center gap-2 text-amber-800 text-[10px] font-black uppercase tracking-tight">
            <AlertTriangle className="w-4 h-4" /> PDF original não vinculado. Algumas funcionalidades de visualização estão limitadas.
          </div>
          <button 
            onClick={() => relinkPdfInputRef.current?.click()}
            className="flex items-center gap-2 px-3 py-1 bg-amber-600 text-white rounded-lg text-[9px] font-black uppercase hover:bg-amber-700 transition-colors"
          >
            <Paperclip className="w-3.5 h-3.5" /> Vincular PDF Original
          </button>
          <input type="file" ref={relinkPdfInputRef} className="hidden" accept=".pdf" onChange={handleFileChange} />
        </div>
      )}

      <div className="flex-1 flex overflow-hidden">
        <aside className="w-72 bg-white border-r hidden lg:flex flex-col p-6 space-y-8 overflow-y-auto shrink-0">
          <div>
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center">
              <ListFilter className="w-3 h-3 mr-2 text-blue-600" /> Filtrar Tipo
            </h3>
            <div className="space-y-1">
              <button onClick={() => setActiveFilter('all')} className={`w-full text-left px-3 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${activeFilter === 'all' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>
                Todos
              </button>
              {docTypes.map(type => (
                <button key={type} onClick={() => setActiveFilter(type)} className={`w-full text-left px-3 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${activeFilter === type ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>
                  {type}
                </button>
              ))}
            </div>
          </div>

          <div>
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center">
              <SortAsc className="w-3 h-3 mr-2 text-blue-600" /> Ordenação
            </h3>
            <div className="bg-slate-50 p-1.5 rounded-2xl border flex flex-col space-y-1">
              <button onClick={() => setSortOrder('chronological')} className={`flex items-center space-x-3 px-3 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${sortOrder === 'chronological' ? 'bg-white shadow-sm border text-blue-600' : 'text-slate-400'}`}>
                <Clock className="w-3.5 h-3.5" /> <span>Índice / Página</span>
              </button>
              <button onClick={() => setSortOrder('alphabetical')} className={`flex items-center space-x-3 px-3 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${sortOrder === 'alphabetical' ? 'bg-white shadow-sm border text-blue-600' : 'text-slate-400'}`}>
                <SortAsc className="w-3.5 h-3.5" /> <span>Alfabética</span>
              </button>
            </div>
          </div>
        </aside>

        <main className="flex-1 overflow-y-auto p-10 bg-slate-50">
          <div className="max-w-5xl mx-auto">
            <div className="mb-10 flex flex-col md:flex-row md:items-end justify-between gap-6">
              <div>
                <h2 className="text-2xl font-black text-slate-900 tracking-tight">Painel de Trabalho</h2>
                <p className="text-slate-500 text-sm font-medium">Cronologia e Assistência Inteligente.</p>
              </div>

              <div className="flex bg-white p-1 rounded-2xl border border-slate-200 shadow-sm shrink-0">
                <button 
                  onClick={() => setActiveTab('timeline')}
                  className={`flex items-center space-x-2 px-6 py-2.5 rounded-xl text-xs font-black uppercase transition-all ${
                    activeTab === 'timeline' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-50'
                  }`}
                >
                  <LayoutGrid className="w-4 h-4" />
                  <span>Timeline</span>
                </button>
                <button 
                  onClick={() => setActiveTab('assistant')}
                  className={`flex items-center space-x-2 px-6 py-2.5 rounded-xl text-xs font-black uppercase transition-all ${
                    activeTab === 'assistant' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-50'
                  }`}
                >
                  <Bot className="w-4 h-4" />
                  <span>Assistente</span>
                </button>
              </div>
            </div>

            {activeTab === 'timeline' ? (
              groupedDocs.length > 0 ? (
                <div className="space-y-2">
                  {groupedDocs.map(group => (
                    <DocumentGroup 
                      key={group.refAto} 
                      refAto={group.refAto} 
                      documents={group.docs} 
                      onDocumentClick={setSelectedDoc}
                    />
                  ))}
                </div>
              ) : (
                <div className="py-24 text-center bg-white rounded-3xl border-2 border-dashed border-slate-100">
                  <FileText className="w-12 h-12 text-slate-200 mx-auto mb-4" />
                  <h3 className="text-slate-900 font-black uppercase text-xs tracking-widest">Nenhum resultado</h3>
                </div>
              )
            ) : (
              <AssistantView 
                documents={analysis!.documentos} 
                file={file} 
                rawText={rawText} 
                chatHistory={chatHistory}
                setChatHistory={setChatHistory}
                onFileLink={(newFile) => setFile(newFile)}
              />
            )}
          </div>
        </main>
      </div>

      {selectedDoc && (
        <DocumentDetail 
          doc={selectedDoc} 
          file={file}
          onClose={() => setSelectedDoc(null)} 
          siblings={incidentSiblings}
          onSelectSibling={setSelectedDoc}
          onFileRelink={(f) => setFile(f)}
        />
      )}
    </div>
  );
};

export default App;

import React, { useMemo, useState, useRef } from 'react';
import { DocumentMetadata, DocumentType, SubDocument } from '../types';
import { X, FileSearch, Library, ExternalLink, Scale, ShieldCheck, User, Paperclip, AlertTriangle } from 'lucide-react';
import { TYPE_COLORS } from '../constants';
import { PdfPagePreview } from './PdfPagePreview';

interface DocumentDetailProps {
  doc: DocumentMetadata;
  file: File | null;
  onClose: () => void;
  siblings?: DocumentMetadata[];
  onSelectSibling: (doc: DocumentMetadata) => void;
  onFileRelink?: (file: File) => void;
}

export const DocumentDetail: React.FC<DocumentDetailProps> = ({ doc, file, onClose, siblings = [], onSelectSibling, onFileRelink }) => {
  const [activeTab, setActiveTab] = useState<'preview' | 'subdocs'>(doc.sub_documentos?.length ? 'subdocs' : 'preview');
  const colorClass = TYPE_COLORS[doc.tipo_documento_principal] || 'bg-gray-100 text-gray-800 border-gray-200';
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleOpenPdf = (pageNumber?: number) => {
    if (!file) {
      fileInputRef.current?.click();
      return;
    }
    const fileUrl = URL.createObjectURL(file);
    const targetPage = pageNumber || doc.pagina_inicial;
    // Abrir em novo separador garantindo que o PDF reader do browser recebe o parâmetro de página
    const win = window.open(`${fileUrl}#page=${targetPage}`, '_blank');
    if (win) {
      win.focus();
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newFile = e.target.files?.[0];
    if (newFile && onFileRelink) {
      onFileRelink(newFile);
    }
  };

  const getRoleLabel = () => {
    if (doc.parte_apresentante === "Tribunal") return "Juiz";
    if (doc.parte_apresentante === "Ministério Público") return "Procurador";
    return "Mandatário";
  };

  const getRoleIcon = () => {
    if (doc.parte_apresentante === "Tribunal") return <Scale className="w-3.5 h-3.5 mr-2 text-blue-500" />;
    if (doc.parte_apresentante === "Ministério Público") return <ShieldCheck className="w-3.5 h-3.5 mr-2 text-purple-500" />;
    return <User className="w-3.5 h-3.5 mr-2 text-slate-400" />;
  };

  const hasSiblings = useMemo(() => {
    return siblings.length > 1;
  }, [siblings]);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm p-4 animate-in fade-in duration-300">
      <div className="bg-white w-full max-w-6xl h-[90vh] rounded-3xl shadow-2xl overflow-hidden flex flex-col md:flex-row border border-white/20">

        <div className="flex-1 flex flex-col min-w-0 bg-white">
          <div className="px-10 py-6 border-b flex items-center justify-between bg-gray-50/50">
            <div className="flex flex-col min-w-0 flex-1 mr-4">
              <span className={`w-fit px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border mb-2 shadow-sm ${colorClass}`}>
                {doc.tipo_documento_principal}
              </span>
              <h2 className="text-xl md:text-2xl font-black text-gray-900 truncate tracking-tight">
                {doc.titulo_resumido}
              </h2>
            </div>

            <div className="flex items-center space-x-2 shrink-0">
              <input type="file" ref={fileInputRef} className="hidden" accept=".pdf" onChange={handleFileChange} />
              <button 
                onClick={() => handleOpenPdf()}
                className={`flex items-center space-x-2 px-4 py-2.5 rounded-xl text-xs font-black transition-all shadow-lg active:scale-95 ${
                  file ? 'bg-blue-600 text-white hover:bg-blue-700' : 'bg-amber-100 text-amber-700 border border-amber-200 hover:bg-amber-200'
                }`}
              >
                {file ? <FileSearch className="w-4 h-4" /> : <Paperclip className="w-4 h-4" />}
                <span>{file ? `Abrir Original (Pág. ${doc.pagina_inicial})` : 'Vincular PDF para Abrir'}</span>
              </button>
              <button 
                onClick={onClose} 
                className="p-2 hover:bg-gray-200 rounded-full transition-colors text-gray-400"
              >
                <X className="w-6 h-6" />
              </button>
            </div>
          </div>

          <div className="flex px-10 bg-white border-b">
            <button 
              onClick={() => setActiveTab('preview')}
              className={`px-6 py-4 text-xs font-black uppercase tracking-widest border-b-2 transition-all ${activeTab === 'preview' ? 'border-blue-600 text-blue-600' : 'border-transparent text-gray-400 hover:text-gray-600'}`}
            >
              Visualização (Pág. {doc.pagina_inicial})
            </button>
            {doc.sub_documentos && doc.sub_documentos.length > 0 && (
              <button 
                onClick={() => setActiveTab('subdocs')}
                className={`px-6 py-4 text-xs font-black uppercase tracking-widest border-b-2 transition-all flex items-center gap-2 ${activeTab === 'subdocs' ? 'border-blue-600 text-blue-600' : 'border-transparent text-gray-400 hover:text-gray-600'}`}
              >
                <Library className="w-4 h-4" /> Anexos ({doc.sub_documentos.length})
              </button>
            )}
          </div>

          <div className="flex-1 overflow-hidden p-4 bg-slate-200 shadow-inner">
            {activeTab === 'preview' ? (
              <div className="h-full animate-in slide-in-from-left-4 duration-300">
                <PdfPagePreview file={file} pageNumber={doc.pagina_inicial} snapshot={doc.snapshot} />
              </div>
            ) : (
              <div className="h-full overflow-y-auto animate-in slide-in-from-right-4 duration-300 bg-white rounded-2xl p-8 border">
                <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.3em] mb-6 flex items-center">
                  <Library className="w-4 h-4 mr-2 text-blue-500" /> Documentos Agrupados
                </h3>
                <div className="grid grid-cols-1 gap-3">
                  {doc.sub_documentos?.map((sub, idx) => (
                    <div key={idx} className="p-4 bg-slate-50 border rounded-2xl flex items-center justify-between">
                      <div>
                        <h4 className="text-[14px] font-black text-gray-900">{sub.titulo}</h4>
                        <p className="text-[11px] text-gray-500">{sub.descricao}</p>
                      </div>
                      <button 
                        onClick={() => handleOpenPdf(sub.pagina_pdf)}
                        className="px-4 py-2 bg-blue-600 text-white rounded-xl font-black text-[10px] uppercase"
                      >
                        Pág. {sub.pagina_pdf}
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="w-full md:w-80 bg-gray-50 border-l border-gray-100 p-8 overflow-y-auto space-y-8">
          <div>
            <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.3em] mb-6">Dados da Peça</h3>
            <div className="space-y-5">
              <MetaItem label="Processo" value={doc.numero_processo} isHighlight />
              <MetaItem label="Ref. Ato" value={doc.ref_ato} isBadge />
              <MetaItem label="Ref. Doc" value={doc.ref_documento} isBadge />
              <MetaItem label="Apresentante" value={doc.parte_apresentante} />
              <MetaItem 
                label={getRoleLabel()} 
                value={doc.mandatario || 'Não identificado'} 
                icon={getRoleIcon()}
              />
              <MetaItem label="Localização" value={`Págs. ${doc.pagina_inicial} - ${doc.pagina_final || '?'}`} />
            </div>
          </div>

          {!file && (
            <div className="p-4 bg-amber-50 border border-amber-200 rounded-2xl">
              <div className="flex items-center gap-2 text-amber-800 text-[10px] font-black uppercase mb-2">
                <AlertTriangle className="w-3.5 h-3.5" /> PDF em Falta
              </div>
              <p className="text-[11px] text-amber-900 leading-relaxed mb-3 font-medium">
                Vincule o ficheiro PDF original para poder abrir as páginas em tamanho real e navegar no processo.
              </p>
              <button 
                onClick={() => handleOpenPdf()}
                className="w-full py-2 bg-amber-600 text-white rounded-lg text-[9px] font-black uppercase shadow-sm"
              >
                Vincular PDF
              </button>
            </div>
          )}

          {hasSiblings && (
            <div className="pt-8 border-t border-gray-200">
              <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.3em] mb-4">Ato Completo</h3>
              <div className="space-y-2">
                {siblings.map((sibling) => (
                  <button
                    key={sibling.id_documento}
                    onClick={() => onSelectSibling(sibling)}
                    className={`w-full text-left p-3 rounded-xl text-[10px] font-bold border transition-all ${
                      sibling.id_documento === doc.id_documento 
                        ? 'bg-blue-600 text-white border-blue-600 shadow-md' 
                        : 'bg-white text-gray-700 hover:bg-gray-50'
                    }`}
                  >
                    <div className="uppercase truncate">{sibling.tipo_documento_indice || sibling.tipo_documento_principal}</div>
                    <div className="text-[9px] opacity-70">Pág: {sibling.pagina_inicial}</div>
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

const MetaItem = ({ label, value, isBadge, isHighlight, icon }: { label: string; value: string; isBadge?: boolean; isHighlight?: boolean, icon?: React.ReactNode }) => (
  <div className="group">
    <span className="text-[10px] font-black text-gray-400 uppercase flex items-center tracking-tight mb-1.5">
      {icon} {label}
    </span>
    <span className={`text-[12px] font-extrabold block leading-tight ${
      isBadge ? 'text-blue-700 bg-blue-50 px-2 py-0.5 rounded-md border border-blue-100 w-fit' : 
      isHighlight ? 'text-blue-900 bg-white border border-blue-600/20 px-3 py-1.5 rounded-lg shadow-sm' : 
      'text-gray-900'
    }`}>
      {value || '---'}
    </span>
  </div>
);

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { DocumentMetadata, ProcessAnalysis, SortOrder, TokenMetrics, ChatMessage } from './types';
import { analyzeProcessText } from './services/geminiService';
import { extractTextFromPdf, getPageSnapshot, getPdfDocument } from './services/pdfService';
import { DocumentGroup } from './components/DocumentGroup';
import { DocumentDetail } from './components/DocumentDetail';
import { AssistantView } from './components/AssistantView';
import { 
  Search, 
  Upload, 
  Gavel, 
  FileText, 
  FileUp,
  Clock,
  SortAsc,
  ListFilter,
  Download,
  FolderOpen,
  LayoutGrid,
  Bot,
  Key,
  AlertTriangle,
  ExternalLink,
  Cpu,
  Loader2,
  Paperclip
} from 'lucide-react';

const App: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [rawText, setRawText] = useState<string>(''); 
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStep, setProcessingStep] = useState<'extracting' | 'analyzing' | 'snapshots' | null>(null);
  const [snapshotProgress, setSnapshotProgress] = useState({ current: 0, total: 0 });
  const [analysis, setAnalysis] = useState<ProcessAnalysis | null>(null);
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [selectedDoc, setSelectedDoc] = useState<DocumentMetadata | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [activeFilter, setActiveFilter] = useState<string>('all');
  const [sortOrder, setSortOrder] = useState<SortOrder>('chronological');
  const [error, setError] = useState<{ message: string; isQuota?: boolean } | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [activeTab, setActiveTab] = useState<'timeline' | 'assistant'>('timeline');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const jsonInputRef = useRef<HTMLInputElement>(null);
  const relinkPdfInputRef = useRef<HTMLInputElement>(null);

  const handleOpenKeySelection = async () => {
    try {
      // @ts-ignore
      await window.aistudio.openSelectKey();
      setError(null);
    } catch (err) {
      console.error("Failed to open key selection", err);
    }
  };

  const validateAndSetFile = (selectedFile: File) => {
    if (selectedFile && selectedFile.type === 'application/pdf') {
      setFile(selectedFile);
      setError(null);
    } else {
      setError({ message: 'Por favor, selecione apenas ficheiros PDF para análise.' });
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(true);
  };

  const handleDragEnter = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);

    const droppedFile = e.dataTransfer.files?.[0];
    if (droppedFile) {
      validateAndSetFile(droppedFile);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile) validateAndSetFile(selectedFile);
  };

  const handleAnalyze = async () => {
    if (!file) return;
    setIsProcessing(true);
    setError(null);
    try {
      setProcessingStep('extracting');
      const extractedText = await extractTextFromPdf(file);
      const pdf = await getPdfDocument(file);
      const totalPages = pdf.numPages;
      setRawText(extractedText);

      setProcessingStep('analyzing');
      const result = await analyzeProcessText(extractedText);

      // ORDENAÇÃO E PÓS-PROCESSAMENTO PARA GARANTIR PÁGINAS FINAIS
      const sortedDocs = [...result.documentos].sort((a, b) => a.pagina_inicial - b.pagina_inicial);

      for (let i = 0; i < sortedDocs.length; i++) {
        const doc = sortedDocs[i];

        // Garante o número do processo em cada doc
        doc.numero_processo = result.numero_processo;

        // Calcula página final baseando-se no próximo documento
        if (i < sortedDocs.length - 1) {
          doc.pagina_final = sortedDocs[i + 1].pagina_inicial - 1;
        } else {
          doc.pagina_final = totalPages;
        }
      }

      setProcessingStep('snapshots');
      setSnapshotProgress({ current: 0, total: sortedDocs.length });

      for (let i = 0; i < sortedDocs.length; i++) {
        const doc = sortedDocs[i];
        try {
          doc.snapshot = await getPageSnapshot(file, doc.pagina_inicial);
        } catch (e) {
          console.warn(`Snapshot failed for doc ${doc.id_documento}`);
        }
        setSnapshotProgress(prev => ({ ...prev, current: i + 1 }));
      }

      setAnalysis({ ...result, documentos: sortedDocs });
      setChatHistory([]); 
    } catch (err: any) {
      console.error(err);
      const isQuota = err?.message?.includes('429') || err?.status === 429;
      setError({ 
        message: isQuota 
          ? 'Limite excedido. Configure a sua chave da API.' 
          : 'Erro ao processar o PDF. Tente novamente.',
        isQuota: isQuota
      });
    } finally {
      setIsProcessing(false);
      setProcessingStep(null);
    }
  };

  const handleSaveProject = () => {
    if (!analysis) return;
    const projectData = { ...analysis, _rawText: rawText, chatHistory: chatHistory };
    const blob = new Blob([JSON.stringify(projectData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Citius_${analysis.numero_processo.replace(/\//g, '_')}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleLoadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (!selectedFile) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json && json.documentos) {
          setAnalysis(json);
          if (json._rawText) setRawText(json._rawText);
          if (json.chatHistory) setChatHistory(json.chatHistory);
          setFile(null); 
          setError(null);
        }
      } catch (err) {
        setError({ message: 'Erro ao ler o ficheiro JSON.' });
      }
    };
    reader.readAsText(selectedFile);
    e.target.value = '';
  };

  const groupedDocs = useMemo(() => {
    if (!analysis) return [];
    const query = searchQuery.toLowerCase();

    let baseDocs = analysis.documentos.filter(doc => {
      const titulo = (doc.titulo_resumido || '').toLowerCase();
      const sumario = (doc.sumario || '').toLowerCase();
      const apresentante = (doc.parte_apresentante || '').toLowerCase();
      const refAto = (doc.ref_ato || '');
      const refDoc = (doc.ref_documento || '');

      const matchesSearch = 
        titulo.includes(query) ||
        sumario.includes(query) ||
        apresentante.includes(query) ||
        refAto.includes(searchQuery) ||
        refDoc.includes(searchQuery);

      const matchesFilter = activeFilter === 'all' || doc.tipo_documento_principal === activeFilter;
      return matchesSearch && matchesFilter;
    });

    if (sortOrder === 'alphabetical') {
      baseDocs.sort((a, b) => (a.titulo_resumido || '').localeCompare(b.titulo_resumido || ''));
    } else {
      baseDocs.sort((a, b) => (a.pagina_inicial || 0) - (b.pagina_inicial || 0));
    }

    const groups: { refAto: string, docs: DocumentMetadata[] }[] = [];
    const seenRefs = new Set<string>();

    baseDocs.forEach(doc => {
      const ref = doc.ref_ato || 'Sem Ref';
      if (!seenRefs.has(ref)) {
        seenRefs.add(ref);
        groups.push({
          refAto: ref,
          docs: baseDocs.filter(d => d.ref_ato === ref)
        });
      }
    });

    return groups;
  }, [analysis, searchQuery, activeFilter, sortOrder]);

  const docTypes = useMemo(() => {
    if (!analysis) return [];
    return Array.from(new Set(analysis.documentos.map(d => d.tipo_documento_principal).filter(Boolean))).sort();
  }, [analysis]);

  const incidentSiblings = useMemo(() => {
    if (!selectedDoc || !analysis) return [];
    return analysis.documentos.filter(d => d.ref_ato === selectedDoc.ref_ato);
  }, [selectedDoc, analysis]);

  if (!analysis && !isProcessing) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 text-slate-900">
        <div className="w-full max-w-2xl space-y-8 animate-in slide-in-from-bottom-4 duration-500">
          <div className="text-center">
            <div className="inline-flex items-center justify-center p-3 bg-blue-600 rounded-2xl shadow-lg mb-4">
              <Gavel className="w-10 h-10 text-white" />
            </div>
            <h1 className="text-4xl font-black tracking-tight">Citius Analytics Pro</h1>
          </div>
          <div className="bg-white p-8 rounded-3xl shadow-2xl border border-slate-200">
            <div 
              onClick={() => fileInputRef.current?.click()}
              onDragOver={handleDragOver}
              onDragEnter={handleDragEnter}
              onDragLeave={handleDragLeave}
              onDrop={handleDrop}
              className={`border-2 border-dashed rounded-2xl p-12 flex flex-col items-center justify-center transition-all cursor-pointer ${
                isDragging ? 'border-blue-600 bg-blue-100' : 'border-slate-300 hover:border-blue-400 hover:bg-slate-50'
              }`}
            >
              <input type="file" ref={fileInputRef} className="hidden" accept=".pdf" onChange={handleFileChange} />
              {file ? (
                <div className="text-center">
                  <FileText className="w-12 h-12 text-blue-600 mb-2 mx-auto" />
                  <h3 className="font-black text-slate-900">{file.name}</h3>
                </div>
              ) : (
                <div className="text-center text-slate-400">
                  <FileUp className="w-12 h-12 mb-2 mx-auto" />
                  <p className="font-bold">Clique ou arraste o PDF para análise</p>
                </div>
              )}
            </div>
            {error && <div className="mt-4 p-4 rounded-xl bg-red-50 text-red-700 text-xs font-bold border border-red-100">{error.message}</div>}
            <div className="grid grid-cols-2 gap-4 mt-6">
              <button onClick={handleAnalyze} disabled={!file} className="py-4 bg-blue-600 text-white font-black rounded-2xl hover:bg-blue-700 disabled:opacity-50 uppercase tracking-widest text-xs shadow-xl shadow-blue-100">
                Analisar Processo
              </button>
              <button onClick={() => jsonInputRef.current?.click()} className="py-4 bg-white border border-slate-200 text-slate-700 font-black rounded-2xl hover:bg-slate-50 uppercase tracking-widest text-xs">
                Recuperar Projeto
              </button>
              <input type="file" ref={jsonInputRef} className="hidden" accept=".json" onChange={handleLoadProject} />
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (isProcessing) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 space-y-8">
        <div className="relative">
          <div className="w-20 h-20 border-8 border-blue-50 border-t-blue-600 rounded-full animate-spin"></div>
          <Gavel className="absolute inset-0 m-auto w-8 h-8 text-blue-600" />
        </div>
        <div className="text-center">
          <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tight">
            {processingStep === 'extracting' ? 'Lendo PDF' : 
             processingStep === 'analyzing' ? 'IA mapeando índice' : 'Gerando Previews Instantâneos'}
          </h2>
          {processingStep === 'snapshots' && (
            <div className="w-64 bg-slate-200 h-2 rounded-full mt-4 overflow-hidden mx-auto">
              <div className="bg-blue-600 h-full transition-all duration-300" style={{ width: `${(snapshotProgress.current / snapshotProgress.total) * 100}%` }} />
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <header className="sticky top-0 z-30 bg-white border-b px-6 py-3 flex items-center justify-between shadow-sm">
        <div className="flex items-center space-x-4">
          <Gavel className="w-6 h-6 text-blue-600" />
          <div>
            <h1 className="text-xs font-black text-slate-900 uppercase tracking-widest leading-none mb-1">Citius Pro</h1>
            <p className="text-[10px] text-slate-400 font-bold leading-none">{analysis?.numero_processo}</p>
          </div>
        </div>
        <div className="flex-1 max-w-xl mx-8 relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
          <input type="text" placeholder="Filtrar cronologia..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border-transparent focus:bg-white focus:border-blue-500 rounded-xl text-xs transition-all border font-medium" />
        </div>
        <div className="flex items-center space-x-2">
          <button onClick={handleSaveProject} className="flex items-center space-x-2 px-4 py-2 text-[10px] font-black uppercase bg-blue-50 text-blue-600 border border-blue-100 rounded-xl hover:bg-blue-100 transition-colors">
            <Download className="w-3.5 h-3.5" /> <span className="hidden md:inline">Guardar JSON</span>
          </button>
          <button onClick={() => { setAnalysis(null); setFile(null); }} className="px-4 py-2 text-[10px] font-black uppercase bg-white border border-slate-200 rounded-xl hover:bg-slate-50 transition-colors">Novo</button>
        </div>
      </header>

      {!file && analysis && (
        <div className="bg-amber-50 border-b border-amber-200 px-6 py-2 flex items-center justify-between">
          <div className="flex items-center gap-2 text-amber-800 text-[10px] font-black uppercase tracking-tight">
            <AlertTriangle className="w-4 h-4" /> PDF original não vinculado.
          </div>
          <button onClick={() => relinkPdfInputRef.current?.click()} className="flex items-center gap-2 px-3 py-1 bg-amber-600 text-white rounded-lg text-[9px] font-black uppercase hover:bg-amber-700 transition-colors">
            <Paperclip className="w-3.5 h-3.5" /> Vincular PDF
          </button>
          <input type="file" ref={relinkPdfInputRef} className="hidden" accept=".pdf" onChange={handleFileChange} />
        </div>
      )}

      <div className="flex-1 flex overflow-hidden">
        <aside className="w-64 bg-white border-r hidden lg:flex flex-col p-6 space-y-8 overflow-y-auto shrink-0">
          <div>
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Filtrar</h3>
            <div className="space-y-1">
              <button onClick={() => setActiveFilter('all')} className={`w-full text-left px-3 py-2 rounded-lg text-[10px] font-black uppercase ${activeFilter === 'all' ? 'bg-blue-600 text-white' : 'text-slate-500 hover:bg-slate-50'}`}>Todos</button>
              {docTypes.map(type => (
                <button key={type} onClick={() => setActiveFilter(type)} className={`w-full text-left px-3 py-2 rounded-lg text-[10px] font-black uppercase ${activeFilter === type ? 'bg-blue-600 text-white' : 'text-slate-500 hover:bg-slate-50'}`}>{type}</button>
              ))}
            </div>
          </div>
        </aside>

        <main className="flex-1 overflow-y-auto p-10 bg-slate-50">
          <div className="max-w-5xl mx-auto">
            <div className="flex bg-white p-1 rounded-2xl border border-slate-200 shadow-sm w-fit mb-8">
              <button onClick={() => setActiveTab('timeline')} className={`px-6 py-2 rounded-xl text-xs font-black uppercase transition-all ${activeTab === 'timeline' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-50'}`}>Timeline</button>
              <button onClick={() => setActiveTab('assistant')} className={`px-6 py-2 rounded-xl text-xs font-black uppercase transition-all ${activeTab === 'assistant' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-50'}`}>Assistente</button>
            </div>

            {activeTab === 'timeline' ? (
              <div className="space-y-2">
                {groupedDocs.map(group => (
                  <DocumentGroup key={group.refAto} refAto={group.refAto} documents={group.docs} onDocumentClick={setSelectedDoc} />
                ))}
              </div>
            ) : (
              <AssistantView documents={analysis!.documentos} file={file} rawText={rawText} chatHistory={chatHistory} setChatHistory={setChatHistory} onFileLink={(f) => setFile(f)} />
            )}
          </div>
        </main>
      </div>

      {selectedDoc && (
        <DocumentDetail doc={selectedDoc} file={file} onClose={() => setSelectedDoc(null)} siblings={incidentSiblings} onSelectSibling={setSelectedDoc} onFileRelink={(f) => setFile(f)} />
      )}
    </div>
  );
};

export default App;

import React, { useMemo, useState, useRef } from 'react';
import { DocumentMetadata, DocumentType, SubDocument } from '../types';
import { X, FileSearch, Library, ExternalLink, Scale, ShieldCheck, User, Paperclip, AlertTriangle } from 'lucide-react';
import { TYPE_COLORS } from '../constants';
import { PdfPagePreview } from './PdfPagePreview';

interface DocumentDetailProps {
  doc: DocumentMetadata;
  file: File | null;
  onClose: () => void;
  siblings?: DocumentMetadata[];
  onSelectSibling: (doc: DocumentMetadata) => void;
  onFileRelink?: (file: File) => void;
}

export const DocumentDetail: React.FC<DocumentDetailProps> = ({ doc, file, onClose, siblings = [], onSelectSibling, onFileRelink }) => {
  const [activeTab, setActiveTab] = useState<'preview' | 'subdocs'>(doc.sub_documentos?.length ? 'subdocs' : 'preview');
  const colorClass = TYPE_COLORS[doc.tipo_documento_principal] || 'bg-gray-100 text-gray-800 border-gray-200';
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleOpenPdf = (pageNumber?: number) => {
    if (!file) {
      fileInputRef.current?.click();
      return;
    }
    const fileUrl = URL.createObjectURL(file);
    const targetPage = pageNumber || doc.pagina_inicial;
    const win = window.open(`${fileUrl}#page=${targetPage}`, '_blank');
    if (win) win.focus();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newFile = e.target.files?.[0];
    if (newFile && onFileRelink) onFileRelink(newFile);
  };

  const getRoleLabel = () => {
    if (doc.parte_apresentante === "Tribunal") return "Juiz";
    if (doc.parte_apresentante === "Ministério Público") return "Procurador";
    return "Mandatário";
  };

  const getRoleIcon = () => {
    if (doc.parte_apresentante === "Tribunal") return <Scale className="w-3.5 h-3.5 mr-2 text-blue-500" />;
    if (doc.parte_apresentante === "Ministério Público") return <ShieldCheck className="w-3.5 h-3.5 mr-2 text-purple-500" />;
    return <User className="w-3.5 h-3.5 mr-2 text-slate-400" />;
  };

  const hasSiblings = useMemo(() => siblings.length > 1, [siblings]);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm p-4 animate-in fade-in duration-300">
      <div className="bg-white w-full max-w-6xl h-[90vh] rounded-3xl shadow-2xl overflow-hidden flex flex-col md:flex-row border border-white/20">

        <div className="flex-1 flex flex-col min-w-0 bg-white">
          <div className="px-10 py-6 border-b flex items-center justify-between bg-gray-50/50">
            <div className="flex flex-col min-w-0 flex-1 mr-4">
              <span className={`w-fit px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border mb-2 shadow-sm ${colorClass}`}>
                {doc.tipo_documento_principal}
              </span>
              <h2 className="text-xl md:text-2xl font-black text-gray-900 truncate tracking-tight">
                {doc.titulo_resumido}
              </h2>
            </div>

            <div className="flex items-center space-x-2 shrink-0">
              <input type="file" ref={fileInputRef} className="hidden" accept=".pdf" onChange={handleFileChange} />
              <button 
                onClick={() => handleOpenPdf()}
                className={`flex items-center space-x-2 px-4 py-2.5 rounded-xl text-xs font-black transition-all shadow-lg active:scale-95 ${
                  file ? 'bg-blue-600 text-white hover:bg-blue-700' : 'bg-amber-100 text-amber-700 border border-amber-200'
                }`}
              >
                {file ? <FileSearch className="w-4 h-4" /> : <Paperclip className="w-4 h-4" />}
                <span>{file ? `Abrir Original (Pág. ${doc.pagina_inicial})` : 'Vincular PDF'}</span>
              </button>
              <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full transition-colors text-gray-400">
                <X className="w-6 h-6" />
              </button>
            </div>
          </div>

          <div className="flex px-10 bg-white border-b">
            <button onClick={() => setActiveTab('preview')} className={`px-6 py-4 text-xs font-black uppercase tracking-widest border-b-2 transition-all ${activeTab === 'preview' ? 'border-blue-600 text-blue-600' : 'border-transparent text-gray-400'}`}>
              Visualização (Pág. {doc.pagina_inicial})
            </button>
            {doc.sub_documentos && doc.sub_documentos.length > 0 && (
              <button onClick={() => setActiveTab('subdocs')} className={`px-6 py-4 text-xs font-black uppercase tracking-widest border-b-2 transition-all ${activeTab === 'subdocs' ? 'border-blue-600 text-blue-600' : 'border-transparent text-gray-400'}`}>
                Anexos ({doc.sub_documentos.length})
              </button>
            )}
          </div>

          <div className="flex-1 overflow-hidden p-4 bg-slate-200 shadow-inner">
            <div className="h-full animate-in slide-in-from-left-4 duration-300">
              <PdfPagePreview file={file} pageNumber={doc.pagina_inicial} snapshot={doc.snapshot} />
            </div>
          </div>
        </div>

        <div className="w-full md:w-80 bg-gray-50 border-l border-gray-100 p-8 overflow-y-auto space-y-8">
          <div>
            <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.3em] mb-6">Dados da Peça</h3>
            <div className="space-y-5">
              <MetaItem label="Processo" value={doc.numero_processo || '---'} isHighlight />
              <MetaItem label="Ref. Ato" value={doc.ref_ato} isBadge />
              <MetaItem label="Ref. Doc" value={doc.ref_documento} isBadge />
              <MetaItem label="Apresentante" value={doc.parte_apresentante} />
              <MetaItem label={getRoleLabel()} value={doc.mandatario || '---'} icon={getRoleIcon()} />
              <MetaItem label="Localização" value={`Págs. ${doc.pagina_inicial} - ${doc.pagina_final || '?'}`} />
            </div>
          </div>

          {hasSiblings && (
            <div className="pt-8 border-t border-gray-200">
              <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.3em] mb-4">Ato Completo</h3>
              <div className="space-y-2">
                {siblings.map((sibling) => (
                  <button
                    key={sibling.id_documento}
                    onClick={() => onSelectSibling(sibling)}
                    className={`w-full text-left p-3 rounded-xl text-[10px] font-bold border transition-all ${
                      sibling.id_documento === doc.id_documento 
                        ? 'bg-blue-600 text-white border-blue-600 shadow-md' 
                        : 'bg-white text-gray-700 hover:bg-gray-50'
                    }`}
                  >
                    <div className="uppercase truncate">{sibling.tipo_documento_indice || sibling.tipo_documento_principal}</div>
                    <div className="text-[9px] opacity-70">Pág: {sibling.pagina_inicial}</div>
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

const MetaItem = ({ label, value, isBadge, isHighlight, icon }: { label: string; value: string; isBadge?: boolean; isHighlight?: boolean, icon?: React.ReactNode }) => (
  <div className="group">
    <span className="text-[10px] font-black text-gray-400 uppercase flex items-center tracking-tight mb-1.5">
      {icon} {label}
    </span>
    <span className={`text-[12px] font-extrabold block leading-tight ${
      isBadge ? 'text-blue-700 bg-blue-50 px-2 py-0.5 rounded-md border border-blue-100 w-fit' : 
      isHighlight ? 'text-blue-900 bg-white border border-blue-600/20 px-3 py-1.5 rounded-lg shadow-sm' : 
      'text-gray-900'
    }`}>
      {value || '---'}
    </span>
  </div>
);

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { DocumentMetadata, ChatMessage, TokenMetrics } from '../types';
import { askAssistant } from '../services/geminiService';
import { 
  Send, 
  Bot, 
  User, 
  Loader2, 
  FileText, 
  ExternalLink, 
  Download, 
  Trash2,
  Cpu,
  ArrowRightCircle,
  Paperclip,
  AlertCircle
} from 'lucide-react';

interface AssistantViewProps {
  documents: DocumentMetadata[];
  file: File | null;
  rawText: string;
  chatHistory: ChatMessage[];
  setChatHistory: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  onFileLink?: (file: File) => void;
}

export const AssistantView: React.FC<AssistantViewProps> = ({ 
  documents, 
  file, 
  rawText, 
  chatHistory, 
  setChatHistory,
  onFileLink
}) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const pdfUrl = useMemo(() => {
    if (!file) return null;
    return URL.createObjectURL(file);
  }, [file]);

  useEffect(() => {
    return () => {
      if (pdfUrl) URL.revokeObjectURL(pdfUrl);
    };
  }, [pdfUrl]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [chatHistory, isLoading]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMessage: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      timestamp: Date.now()
    };

    setChatHistory(prev => [...prev, userMessage]);
    setInput('');
    setIsLoading(true);

    try {
      const docsContext = documents.map(d => 
        `Ref Doc: ${d.ref_documento} | Titulo: ${d.titulo_resumido} | Pagina: ${d.pagina_inicial}`
      ).join('\n');

      const result = await askAssistant(input, rawText, docsContext);

      const assistantMessage: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: result.answer,
        citations: result.citations,
        metrics: result.metrics,
        timestamp: Date.now()
      };

      setChatHistory(prev => [...prev, assistantMessage]);
    } catch (error) {
      console.error(error);
      const errorMessage: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: "Lamento, ocorreu um erro ao processar a sua pergunta. Verifique a ligação e tente novamente.",
        timestamp: Date.now()
      };
      setChatHistory(prev => [...prev, errorMessage]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleOpenDoc = (page: number) => {
    if (!pdfUrl) {
      alert("Por favor, vincule o ficheiro PDF original para abrir as páginas.");
      fileInputRef.current?.click();
      return;
    }
    window.open(`${pdfUrl}#page=${page}`, '_blank');
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newFile = e.target.files?.[0];
    if (newFile && onFileLink) {
      onFileLink(newFile);
    }
  };

  const downloadToWord = (msg?: ChatMessage) => {
    let bodyHtml = "";

    if (msg) {
      const userContent = chatHistory.find(m => m.timestamp < msg.timestamp && m.role === 'user')?.content;
      bodyHtml = `
        <h3>PERGUNTA:</h3>
        <p>${userContent?.replace(/\n/g, '<br>')}</p>
        <hr/>
        <h3>RESPOSTA DO ASSISTENTE:</h3>
        <p>${msg.content.replace(/\n/g, '<br>')}</p>
        <h4>Documentos citados:</h4>
        <ul>
          ${msg.citations?.map(c => `<li>${c.titulo} (Ref: ${c.ref_documento}, Pág: ${c.pagina})</li>`).join('') || ''}
        </ul>
      `;
    } else {
      bodyHtml = chatHistory.map(m => {
        const role = m.role === 'user' ? 'UTILIZADOR' : 'ASSISTENTE';
        return `
          <div style="margin-bottom: 20px; padding: 10px; border: 1px solid #eee;">
            <b style="color: #2563eb;">${role}:</b><br/>
            <p>${m.content.replace(/\n/g, '<br>')}</p>
            ${m.citations ? '<br/><b>CITAÇÕES:</b><ul>' + m.citations.map(c => `<li>${c.titulo} (Pág. ${c.pagina})</li>`).join('') + '</ul>' : ''}
          </div>
        `;
      }).join('');
    }

    const header = `<html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'>
                    <head><meta charset='utf-8'><title>Conversa Citius Pro</title>
                    <style>body { font-family: 'Inter', sans-serif; font-size: 11pt; }</style></head><body>`;
    const footer = "</body></html>";
    const fullContent = header + bodyHtml + footer;

    const blob = new Blob(['\ufeff' + fullContent], { type: 'application/msword' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = msg ? `Resposta_${msg.id}.doc` : `Conversa_Citius_Completa.doc`;
    link.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="flex flex-col h-[75vh] bg-white rounded-3xl border border-slate-200 overflow-hidden shadow-sm animate-in fade-in duration-500">
      <div className="bg-slate-900 px-8 py-5 flex items-center justify-between shrink-0">
        <div className="flex items-center space-x-4">
          <div className="p-2.5 bg-blue-600 rounded-xl shadow-lg shadow-blue-900/20">
            <Bot className="w-5 h-5 text-white" />
          </div>
          <div>
            <h4 className="text-white font-black text-sm uppercase tracking-wider">Assistente Jurídico Pro</h4>
            <div className="flex items-center gap-2">
              <div className={`w-1.5 h-1.5 rounded-full ${pdfUrl ? 'bg-green-400' : 'bg-amber-400 animate-pulse'}`} />
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">
                {pdfUrl ? 'PDF Vinculado' : 'PDF não detetado'}
              </p>
            </div>
          </div>
        </div>
        <div className="flex items-center space-x-2">
          {!pdfUrl && (
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="flex items-center gap-2 px-3 py-1.5 bg-amber-500/10 text-amber-500 border border-amber-500/20 rounded-lg text-[10px] font-black uppercase hover:bg-amber-500 hover:text-white transition-all"
            >
              <Paperclip className="w-3.5 h-3.5" /> Vincular PDF
            </button>
          )}
          <input type="file" ref={fileInputRef} className="hidden" accept=".pdf" onChange={handleFileChange} />

          <button 
            onClick={() => downloadToWord()}
            disabled={chatHistory.length === 0}
            className="p-2 text-slate-400 hover:text-white transition-colors disabled:opacity-30"
            title="Descarregar histórico para Word"
          >
            <Download className="w-5 h-5" />
          </button>
          <button 
            onClick={() => setChatHistory([])}
            className="p-2 text-slate-400 hover:text-red-400 transition-colors"
            title="Limpar conversa"
          >
            <Trash2 className="w-5 h-5" />
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-8 space-y-8 bg-slate-50/50">
        {!pdfUrl && chatHistory.length > 0 && (
           <div className="p-4 bg-amber-50 border border-amber-200 rounded-2xl flex items-start gap-3 text-amber-800 animate-in slide-in-from-top-2">
              <AlertCircle className="w-5 h-5 shrink-0 mt-0.5" />
              <div>
                <p className="text-[11px] font-black uppercase tracking-tight">Aviso de Contexto Visual</p>
                <p className="text-[12px] font-medium leading-relaxed">
                  Vincule o PDF original para abrir as páginas citadas pelo assistente.
                </p>
              </div>
           </div>
        )}

        {chatHistory.length === 0 && !isLoading && (
          <div className="h-full flex flex-col items-center justify-center text-center max-w-md mx-auto space-y-6">
            <div className="w-20 h-20 bg-blue-50 rounded-full flex items-center justify-center border-2 border-dashed border-blue-200">
              <Bot className="w-10 h-10 text-blue-300" />
            </div>
            <div>
              <h5 className="text-slate-900 font-black uppercase text-xs tracking-widest mb-2">Como posso ajudar?</h5>
              <p className="text-[12px] font-bold text-slate-400 uppercase leading-relaxed">
                Faça perguntas sobre salários, datas ou decisões.
              </p>
            </div>
            <div className="grid grid-cols-1 gap-2 w-full">
              {["Qual o valor das custas?", "Quais os fundamentos do recurso?", "Identifique o salário do trabalhador."].map(hint => (
                <button 
                  key={hint}
                  onClick={() => setInput(hint)}
                  className="px-4 py-2 bg-white border border-slate-200 rounded-xl text-[10px] font-black text-slate-500 uppercase hover:border-blue-500 hover:text-blue-600 transition-all text-left flex items-center justify-between group"
                >
                  {hint}
                  <ArrowRightCircle className="w-3.5 h-3.5 opacity-0 group-hover:opacity-100 transition-opacity" />
                </button>
              ))}
            </div>
          </div>
        )}

        {chatHistory.map((msg) => (
          <div 
            key={msg.id} 
            className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in slide-in-from-bottom-2 duration-300`}
          >
            <div className={`flex max-w-[85%] ${msg.role === 'user' ? 'flex-row-reverse space-x-reverse' : 'flex-row'} space-x-4`}>
              <div className={`shrink-0 w-10 h-10 rounded-2xl flex items-center justify-center shadow-sm border ${
                msg.role === 'user' ? 'bg-white text-slate-900 border-slate-200' : 'bg-blue-600 text-white border-blue-500'
              }`}>
                {msg.role === 'user' ? <User className="w-5 h-5" /> : <Bot className="w-5 h-5" />}
              </div>

              <div className="space-y-3">
                <div className={`p-6 rounded-[2rem] shadow-sm border ${
                  msg.role === 'user' 
                    ? 'bg-slate-900 text-white border-slate-800 rounded-tr-none' 
                    : 'bg-white text-slate-800 border-slate-100 rounded-tl-none'
                }`}>
                  <p className="text-[14px] leading-relaxed whitespace-pre-wrap font-medium">
                    {msg.content}
                  </p>

                  {msg.role === 'assistant' && msg.citations && msg.citations.length > 0 && (
                    <div className="mt-6 pt-6 border-t border-slate-100 flex flex-wrap gap-2">
                      {msg.citations.map((cite, idx) => (
                        <button 
                          key={idx}
                          onClick={() => handleOpenDoc(cite.pagina)}
                          className="flex items-center space-x-2 px-3 py-1.5 bg-blue-50 border border-blue-100 rounded-lg text-[10px] font-black text-blue-700 hover:bg-blue-600 hover:text-white transition-all group"
                        >
                          <FileText className="w-3.5 h-3.5" />
                          <span>{cite.titulo} (Pág. {cite.pagina})</span>
                          <ExternalLink className="w-3 h-3 opacity-0 group-hover:opacity-100 transition-opacity" />
                        </button>
                      ))}
                    </div>
                  )}
                </div>

                {msg.role === 'assistant' && (
                  <div className="flex items-center justify-between px-2">
                    <div className="flex items-center space-x-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">
                      {msg.metrics && (
                        <span className="flex items-center gap-1.5 bg-slate-100 px-2.5 py-1 rounded-full border border-slate-200">
                          <Cpu className="w-3 h-3 text-blue-500" />
                          {msg.metrics.totalTokens} Tokens
                        </span>
                      )}
                      <span>{new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                    </div>

                    <button 
                      onClick={() => downloadToWord(msg)}
                      className="text-[9px] font-black text-blue-600 uppercase tracking-widest hover:underline flex items-center"
                    >
                      <Download className="w-3 h-3 mr-1" /> Exportar Word
                    </button>
                  </div>
                )}
              </div>
            </div>
          </div>
        ))}

        {isLoading && (
          <div className="flex justify-start animate-in fade-in duration-300">
            <div className="flex space-x-4">
              <div className="w-10 h-10 rounded-2xl bg-blue-600 text-white flex items-center justify-center animate-pulse">
                <Bot className="w-5 h-5" />
              </div>
              <div className="bg-white p-6 rounded-[2rem] rounded-tl-none border border-slate-100 shadow-sm flex items-center space-x-3">
                <Loader2 className="w-4 h-4 animate-spin text-blue-500" />
                <span className="text-[12px] font-black text-slate-400 uppercase tracking-widest">A ler o processo...</span>
              </div>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <div className="p-6 bg-white border-t border-slate-100">
        <div className="relative max-w-4xl mx-auto flex items-end space-x-4">
          <div className="flex-1 relative">
            <textarea
              rows={1}
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' && !e.shiftKey) {
                  e.preventDefault();
                  handleSend();
                }
              }}
              placeholder="Faça uma pergunta sobre o processo..."
              className="w-full pl-6 pr-14 py-4 bg-slate-50 border-transparent focus:bg-white focus:border-blue-500 rounded-[1.5rem] text-[14px] font-medium transition-all border shadow-inner resize-none overflow-hidden"
              style={{ minHeight: '56px', maxHeight: '150px' }}
            />
          </div>
          <button 
            onClick={handleSend}
            disabled={!input.trim() || isLoading}
            className="w-14 h-14 bg-blue-600 text-white rounded-2xl flex items-center justify-center shadow-xl shadow-blue-100 hover:bg-blue-700 disabled:opacity-30 transition-all shrink-0"
          >
            <Send className="w-6 h-6" />
          </button>
        </div>
      </div>
    </div>
  );
};
